      const renderPdfSharedAudioVoiceOptions = (payload = null) => {
        if (!pdfEls || (!pdfEls.audioVoice && !pdfEls.aiNoticeVoice)) {
          return;
        }
        const select = pdfEls.audioVoice || pdfEls.aiNoticeVoice;
        const current = clean(select.value || (pdfSharedAudioMarkerById(pdfAudioMarkerEditingId) || {}).voice || PDF_SHARED_AUDIO_DEFAULT_VOICE) || PDF_SHARED_AUDIO_DEFAULT_VOICE;
        const rows = [
          { key: "edge:vi-VN-NamMinhNeural", label: "Edge | Vietnamese VN | Nam Minh" },
          { key: "kokoro_vi:diem_trinh", label: "Kokoro VI | Diem Trinh" },
          { key: "kokoro_vi:hung_thinh", label: "Kokoro VI | Hung Thinh" },
          { key: "kokoro_vi:mai_linh", label: "Kokoro VI | Mai Linh" },
          { key: "kokoro:am_adam", label: "People | Male Adam" },
          { key: "edge:en-GB-MaisieNeural", label: "Edge | English GB | Maisie" },
          { key: "edge:vi-VN-HoaiMyNeural", label: "Edge | Vietnamese VN | Hoai My" },
          { key: "sot:en-GB", label: "Sound of Text | Female UK" },
        ];
        const source = payload && typeof payload === "object" ? payload : (pdfAudioMarkerVoicePayload || {});
        const seen = new Set();
        const appendRows = (items) => {
          (Array.isArray(items) ? items : []).forEach((item) => {
            rows.push({
              key: clean(item && (item.key || item.voice || item.value || "")),
              label: clean(item && (item.label || item.name || item.key || item.voice || "")),
            });
          });
        };
        appendRows(source.vi);
        appendRows(source.en);
        pdfAudioMarkerVoiceRows = [];
        const noticeCurrent = pdfEls.aiNoticeVoice ? clean(pdfEls.aiNoticeVoice.value || current || PDF_SHARED_AUDIO_DEFAULT_VOICE) || PDF_SHARED_AUDIO_DEFAULT_VOICE : "";
        select.replaceChildren();
        if (pdfEls.aiNoticeVoice && pdfEls.aiNoticeVoice !== select) {
          pdfEls.aiNoticeVoice.replaceChildren();
        }
        rows.forEach((row) => {
          const key = clean(row.key);
          if (!key || seen.has(key.toLowerCase())) {
            return;
          }
          seen.add(key.toLowerCase());
          const option = document.createElement("option");
          option.value = key;
          option.textContent = clean(row.label) || key;
          select.appendChild(option);
          pdfAudioMarkerVoiceRows.push({ key, label: clean(row.label) || key });
          if (pdfEls.aiNoticeVoice && pdfEls.aiNoticeVoice !== select) {
            const noticeOption = document.createElement("option");
            noticeOption.value = key;
            noticeOption.textContent = clean(row.label) || key;
            pdfEls.aiNoticeVoice.appendChild(noticeOption);
          }
        });
        select.value = seen.has(current.toLowerCase()) ? current : PDF_SHARED_AUDIO_DEFAULT_VOICE;
        if (pdfEls.aiNoticeVoice) {
          pdfEls.aiNoticeVoice.value = seen.has(noticeCurrent.toLowerCase()) ? noticeCurrent : PDF_SHARED_AUDIO_DEFAULT_VOICE;
        }
        syncPdfSharedAudioVoicePicker();
      };

      const loadPdfSharedAudioVoices = async (options = {}) => {
        if (pdfAudioMarkerVoicePromise && !options.force) {
          return pdfAudioMarkerVoicePromise;
        }
        renderPdfSharedAudioVoiceOptions(pdfAudioMarkerVoicePayload || {});
        pdfAudioMarkerVoicePromise = fetchSharedChatVoices(options)
          .then(({ payload }) => {
            pdfAudioMarkerVoicePayload = payload && typeof payload === "object" ? payload : {};
            renderPdfSharedAudioVoiceOptions(pdfAudioMarkerVoicePayload);
            return pdfAudioMarkerVoicePayload;
          })
          .catch((error) => {
            if (options.force) {
              throw error;
            }
            return pdfAudioMarkerVoicePayload || {};
          })
          .finally(() => {
            pdfAudioMarkerVoicePromise = null;
          });
        return pdfAudioMarkerVoicePromise;
      };

      const positionPdfSharedAudioMarkerNode = (node, marker) => {
        if (!node || !marker || !pdfEls || !pdfEls.image) {
          return;
        }
        const width = Math.max(1, Number(pdfEls.image.clientWidth || pdfEls.wrap && pdfEls.wrap.clientWidth || 0) || 1);
        const height = Math.max(1, Number(pdfEls.image.clientHeight || pdfEls.wrap && pdfEls.wrap.clientHeight || 0) || 1);
        node.style.left = `${Math.round(width * Math.max(0, Math.min(1, Number(marker.x || 0.5))))}px`;
        node.style.top = `${Math.round(height * Math.max(0, Math.min(1, Number(marker.y || 0.5))))}px`;
      };

      const renderPdfSharedAudioMarkers = () => {
        if (!pdfEls || !pdfEls.audioLayer) {
          return;
        }
        const layer = pdfEls.audioLayer;
        layer.replaceChildren();
        layer.hidden = !(pdfModeActive && pdfState && pdfState.path);
        const markers = (Array.isArray(pdfAudioMarkers) ? pdfAudioMarkers : []).filter((item) => item && item.id);
        pdfState.audioMarkers = markers.slice();
        markers.forEach((marker) => {
          const button = document.createElement("button");
          button.type = "button";
          button.className = "ft-pdf-audio-marker";
          button.dataset.markerId = marker.id;
          const isImageMarker = pdfSharedAudioMarkerIsImage(marker);
          const imageAlways = isImageMarker && marker.displayMode === "always" && marker.audioPath;
          button.classList.toggle("is-image-marker", isImageMarker);
          button.classList.toggle("is-image-always", Boolean(imageAlways));
          button.title = marker.title || (isImageMarker ? "Shared Picture" : "Shared Media");
          button.setAttribute("aria-label", `${marker.title || (isImageMarker ? "Shared Picture" : "Shared Media")}${marker.hasAudio ? "" : " (no media yet)"}`);
          button.classList.toggle("is-playing", pdfAudioMarkerPlayingId === marker.id);
          button.classList.toggle("is-empty", !marker.hasAudio);
          button.classList.toggle("is-move-target", pdfAudioMarkerMoveId === marker.id);
          const isThisPlaying = pdfAudioMarkerPlayingId === marker.id;
          const isThisPaused = isThisPlaying && pdfAudioMarkerPlayer && pdfAudioMarkerPlayer.paused;
          button.classList.toggle("is-paused", Boolean(isThisPaused));
          button.classList.toggle("is-ended", pdfAudioMarkerEndedId === marker.id && !isThisPlaying);
          if (imageAlways) {
            const image = document.createElement("img");
            image.className = "ft-pdf-audio-marker-image";
            image.alt = marker.title || "Shared picture";
            image.src = pdfAudioMarkerAssetUrl(marker.audioPath);
            button.appendChild(image);
            if (canEditPdfSharedAudioMarkers()) {
              const resize = document.createElement("span");
              resize.className = "ft-pdf-audio-marker-image-resize";
              resize.dataset.audioAction = "resizeImage";
              resize.setAttribute("aria-hidden", "true");
              button.appendChild(resize);
            }
            const imageWidth = Math.max(44, Math.round((Number(marker.w || 0.18) || 0.18) * Math.max(1, Number(pdfEls.image.clientWidth || 1))));
            const imageHeight = Math.max(44, Math.round((Number(marker.h || 0.14) || 0.14) * Math.max(1, Number(pdfEls.image.clientHeight || 1))));
            button.style.width = `${imageWidth}px`;
            button.style.height = `${imageHeight}px`;
            positionPdfSharedAudioMarkerNode(button, marker);
            layer.appendChild(button);
            return;
          }
          const icon = document.createElement("span");
          icon.className = "ft-pdf-audio-marker-icon";
          const glyph = document.createElement("span");
          glyph.className = "ft-pdf-audio-marker-glyph";
          glyph.textContent = isImageMarker ? "▣" : (pdfAudioMarkerEndedId === marker.id ? "↻" : "▶");
          const wave = document.createElement("span");
          wave.className = "ft-pdf-audio-marker-wave";
          for (let index = 0; index < 3; index += 1) {
            const bar = document.createElement("i");
            bar.style.setProperty("--wave-index", String(index));
            wave.appendChild(bar);
          }
          icon.append(glyph, wave);
          const label = document.createElement("span");
          label.className = "ft-pdf-audio-marker-label";
          label.textContent = clean(marker.title || (isImageMarker ? "Picture" : "Media")).slice(0, 20);
          button.append(icon, label);
          const panel = document.createElement("span");
          panel.className = "ft-pdf-audio-marker-panel";
          panel.setAttribute("aria-hidden", isThisPlaying ? "false" : "true");
          const track = document.createElement("span");
          track.className = "ft-pdf-audio-marker-progress";
          track.dataset.audioAction = "seek";
          const fill = document.createElement("span");
          fill.className = "ft-pdf-audio-marker-progress-fill";
          const pin = document.createElement("span");
          pin.className = "ft-pdf-audio-marker-progress-pin";
          pin.dataset.audioAction = "pin";
          pin.setAttribute("aria-label", "Drag pinned replay time");
          const pinLabel = document.createElement("span");
          pinLabel.className = "ft-pdf-audio-marker-progress-pin-time";
          pinLabel.textContent = "0:00";
          pin.appendChild(pinLabel);
          track.append(fill, pin);
          const updatePinFromPointer = (ev) => {
            const player = pdfAudioMarkerPlayer;
            if (!player || pdfAudioMarkerPlayingId !== marker.id || Number(player.duration || 0) <= 0) {
              return;
            }
            const rect = track.getBoundingClientRect();
            const ratio = Math.max(0, Math.min(1, (Number(ev.clientX || 0) - rect.left) / Math.max(1, rect.width)));
            pdfAudioMarkerPins[marker.id] = ratio * player.duration;
            pin.style.left = `${(ratio * 100).toFixed(2)}%`;
            pinLabel.textContent = formatPdfAudioMarkerTime(pdfAudioMarkerPins[marker.id]);
            setPdfStatus(`Pinned replay at ${formatPdfAudioMarkerTime(pdfAudioMarkerPins[marker.id])}.`);
          };
          pin.addEventListener("pointerdown", (event) => {
            if (event.button != null && event.button !== 0) {
              return;
            }
            event.preventDefault();
            event.stopPropagation();
            try { pin.setPointerCapture(event.pointerId); } catch (error) {}
            updatePinFromPointer(event);
            const move = (ev) => updatePinFromPointer(ev);
            const up = (ev) => {
              try { pin.releasePointerCapture(ev.pointerId); } catch (error) {}
              pin.removeEventListener("pointermove", move);
              pin.removeEventListener("pointerup", up);
              pin.removeEventListener("pointercancel", up);
            };
            pin.addEventListener("pointermove", move);
            pin.addEventListener("pointerup", up);
            pin.addEventListener("pointercancel", up);
          });
          track.addEventListener("contextmenu", (event) => {
            if (!isThisPlaying && pdfAudioMarkerEndedId !== marker.id) {
              return;
            }
            event.preventDefault();
            event.stopPropagation();
            updatePinFromPointer(event);
          });
          track.addEventListener("pointerdown", (event) => {
            if (event.button != null && event.button !== 0) {
              return;
            }
            if (!isThisPlaying && pdfAudioMarkerEndedId !== marker.id) {
              return;
            }
            event.preventDefault();
            event.stopPropagation();
            try { track.setPointerCapture(event.pointerId); } catch (error) {}
            const seekTo = (ev) => {
              const player = pdfAudioMarkerPlayer;
              if (!player) {
                return;
              }
              const rect = track.getBoundingClientRect();
              const ratio = Math.max(0, Math.min(1, (Number(ev.clientX || 0) - rect.left) / Math.max(1, rect.width)));
              if (Number(player.duration || 0) > 0) {
                try { player.currentTime = ratio * player.duration; } catch (error) {}
              }
            };
            seekTo(event);
            const move = (ev) => seekTo(ev);
            const up = (ev) => {
              try { track.releasePointerCapture(ev.pointerId); } catch (error) {}
              track.removeEventListener("pointermove", move);
              track.removeEventListener("pointerup", up);
              track.removeEventListener("pointercancel", up);
            };
            track.addEventListener("pointermove", move);
            track.addEventListener("pointerup", up);
            track.addEventListener("pointercancel", up);
          });
          const time = document.createElement("span");
          time.className = "ft-pdf-audio-marker-time";
          time.textContent = "0:00 / 0:00";
          const pause = document.createElement("button");
          pause.type = "button";
          pause.className = "ft-pdf-audio-marker-btn is-pause";
          pause.setAttribute("aria-label", isThisPaused ? "Resume audio" : "Pause audio");
          pause.dataset.audioAction = "pause";
          pause.innerHTML = isThisPaused ? "▶" : "⏸";
          const replay = document.createElement("button");
          replay.type = "button";
          replay.className = "ft-pdf-audio-marker-btn is-replay";
          replay.setAttribute("aria-label", "Replay audio");
          replay.dataset.audioAction = "replay";
          replay.innerHTML = "↻";
          const replayPin = document.createElement("button");
          replayPin.type = "button";
          replayPin.className = "ft-pdf-audio-marker-btn is-pin-replay";
          replayPin.setAttribute("aria-label", "Replay from pinned time");
          replayPin.dataset.audioAction = "replayPin";
          replayPin.innerHTML = "⌖";
          const reset = document.createElement("button");
          reset.type = "button";
          reset.className = "ft-pdf-audio-marker-btn is-reset";
          reset.setAttribute("aria-label", "Reset audio");
          reset.dataset.audioAction = "reset";
          reset.innerHTML = "⏹";
          panel.append(track, time, pause, replay, replayPin, reset);
          button.append(panel);
          positionPdfSharedAudioMarkerNode(button, marker);
          layer.appendChild(button);
        });
        window.requestAnimationFrame(() => updatePdfSharedAudioPopoverConnector());
      };

      const clearPdfAudioMarkerAutoReset = () => {
        if (pdfAudioMarkerAutoResetTimer) {
          window.clearTimeout(pdfAudioMarkerAutoResetTimer);
          pdfAudioMarkerAutoResetTimer = 0;
        }
      };
      const clearPdfAudioMarkerProgressRaf = () => {
        if (pdfAudioMarkerProgressRaf) {
          window.cancelAnimationFrame(pdfAudioMarkerProgressRaf);
          pdfAudioMarkerProgressRaf = 0;
        }
      };

      const closePdfAudioMarkerVideoPopup = () => {
        if (pdfAudioMarkerVideoPopup) {
          try { pdfAudioMarkerVideoPopup.remove(); } catch (error) {}
        }
        if (pdfAudioMarkerVideoConnector) {
          try { pdfAudioMarkerVideoConnector.remove(); } catch (error) {}
        }
        pdfAudioMarkerVideoPopup = null;
        pdfAudioMarkerVideoConnector = null;
      };

      const positionPdfAudioMarkerVideoPopup = () => {
        if (!pdfAudioMarkerVideoPopup || !pdfAudioMarkerVideoConnector || !pdfAudioMarkerPlayingId) {
          return;
        }
        const markerNode = pdfEls && pdfEls.audioLayer
          ? pdfEls.audioLayer.querySelector(`.ft-pdf-audio-marker[data-marker-id="${cssEscapeAttr(pdfAudioMarkerPlayingId)}"]`)
          : null;
        const markerRect = markerNode ? markerNode.getBoundingClientRect() : null;
        const viewportW = Math.max(1, window.innerWidth || document.documentElement.clientWidth || 1);
        const viewportH = Math.max(1, window.innerHeight || document.documentElement.clientHeight || 1);
        const width = Math.min(Math.max(360, Math.round(viewportW * 0.48)), Math.max(280, viewportW - 28));
        const height = Math.min(Math.round(width * 0.62) + 58, Math.max(240, viewportH - 34));
        let left = Math.round((viewportW - width) / 2);
        let top = Math.round((viewportH - height) / 2);
        if (markerRect) {
          const preferTop = markerRect.top > viewportH * 0.55;
          top = preferTop
            ? Math.max(14, Math.round(markerRect.top - height - 22))
            : Math.min(viewportH - height - 14, Math.round(markerRect.bottom + 22));
          left = Math.max(14, Math.min(viewportW - width - 14, Math.round(markerRect.left + markerRect.width / 2 - width / 2)));
        }
        pdfAudioMarkerVideoPopup.style.left = `${left}px`;
        pdfAudioMarkerVideoPopup.style.top = `${top}px`;
        pdfAudioMarkerVideoPopup.style.width = `${width}px`;
        pdfAudioMarkerVideoPopup.style.maxHeight = `${height}px`;
        if (markerRect) {
          const startX = Math.round(markerRect.left + markerRect.width / 2);
          const startY = Math.round(markerRect.top + markerRect.height / 2);
          const endX = Math.round(left + width / 2);
          const endY = Math.round(top + (top > markerRect.top ? 0 : height));
          const dx = endX - startX;
          const dy = endY - startY;
          const length = Math.max(24, Math.sqrt(dx * dx + dy * dy));
          const angle = Math.atan2(dy, dx) * 180 / Math.PI;
          pdfAudioMarkerVideoConnector.style.left = `${startX}px`;
          pdfAudioMarkerVideoConnector.style.top = `${startY}px`;
          pdfAudioMarkerVideoConnector.style.width = `${length}px`;
          pdfAudioMarkerVideoConnector.style.transform = `rotate(${angle}deg)`;
          pdfAudioMarkerVideoConnector.classList.remove("is-hidden");
        } else {
          pdfAudioMarkerVideoConnector.classList.add("is-hidden");
        }
      };

      const openPdfAudioMarkerVideoPopup = (marker = null, player = null) => {
        if (!marker || !player || player.tagName !== "VIDEO") {
          closePdfAudioMarkerVideoPopup();
          return;
        }
        if (!pdfAudioMarkerVideoPopup) {
          pdfAudioMarkerVideoConnector = document.createElement("span");
          pdfAudioMarkerVideoConnector.className = "ft-pdf-audio-video-connector";
          pdfAudioMarkerVideoPopup = document.createElement("aside");
          pdfAudioMarkerVideoPopup.className = "ft-pdf-audio-video-popover";
          pdfAudioMarkerVideoPopup.setAttribute("role", "dialog");
          pdfAudioMarkerVideoPopup.innerHTML = `
            <div class="ft-pdf-audio-video-head">
              <span class="ft-pdf-audio-video-title"></span>
              <button type="button" class="ft-pdf-audio-video-close" aria-label="Close video">x</button>
            </div>
            <div class="ft-pdf-audio-video-body"></div>
          `;
          document.body.append(pdfAudioMarkerVideoConnector, pdfAudioMarkerVideoPopup);
          pdfAudioMarkerVideoPopup.querySelector(".ft-pdf-audio-video-close").addEventListener("click", (event) => {
            event.preventDefault();
            event.stopPropagation();
            resetPdfAudioMarkerToInitial();
          });
        }
        const title = pdfAudioMarkerVideoPopup.querySelector(".ft-pdf-audio-video-title");
        const body = pdfAudioMarkerVideoPopup.querySelector(".ft-pdf-audio-video-body");
        if (title) {
          title.textContent = clean(marker.title || "Shared video");
        }
        if (body && player.parentNode !== body) {
          body.replaceChildren(player);
        }
        pdfAudioMarkerVideoPopup.dataset.markerId = marker.id;
        window.requestAnimationFrame(positionPdfAudioMarkerVideoPopup);
      };

      // Added 2026-07-02: opens shared picture media from PDF/Picture markers without using an audio player.
      const openPdfAudioMarkerImagePopup = (marker = null) => {
        if (!marker || !marker.audioPath) {
          return;
        }
        stopPdfSharedAudioPlayback({ resetEnded: true });
        if (!pdfAudioMarkerVideoPopup) {
          pdfAudioMarkerVideoConnector = document.createElement("span");
          pdfAudioMarkerVideoConnector.className = "ft-pdf-audio-video-connector";
          pdfAudioMarkerVideoPopup = document.createElement("aside");
          pdfAudioMarkerVideoPopup.className = "ft-pdf-audio-video-popover is-image-media";
          pdfAudioMarkerVideoPopup.setAttribute("role", "dialog");
          pdfAudioMarkerVideoPopup.innerHTML = `
            <div class="ft-pdf-audio-video-head">
              <span class="ft-pdf-audio-video-title"></span>
              <button type="button" class="ft-pdf-audio-video-close" aria-label="Close picture">x</button>
            </div>
            <div class="ft-pdf-audio-video-body"></div>
          `;
          document.body.append(pdfAudioMarkerVideoConnector, pdfAudioMarkerVideoPopup);
          pdfAudioMarkerVideoPopup.querySelector(".ft-pdf-audio-video-close").addEventListener("click", (event) => {
            event.preventDefault();
            event.stopPropagation();
            closePdfAudioMarkerVideoPopup();
          });
        }
        pdfAudioMarkerVideoPopup.classList.add("is-image-media");
        pdfAudioMarkerVideoPopup.classList.remove("is-web-embed");
        const title = pdfAudioMarkerVideoPopup.querySelector(".ft-pdf-audio-video-title");
        const body = pdfAudioMarkerVideoPopup.querySelector(".ft-pdf-audio-video-body");
        if (title) {
          title.textContent = clean(marker.title || "Shared picture");
        }
        if (body) {
          const image = document.createElement("img");
          image.className = "ft-pdf-audio-popup-image";
          image.alt = marker.title || "Shared picture";
          image.src = pdfAudioMarkerAssetUrl(marker.audioPath);
          body.replaceChildren(image);
        }
        pdfAudioMarkerVideoPopup.dataset.markerId = marker.id;
        window.requestAnimationFrame(positionPdfAudioMarkerVideoPopup);
      };

      const resetPdfAudioMarkerToInitial = () => {
        clearPdfAudioMarkerAutoReset();
        clearPdfAudioMarkerProgressRaf();
        closePdfAudioMarkerVideoPopup();
        if (pdfAudioMarkerPlayer) {
          try { pdfAudioMarkerPlayer.pause(); } catch (error) {}
          try { pdfAudioMarkerPlayer.removeAttribute("src"); pdfAudioMarkerPlayer.load(); } catch (error) {}
        }
        pdfAudioMarkerPlayer = null;
        pdfAudioMarkerPlayingId = "";
        pdfAudioMarkerEndedId = "";
        renderPdfSharedAudioMarkers();
      };
      const formatPdfAudioMarkerTime = (seconds = 0) => {
        const total = Math.max(0, Math.floor(Number(seconds) || 0));
        const minutes = Math.floor(total / 60);
        const secs = total % 60;
        return `${minutes}:${secs < 10 ? "0" : ""}${secs}`;
      };
      const cssEscapeAttr = (value = "") => {
        const text = clean(value);
        if (window.CSS && CSS.escape) {
          return CSS.escape(text);
        }
        return text.replace(/["\\]/g, "\\$&");
      };
      const updatePdfAudioMarkerProgress = () => {
        clearPdfAudioMarkerProgressRaf();
        const player = pdfAudioMarkerPlayer;
        const markerId = pdfAudioMarkerPlayingId;
        if (!player || !markerId || !pdfEls || !pdfEls.audioLayer) {
          return;
        }
        const node = pdfEls.audioLayer.querySelector(`.ft-pdf-audio-marker[data-marker-id="${cssEscapeAttr(markerId)}"]`);
        if (!node) {
          return;
        }
        const fill = node.querySelector(".ft-pdf-audio-marker-progress-fill");
        const pin = node.querySelector(".ft-pdf-audio-marker-progress-pin");
        const time = node.querySelector(".ft-pdf-audio-marker-time");
        const current = Math.max(0, Number(player.currentTime || 0) || 0);
        const duration = Math.max(0, Number(player.duration || 0) || 0);
        const percent = duration > 0 ? Math.min(100, Math.max(0, (current / duration) * 100)) : 0;
        if (fill) {
          fill.style.width = `${percent.toFixed(2)}%`;
        }
        if (pin) {
          const storedPin = Math.max(0, Number(pdfAudioMarkerPins[markerId] || 0) || 0);
          const pinTime = duration > 0 ? Math.min(duration, storedPin) : 0;
          const pinPercent = duration > 0 ? Math.min(100, Math.max(0, (pinTime / duration) * 100)) : 0;
          pin.style.left = `${pinPercent.toFixed(2)}%`;
          pin.classList.toggle("is-set", pinTime > 0);
          const pinLabel = pin.querySelector(".ft-pdf-audio-marker-progress-pin-time");
          if (pinLabel) {
            pinLabel.textContent = formatPdfAudioMarkerTime(pinTime);
          }
        }
        if (time) {
          time.textContent = `${formatPdfAudioMarkerTime(current)} / ${formatPdfAudioMarkerTime(duration)}`;
        }
        if (pdfAudioMarkerVideoPopup) {
          positionPdfAudioMarkerVideoPopup();
        }
        pdfAudioMarkerProgressRaf = window.requestAnimationFrame(updatePdfAudioMarkerProgress);
      };
      const schedulePdfAudioMarkerAutoReset = (markerId = "", delayMs = 5000) => {
        clearPdfAudioMarkerAutoReset();
        if (!markerId) {
          return;
        }
        pdfAudioMarkerAutoResetTimer = window.setTimeout(() => {
          pdfAudioMarkerAutoResetTimer = 0;
          if (pdfAudioMarkerEndedId === markerId && !pdfAudioMarkerPlayer) {
            pdfAudioMarkerEndedId = "";
            renderPdfSharedAudioMarkers();
          }
        }, Math.max(0, Number(delayMs) || 5000));
      };
      const stopPdfSharedAudioPlayback = (options = {}) => {
        clearPdfAudioMarkerProgressRaf();
        closePdfAudioMarkerVideoPopup();
        if (pdfAudioMarkerPlayer) {
          try {
            pdfAudioMarkerPlayer.pause();
          } catch (error) {
          }
          try {
            pdfAudioMarkerPlayer.removeAttribute("src");
            pdfAudioMarkerPlayer.load();
          } catch (error) {
          }
        }
        pdfAudioMarkerPlayer = null;
        if (!options.keepId) {
          pdfAudioMarkerPlayingId = "";
          pdfAudioMarkerPlayingPage = 0;
        }
        if (options.resetEnded) {
          pdfAudioMarkerEndedId = "";
          clearPdfAudioMarkerAutoReset();
        }
        renderPdfSharedAudioMarkers();
      };

      const replayPdfSharedAudioMarker = async (markerId = "") => {
        const marker = pdfSharedAudioMarkerById(markerId);
        if (!marker || !marker.audioPath) {
          return;
        }
        if (pdfSharedAudioMarkerIsWebEmbed(marker)) {
          stopPdfSharedAudioPlayback({ resetEnded: true });
          pdfAudioMarkerPlayingId = marker.id;
          pdfAudioMarkerEndedId = "";
          renderPdfSharedAudioMarkers();
          openPdfAudioMarkerWebPopup(marker);
          setPdfStatus(`Opened ${marker.title || "shared web media"}.`);
          return;
  }
        clearPdfAudioMarkerAutoReset();
        stopPdfSharedAudioPlayback({ resetEnded: true });
        if (pdfAudioPlayer) {
          try { pdfAudioPlayer.pause(); } catch (error) {}
        }
        const player = createPdfSharedMediaPlayer(marker);
        pdfAudioMarkerPlayer = player;
        pdfAudioMarkerPlayingId = marker.id;
        pdfAudioMarkerPlayingPage = pdfState ? pdfState.page : 0;
        pdfAudioMarkerEndedId = "";
        normalizeAudioPlaybackSpeed(player);
        player.onended = () => {
          const endedId = marker.id;
          stopPdfSharedAudioPlayback({ keepId: true });
          pdfAudioMarkerPlayingId = "";
          pdfAudioMarkerPlayingPage = 0;
          pdfAudioMarkerEndedId = endedId;
          renderPdfSharedAudioMarkers();
          schedulePdfAudioMarkerAutoReset(endedId, 5000);
        };
        player.onerror = () => {
          stopPdfSharedAudioPlayback({ resetEnded: true });
          if (player.tagName === "VIDEO") {
            void transcodePdfSharedVideoMarkerForBrowser(marker)
              .then((converted) => {
                if (converted) {
                  void replayPdfSharedAudioMarker(marker.id);
                } else {
                  setPdfStatus("Could not load this video. The file may use a codec your browser cannot play.", true);
                }
              })
              .catch((error) => {
                setPdfStatus(error && error.message ? error.message : "Could not convert this video for browser playback.", true);
              });
            return;
          }
          setPdfStatus(player.tagName === "VIDEO" ? "Could not load this video. The file may use a codec your browser cannot play." : "Could not play this shared media marker.", true);
        };
        renderPdfSharedAudioMarkers();
        openPdfAudioMarkerVideoPopup(marker, player);
        clearPdfAudioMarkerProgressRaf();
        pdfAudioMarkerProgressRaf = window.requestAnimationFrame(updatePdfAudioMarkerProgress);
        try {
          await player.play();
          setPdfStatus(`Replaying ${marker.title || "shared audio"}.`);
        } catch (error) {
          stopPdfSharedAudioPlayback({ resetEnded: true });
          setPdfStatus(error && error.message ? error.message : "Could not play this shared media marker.", true);
        }
      };

      const togglePdfSharedAudioMarkerPause = async (markerId = "") => {
        const marker = pdfSharedAudioMarkerById(markerId);
        const player = pdfAudioMarkerPlayer;
        if (!marker || !player || pdfAudioMarkerPlayingId !== marker.id) {
          await playPdfSharedAudioMarker(markerId);
          return;
        }
        if (player.paused) {
          try {
            await player.play();
            clearPdfAudioMarkerProgressRaf();
            pdfAudioMarkerProgressRaf = window.requestAnimationFrame(updatePdfAudioMarkerProgress);
            renderPdfSharedAudioMarkers();
            window.requestAnimationFrame(updatePdfAudioMarkerProgress);
            setPdfStatus(`Resumed ${marker.title || "shared audio"}.`);
          } catch (error) {
            setPdfStatus(error && error.message ? error.message : "Could not resume this shared media marker.", true);
          }
          return;
        }
        try {
          player.pause();
        } catch (error) {
        }
        renderPdfSharedAudioMarkers();
        window.requestAnimationFrame(updatePdfAudioMarkerProgress);
        setPdfStatus(`Paused at ${formatPdfAudioMarkerTime(player.currentTime || 0)}.`);
      };

      const replayPdfSharedAudioMarkerFromPin = async (markerId = "") => {
        const marker = pdfSharedAudioMarkerById(markerId);
        if (!marker || !marker.audioPath) {
          return;
        }
        const pinTime = Math.max(0, Number(pdfAudioMarkerPins[marker.id] || 0) || 0);
        if (!pinTime) {
          setPdfStatus("Drag the pin on the progress bar first.", true);
          return;
        }
        await replayPdfSharedAudioMarker(marker.id);
        if (pdfAudioMarkerPlayer) {
          const applyPin = () => {
            const duration = Math.max(0, Number(pdfAudioMarkerPlayer && pdfAudioMarkerPlayer.duration || 0) || 0);
            if (duration > 0) {
              try { pdfAudioMarkerPlayer.currentTime = Math.min(duration, pinTime); } catch (error) {}
              setPdfStatus(`Replaying from ${formatPdfAudioMarkerTime(Math.min(duration, pinTime))}.`);
            }
          };
          if (Number(pdfAudioMarkerPlayer.duration || 0) > 0) {
            applyPin();
          } else {
            pdfAudioMarkerPlayer.addEventListener("loadedmetadata", applyPin, { once: true });
          }
        }
      };

      const PDF_AUDIO_LOCAL_SERVER_KEY = "future_pdf_audio_local_server";
      const pdfAudioLocalServerOn = () => {
        try { return localStorage.getItem(PDF_AUDIO_LOCAL_SERVER_KEY) === "1"; } catch (error) { return false; }
      };
      const setPdfAudioLocalServer = (on) => {
        try { if (on) { localStorage.setItem(PDF_AUDIO_LOCAL_SERVER_KEY, "1"); } else { localStorage.removeItem(PDF_AUDIO_LOCAL_SERVER_KEY); } } catch (error) {}
      };
      const pdfAudioMarkerAssetUrl = (audioPath = "") => {
        const raw = clean(audioPath);
        if (!raw) {
          return "";
        }
        if (/^https?:\/\//i.test(raw) || raw.startsWith("data:") || raw.startsWith("blob:")) {
          return raw;
        }
        const relative = raw.replace(/^\/+/, "");
        if (!pdfAudioLocalServerOn()) {
          return serverAssetUrl(raw);
        }
        const base = clean(window.location.origin) || `http://127.0.0.1:${clean(WHISPER_SERVER_PORT) || "8877"}`;
        return raw.startsWith("/") ? `${base}${raw}` : `${base}/server-data/asset?path=${encodeURIComponent(relative)}`;
      };

      const pdfSharedAudioMarkerIsVideo = (marker = null) => {
        const item = marker && typeof marker === "object" ? marker : {};
        if (clean(item.mediaKind || "").toLowerCase() === "video") {
          return true;
        }
        const mime = clean(item.audioMime || item.audio_mime || "").toLowerCase();
        const path = clean(item.audioPath || item.audio_path || "").toLowerCase().split("?")[0];
        return mime.startsWith("video/") || /\.(mp4|m4v|webm|ogv|ogg|mov|avi|mkv|wmv|flv|mpeg|mpg|m2ts|mts|ts|3gp|3g2|vob|asf|rm|rmvb|divx|f4v)$/i.test(path);
      };

      const pdfSharedAudioMarkerIsDirectMediaUrl = (marker = null) => {
        const item = marker && typeof marker === "object" ? marker : {};
        const mime = clean(item.audioMime || item.audio_mime || "").toLowerCase();
        const path = clean(item.audioPath || item.audio_path || "").toLowerCase().split("?")[0];
        return mime.startsWith("audio/") || mime.startsWith("video/")
          || /\.(mp3|wav|m4a|ogg|oga|webm|aac|flac|opus|aiff|aif|amr|caf|3gp|3g2|mp4|m4v|mov|avi|mkv|wmv|flv|mpeg|mpg|m2ts|mts|ts|ogv|vob|asf|rm|rmvb|divx|f4v)$/i.test(path);
      };

      const pdfSharedAudioMarkerIsWebEmbed = (marker = null) => {
        const raw = clean(marker && marker.audioPath || "");
        if (clean(marker && marker.mediaKind || "").toLowerCase() === "url") {
          return /^https?:\/\//i.test(raw);
        }
        return /^https?:\/\//i.test(raw) && !pdfSharedAudioMarkerIsDirectMediaUrl(marker);
      };

      const createPdfSharedMediaPlayer = (marker = null) => {
        const src = pdfAudioMarkerAssetUrl(marker && marker.audioPath);
        if (pdfSharedAudioMarkerIsVideo(marker)) {
          const video = document.createElement("video");
          video.className = "ft-pdf-audio-marker-video";
          video.src = src;
          video.playsInline = true;
          video.preload = "metadata";
          video.controls = false;
          return video;
        }
        return new Audio(src);
      };

      const pdfSharedAudioEmbedUrl = (url = "") => {
        const raw = clean(url);
        const youtube = raw.match(/(?:youtube\.com\/watch\?v=|youtu\.be\/|youtube\.com\/shorts\/)([A-Za-z0-9_-]{6,})/i);
        if (youtube) {
          return `https://www.youtube.com/embed/${encodeURIComponent(youtube[1])}`;
        }
        return raw;
      };

      const openPdfAudioMarkerWebPopup = (marker = null) => {
        if (!marker || !marker.audioPath) {
          return;
        }
        if (!pdfAudioMarkerVideoPopup) {
          pdfAudioMarkerVideoConnector = document.createElement("span");
          pdfAudioMarkerVideoConnector.className = "ft-pdf-audio-video-connector";
          pdfAudioMarkerVideoPopup = document.createElement("aside");
          pdfAudioMarkerVideoPopup.className = "ft-pdf-audio-video-popover is-web-embed";
          pdfAudioMarkerVideoPopup.setAttribute("role", "dialog");
          pdfAudioMarkerVideoPopup.innerHTML = `
            <div class="ft-pdf-audio-video-head">
              <span class="ft-pdf-audio-video-title"></span>
              <a class="ft-pdf-audio-video-open" target="_blank" rel="noopener noreferrer">Open</a>
              <button type="button" class="ft-pdf-audio-video-close" aria-label="Close web media">x</button>
            </div>
            <div class="ft-pdf-audio-video-body"></div>
          `;
          document.body.append(pdfAudioMarkerVideoConnector, pdfAudioMarkerVideoPopup);
          pdfAudioMarkerVideoPopup.querySelector(".ft-pdf-audio-video-close").addEventListener("click", (event) => {
            event.preventDefault();
            event.stopPropagation();
            resetPdfAudioMarkerToInitial();
          });
        }
        const title = pdfAudioMarkerVideoPopup.querySelector(".ft-pdf-audio-video-title");
        const open = pdfAudioMarkerVideoPopup.querySelector(".ft-pdf-audio-video-open");
        const body = pdfAudioMarkerVideoPopup.querySelector(".ft-pdf-audio-video-body");
        const rawUrl = clean(marker.audioPath);
        if (title) title.textContent = clean(marker.title || "Shared web media");
        if (open) open.href = rawUrl;
        if (body) {
          const iframe = document.createElement("iframe");
          iframe.className = "ft-pdf-audio-web-frame";
          iframe.src = pdfSharedAudioEmbedUrl(rawUrl);
          iframe.allow = "autoplay; fullscreen; picture-in-picture; encrypted-media";
          iframe.referrerPolicy = "no-referrer-when-downgrade";
          body.replaceChildren(iframe);
        }
        pdfAudioMarkerVideoPopup.dataset.markerId = marker.id;
        window.requestAnimationFrame(positionPdfAudioMarkerVideoPopup);
      };

      const transcodePdfSharedVideoMarkerForBrowser = async (marker = null) => {
        if (!marker || !marker.id || !marker.audioPath || !currentAuthIsAdmin) {
          return false;
        }
        const sourcePath = clean(marker.audioPath || "").toLowerCase().split("?", 1)[0];
        if (/\.(mp4|m4v|webm)$/i.test(sourcePath)) {
          return false;
        }
        if (pdfAudioMarkerTranscodeRetry[marker.id]) {
          return false;
        }
        pdfAudioMarkerTranscodeRetry[marker.id] = true;
        const scope = currentPdfSharedAudioScope();
        setPdfStatus("Converting this video to browser-compatible WebM...");
        const { payload } = await fetchAuthJson("/space-pdf/audio-marker-server-file?client_source=pdf_audio_marker_server_file", {
          method: "POST",
          body: JSON.stringify({
            path: scope.path,
            mode: scope.mode,
            page: scope.page,
            id: marker.id,
            server_path: marker.audioPath,
            text: marker.text || "",
            voice: marker.voice || PDF_SHARED_AUDIO_DEFAULT_VOICE,
          }),
          timeoutMs: 0,
        });
        applyPdfSharedAudioPayload(payload || {});
        return true;
      };

      const playPdfSharedAudioMarker = async (markerId = "") => {
        const marker = pdfSharedAudioMarkerById(markerId);
        if (!marker) {
          return;
        }
        if (!marker.audioPath) {
          setPdfStatus("This shared media marker has no file yet.", true);
          return;
        }
        if (pdfSharedAudioMarkerIsImage(marker)) {
          openPdfAudioMarkerImagePopup(marker);
          setPdfStatus(`Opened ${marker.title || "shared picture"}.`);
          return;
        }
        if (pdfSharedAudioMarkerIsWebEmbed(marker)) {
          stopPdfSharedAudioPlayback({ resetEnded: true });
          pdfAudioMarkerPlayingId = marker.id;
          pdfAudioMarkerEndedId = "";
          renderPdfSharedAudioMarkers();
          openPdfAudioMarkerWebPopup(marker);
          setPdfStatus(`Opened ${marker.title || "shared web media"}.`);
          return;
        }
        if (pdfAudioMarkerPlayingId === marker.id && pdfAudioMarkerPlayer && !pdfAudioMarkerPlayer.paused) {
          setPdfStatus(`${marker.title || "Shared audio"} is already playing.`);
          return;
        }
        if (pdfAudioMarkerPlayingId === marker.id && pdfAudioMarkerPlayer && pdfAudioMarkerPlayer.paused) {
          await togglePdfSharedAudioMarkerPause(marker.id);
          return;
        }
        stopPdfSharedAudioPlayback();
        if (pdfAudioPlayer) {
          try {
            pdfAudioPlayer.pause();
          } catch (error) {
          }
        }
        const player = createPdfSharedMediaPlayer(marker);
        pdfAudioMarkerPlayer = player;
        pdfAudioMarkerPlayingId = marker.id;
        pdfAudioMarkerPlayingPage = pdfState ? pdfState.page : 0;
        pdfAudioMarkerEndedId = "";
        normalizeAudioPlaybackSpeed(player);
        player.onended = () => {
          const endedId = marker.id;
          stopPdfSharedAudioPlayback({ keepId: true });
          pdfAudioMarkerPlayingId = "";
          pdfAudioMarkerPlayingPage = 0;
          pdfAudioMarkerEndedId = endedId;
          renderPdfSharedAudioMarkers();
          schedulePdfAudioMarkerAutoReset(endedId, 5000);
        };
        player.onerror = () => {
          stopPdfSharedAudioPlayback({ resetEnded: true });
          if (player.tagName === "VIDEO") {
            void transcodePdfSharedVideoMarkerForBrowser(marker)
              .then((converted) => {
                if (converted) {
                  void playPdfSharedAudioMarker(marker.id);
                } else {
                  setPdfStatus("Could not load this video. The file may use a codec your browser cannot play.", true);
                }
              })
              .catch((error) => {
                setPdfStatus(error && error.message ? error.message : "Could not convert this video for browser playback.", true);
              });
            return;
          }
          setPdfStatus(player.tagName === "VIDEO" ? "Could not load this video. The file may use a codec your browser cannot play." : "Could not play this shared media marker.", true);
        };
        renderPdfSharedAudioMarkers();
        openPdfAudioMarkerVideoPopup(marker, player);
        clearPdfAudioMarkerProgressRaf();
        pdfAudioMarkerProgressRaf = window.requestAnimationFrame(updatePdfAudioMarkerProgress);
        try {
          await player.play();
          setPdfStatus(`Playing ${marker.title || "shared audio"}.`);
        } catch (error) {
          stopPdfSharedAudioPlayback();
          setPdfStatus(error && error.message ? error.message : "Could not play this shared media marker.", true);
        }
      };

      const syncPdfSharedAudioUi = () => {
        const active = canEditPdfSharedAudioMarkers();
        if (!active) {
          pdfAudioInsertActive = false;
          pdfAudioMarkerMoveId = "";
          closePdfSharedAudioPopover({ silent: true });
        }
        if (pdfEls && pdfEls.audioToggle) {
          pdfEls.audioToggle.setAttribute("data-pdf-tool-kind", "media");
          pdfEls.audioToggle.hidden = !active;
          pdfEls.audioToggle.style.display = active ? "" : "none";
          pdfEls.audioToggle.disabled = !active;
          pdfEls.audioToggle.setAttribute("aria-hidden", active ? "false" : "true");
          pdfEls.audioToggle.classList.toggle("is-admin-visible", active);
          pdfEls.audioToggle.classList.toggle("is-active", Boolean(active && pdfAudioInsertActive));
          pdfEls.audioToggle.setAttribute("aria-pressed", active && pdfAudioInsertActive ? "true" : "false");
          pdfEls.audioToggle.textContent = "Insert Media";
          pdfEls.audioToggle.title = active && pdfAudioInsertActive ? "Click the page to place a shared media marker." : "Insert shared media marker";
        }
        if (typeof pdfCompactAudio !== "undefined" && pdfCompactAudio) {
          pdfCompactAudio.setAttribute("data-pdf-tool-kind", "media");
          pdfCompactAudio.hidden = !active;
          pdfCompactAudio.style.display = active ? "" : "none";
          pdfCompactAudio.disabled = !active;
          pdfCompactAudio.setAttribute("aria-hidden", active ? "false" : "true");
          pdfCompactAudio.classList.toggle("is-admin-visible", active);
          pdfCompactAudio.classList.toggle("is-active", Boolean(active && pdfAudioInsertActive));
          pdfCompactAudio.setAttribute("aria-pressed", active && pdfAudioInsertActive ? "true" : "false");
          pdfCompactAudio.title = active && pdfAudioInsertActive ? "Click the page to place a shared media marker." : "Insert shared media marker";
        }
        if (pdfEls && pdfEls.root) {
          pdfEls.root.classList.toggle("is-audio-insert-active", Boolean(active && pdfAudioInsertActive));
          pdfEls.root.classList.toggle("is-audio-move-active", Boolean(active && pdfAudioMarkerMoveId));
        }
        renderPdfSharedAudioMarkers();
      };

      const togglePdfSharedAudioInsertMode = (active = !pdfAudioInsertActive, options = {}) => {
        if (!canEditPdfSharedAudioMarkers()) {
          pdfAudioInsertActive = false;
          syncPdfSharedAudioUi();
          setPdfStatus("Insert Media needs admin access and an opened PDF/Picture file.", true);
          return false;
        }
        const next = Boolean(active);
        pdfAudioInsertActive = next;
        if (next) {
          pdfAudioMarkerMoveId = "";
          closePdfSharedAudioPopover({ silent: true });
          if (pdfPenActive) togglePdfPenMode(false);
          if (pdfEraserActive) togglePdfEraserMode(false);
          if (pdfTextActive) togglePdfTextMode(false);
          setPdfSelectionArmed(false);
          setPdfStatus("Insert Media is on. Click the PDF/Picture to place one shared media marker.");
        } else if (!options.silent) {
          setPdfStatus("Insert Media is off.");
        }
        syncPdfSharedAudioUi();
        schedulePdfUiSettingsSave();
        return next;
      };

      const applyPdfSharedAudioPayload = (payload = {}) => {
        const source = payload && typeof payload === "object" ? payload : {};
        const rows = Array.isArray(source.markers) ? source.markers : [];
        pdfAudioMarkers = rows.map((item) => normalizePdfSharedAudioMarker(item)).filter((item) => item.id);
        const scope = currentPdfSharedAudioScope();
        const cacheKey = pdfPageSideDataCacheKey(scope);
        pdfAudioMarkerCache[cacheKey] = pdfAudioMarkers.slice();
        renderPdfSharedAudioMarkers();
        return pdfAudioMarkers;
      };

      const pdfPageSideDataCacheKey = (scope = {}) => {
        const source = scope && typeof scope === "object" ? scope : {};
        return [
          clean(source.lesson_id || source.lessonId || "") || normalizeServerPathValue(source.path || ""),
          clean(source.mode || "pdf") === "picture" ? "picture" : clean(source.mode || "pdf") || "pdf",
          Math.max(1, Math.floor(Number(source.page || 1) || 1)),
        ].join("|");
      };

      const loadPdfSharedAudioMarkers = async (options = {}) => {
        if (!pdfModeActive || !pdfState || !pdfState.path) {
          pdfAudioMarkers = [];
          renderPdfSharedAudioMarkers();
          return [];
        }
        const scope = currentPdfSharedAudioScope();
        const cacheKey = pdfPageSideDataCacheKey(scope);
        const cached = pdfAudioMarkerCache[cacheKey];
        if (cached) {
          pdfAudioMarkers = cached.slice();
          renderPdfSharedAudioMarkers();
          if (!options.force) {
            return pdfAudioMarkers;
          }
        }
        if (pdfAudioMarkerLoadInflight[cacheKey]) {
          return pdfAudioMarkerLoadInflight[cacheKey];
        }
        const requestToken = ++pdfAudioMarkerLoadToken;
        const query = new URLSearchParams();
        query.set("path", scope.path);
        if (scope.lesson_id) query.set("lesson_id", scope.lesson_id);
        if (clean(pdfState && pdfState.lessonHandle || "")) query.set("lesson_handle", clean(pdfState.lessonHandle));
        query.set("page", String(scope.page));
        query.set("mode", scope.mode);
        query.set("client_source", clean(options.clientSource || "pdf_side_data_audio_markers"));
        const promise = (async () => {
          const { payload } = await fetchAuthJson(`/space-pdf/audio-markers?${query.toString()}`);
          if (requestToken !== pdfAudioMarkerLoadToken || !isSamePdfSharedAudioScope(scope)) {
            return [];
          }
          const markers = applyPdfSharedAudioPayload(payload || {});
          pdfAudioMarkerCache[cacheKey] = markers.slice();
          return markers;
        })();
        pdfAudioMarkerLoadInflight[cacheKey] = promise;
        try {
          return await promise;
        } catch (error) {
          if (requestToken === pdfAudioMarkerLoadToken && isSamePdfSharedAudioScope(scope)) {
            pdfAudioMarkers = [];
            renderPdfSharedAudioMarkers();
            delete pdfAudioMarkerCache[cacheKey];
          }
          return [];
        } finally {
          if (pdfAudioMarkerLoadInflight[cacheKey] === promise) {
            delete pdfAudioMarkerLoadInflight[cacheKey];
          }
        }
      };

      const currentPdfAiRegionNoticeScope = () => ({
        path: normalizeServerPathValue(pdfState && pdfState.path || ""),
        lesson_id: clean(pdfState && pdfState.lessonId || ""),
        mode: pdfState && pdfState.mode === "picture" ? "picture" : "pdf",
        page: Math.max(1, Math.floor(Number(pdfState && pdfState.page || 1) || 1)),
      });

      const isSamePdfAiRegionNoticeScope = (scope = null) => {
        const current = currentPdfAiRegionNoticeScope();
        const source = scope && typeof scope === "object" ? scope : {};
        return current.path === normalizeServerPathValue(source.path || "")
          && current.mode === (clean(source.mode || "pdf") === "picture" ? "picture" : "pdf")
          && current.page === Math.max(1, Math.floor(Number(source.page || 1) || 1));
      };

      const preservePdfAiNoticeText = (value = "", limit = 0) => {
        const text = String(value || "").replace(/\r\n?/g, "\n");
        return limit && limit > 0 ? text.slice(0, limit) : text;
      };

      const normalizePdfAiRegionNotice = (raw = {}) => {
        const source = raw && typeof raw === "object" ? raw : {};
        const rect = normalizePdfSelectionState(source.rect || source.selection || source);
        const text = preservePdfAiNoticeText(source.text || source.notice || source.message || "");
        if (!rect || !text) {
          return null;
        }
        const scope = currentPdfAiRegionNoticeScope();
        const rawUnion = source.unionRects || source.union_rects || [];
        const unionRects = Array.isArray(rawUnion) ? rawUnion.map((u) => normalizePdfSelectionState(u)).filter(Boolean) : [];
        return {
          id: clean(source.id || ""),
          path: normalizeServerPathValue(source.path || scope.path),
          mode: clean(source.mode || scope.mode) === "picture" ? "picture" : "pdf",
          page: Math.max(1, Math.floor(Number(source.page || scope.page || 1) || 1)),
          rect,
          unionRects: unionRects.length ? unionRects : [],
          text,
          displayMode: clean(source.displayMode || source.display_mode || "type").toLowerCase() === "full" ? "full" : "type",
          noticeStyle: /^(image|picture|photo|character|image_character)$/.test(clean(source.noticeStyle || source.notice_style || source.style || "fireball").toLowerCase()) ? "image" : "fireball",
          imageSrc: normalizePdfAiQuestionImageSrc(source.imageSrc || source.image_src || source.imagePath || source.image_path || ""),
          noticeTheme: clean(source.noticeTheme || source.notice_theme || source.theme || "red").toLowerCase() === "cyan" ? "cyan" : "red",
          focusText: preservePdfAiNoticeText(source.focusText || source.focus_text || source.focus || source.hudText || source.hud_text || "", 520),
          noticeTextHighlights: normalizePdfAiTextHighlights(source.noticeTextHighlights || source.notice_text_highlights || source.textHighlights || source.text_highlights || [], text),
          focusTextHighlights: normalizePdfAiTextHighlights(source.focusTextHighlights || source.focus_text_highlights || source.focusHighlights || source.focus_highlights || [], preservePdfAiNoticeText(source.focusText || source.focus_text || source.focus || source.hudText || source.hud_text || "", 520)),
          noticeTextFont: normalizePdfAiNoticeFont(source.noticeTextFont || source.notice_text_font || source.textFont || source.text_font || "Inter"),
          focusTextFont: normalizePdfAiNoticeFont(source.focusTextFont || source.focus_text_font || source.focusFont || source.focus_font || "Inter"),
          voice: clean(source.voice || PDF_SHARED_AUDIO_DEFAULT_VOICE) || PDF_SHARED_AUDIO_DEFAULT_VOICE,
          voiceLabel: clean(source.voice_label || source.voiceLabel || ""),
          speakMode: (() => {
            const mode = clean(source.speakMode || source.speak_mode || "once").toLowerCase();
            return mode === "click" || mode === "when_click" || mode === "every" ? "click" : (mode === "off" ? "off" : "once");
          })(),
          audioText: preservePdfAiNoticeText(source.audio_text || source.audioText || text, 2400),
          audioPath: clean(source.audio_path || source.audioPath || ""),
          audioMime: clean(source.audio_mime || source.audioMime || ""),
          updatedAt: clean(source.updated_at || source.updatedAt || ""),
        };
      };

      const PDF_AI_QUESTION_DEFAULT_VOICE = "kokoro:af_jessica";
      const PDF_AI_QUESTION_CHARACTER_URL = "/space-pdf/character-asset?name=redgirl.gif&speed=2&transparent=1";
      const PDF_AI_QUESTION_ANIMATION_PAUSE_KEY = "future_pdf_ai_question_animation_pause";
      const PDF_AI_QUESTION_GATE_AUDIO_CACHE_KEY = "future_pdf_ai_question_gate_audio_cache";
      const PDF_AI_QUESTION_LOCAL_PROGRESS_PREFIX = "future_pdf_ai_question_progress:";
      const PDF_AI_QUESTION_TRUE_FX_PATH = "Sound/fx-true_a76ad961cb10db7ab6c8a928b2581711b5ae65b9.mp3";
      const PDF_AI_QUESTION_FALSE_FX_PATH = "Sound/fx-false_1ee7795e2be3b283e45d8f6b3e1a0e166bb6d4cc.mp3";
      let pdfAiQuestionCharacterPreload = null;
      let pdfAiQuestionCloseTimer = 0;
      let pdfAiQuestionAnimationPauseTimer = 0;
      let pdfAiQuestionEditingId = "";
      let pdfAiQuestionEditorNodes = [];
      let pdfAiQuestionActiveProgress = null;
      let pdfAiQuestionMinimized = false;
      let pdfAiQuestionDialogueFrame = 0;
      let pdfAiQuestionDraggingNodeId = "";
      let pdfAiQuestionRightDragActive = false;
      let pdfAiQuestionRightDragOverId = "";
      let pdfAiQuestionGotoHighlightId = "";
      let pdfAiQuestionGotoHighlightTimer = 0;
      let pdfAiQuestionAutoSaveTimer = 0;
      const pdfAiQuestionProgressCache = new Map();
      const pdfAiQuestionGateAudioCache = new Map();

      const pdfAiQuestionNodeIsPinned = (node = {}) => Boolean(
        node && (node.pinned || node.pinNode || node.pin_node || node.pinnedNode || node.pinned_node)
      );

      // Added 2026-07-02: keeps pinned MishiKa nodes at their source index while shuffling the rest.
      const pdfAiQuestionShuffleNodes = (items = []) => {
        const source = Array.isArray(items) ? items.slice() : [];
        const movable = source.filter((item) => !pdfAiQuestionNodeIsPinned(item));
        for (let index = movable.length - 1; index > 0; index -= 1) {
          const swapIndex = Math.floor(Math.random() * (index + 1));
          [movable[index], movable[swapIndex]] = [movable[swapIndex], movable[index]];
        }
        let movableIndex = 0;
        return source.map((item) => (pdfAiQuestionNodeIsPinned(item) ? item : movable[movableIndex++]));
      };

      const pdfAiQuestionNodeKey = (question = {}, index = 0) => clean(question && question.id || "") || `node-${index + 1}-${pdfAiNoticeRectKey(question && question.rect)}`;

      // Added 2026-07-10: resumes MishiKa from the first unpassed node instead of trusting a stale questionIndex.
      const pdfAiQuestionProgressResultForNode = (progress = null, sequence = [], index = 0) => {
        const safeProgress = progress && typeof progress === "object" ? progress : {};
        const results = safeProgress.results && typeof safeProgress.results === "object" ? safeProgress.results : {};
        const question = Array.isArray(sequence) ? sequence[index] : null;
        if (!question) {
          return null;
        }
        const candidates = [
          pdfAiQuestionNodeKey(question, index),
          clean(question && question.id || ""),
          Array.isArray(safeProgress.order) ? clean(safeProgress.order[index] || "") : "",
        ].filter(Boolean);
        for (const key of candidates) {
          if (results[key] && typeof results[key] === "object") {
            return results[key];
          }
        }
        return null;
      };

      const pdfAiQuestionProgressNodePassed = (progress = null, sequence = [], index = 0) => {
        const result = pdfAiQuestionProgressResultForNode(progress, sequence, index);
        return Boolean(result && (result.passed || result.correct));
      };

      const pdfAiQuestionFirstIncompleteIndex = (progress = null, sequence = []) => {
        const safeSequence = Array.isArray(sequence) ? sequence : [];
        for (let index = 0; index < safeSequence.length; index += 1) {
          if (!pdfAiQuestionProgressNodePassed(progress, safeSequence, index)) {
            return index;
          }
        }
        return safeSequence.length;
      };

      const pdfAiQuestionLocalProgressKey = (regionKey = "") => {
        const owner = clean(currentAuthUsername || (authUser && authUser.value) || "guest").toLowerCase() || "guest";
        return `${PDF_AI_QUESTION_LOCAL_PROGRESS_PREFIX}${owner}:${hashSpaceWText(clean(regionKey || ""))}`;
      };

      // Added 2026-07-02: stores MishiKa progress locally first, then lets server sync catch up when available.
      const rememberPdfAiQuestionLocalProgress = (progress = null) => {
        if (!progress || !progress.regionKey) {
          return;
        }
        try {
          localStorage.setItem(pdfAiQuestionLocalProgressKey(progress.regionKey), JSON.stringify({
            ...progress,
            localSavedAt: new Date().toISOString(),
            pendingServerSync: progress.pendingServerSync != null ? Boolean(progress.pendingServerSync) : true,
          }));
        } catch (error) {}
      };

      const readPdfAiQuestionLocalProgress = (regionKey = "") => {
        if (!regionKey) {
          return null;
        }
        try {
          const raw = localStorage.getItem(pdfAiQuestionLocalProgressKey(regionKey));
          if (!raw) {
            return null;
          }
          const parsed = JSON.parse(raw);
          return parsed && typeof parsed === "object" ? parsed : null;
        } catch (error) {
          return null;
        }
      };

      const newerPdfAiQuestionProgress = (first = null, second = null) => {
        if (!first) return second || null;
        if (!second) return first || null;
        const firstAt = Date.parse(first.localSavedAt || first.savedAt || first.updatedAt || first.at || "") || 0;
        const secondAt = Date.parse(second.localSavedAt || second.savedAt || second.updatedAt || second.at || "") || 0;
        return secondAt > firstAt ? second : first;
      };

      const pdfAiQuestionRegionKey = (nodes = []) => {
        const sequence = Array.isArray(nodes) ? nodes : [];
        const first = sequence[0] || {};
        const scope = currentPdfAiRegionNoticeScope();
        const regionName = clean(first.regionName || first.region_name || first.aiQuestionRegionName || first.ai_question_region_name || "");
        return [
          scope.mode,
          scope.path.toLowerCase(),
          scope.page,
          pdfAiNoticeRectKey(first && first.rect),
          regionName.toLowerCase(),
        ].join("::");
      };

      const pdfAiQuestionOrderByIds = (nodes = [], order = []) => {
        const sequence = Array.isArray(nodes) ? nodes.slice() : [];
        const keys = Array.isArray(order) ? order.map((item) => clean(item)).filter(Boolean) : [];
        if (!sequence.length || !keys.length) {
          return sequence;
        }
        const used = new Set();
        const ordered = [];
        keys.forEach((key) => {
          const index = sequence.findIndex((item, itemIndex) => !used.has(itemIndex) && pdfAiQuestionNodeKey(item, itemIndex) === key);
          if (index >= 0) {
            used.add(index);
            ordered.push(sequence[index]);
          }
        });
        sequence.forEach((item, index) => {
          if (!used.has(index)) {
            ordered.push(item);
          }
        });
        return ordered;
      };

      const makePdfAiQuestionProgressState = (sequence = [], index = 0, options = {}) => {
        const normalizedSequence = Array.isArray(sequence) ? sequence : [];
        const scope = currentPdfAiRegionNoticeScope();
        const order = normalizedSequence.map((item, itemIndex) => pdfAiQuestionNodeKey(item, itemIndex));
        const saved = options && options.savedProgress && typeof options.savedProgress === "object" ? options.savedProgress : {};
        const savedCompleted = saved.completed && typeof saved.completed === "object" ? saved.completed : {};
        const savedResults = saved.results && typeof saved.results === "object" ? saved.results : {};
        const regionKey = clean(options.regionKey || saved.regionKey || pdfAiQuestionRegionKey(normalizedSequence));
        return {
          version: 1,
          path: scope.path,
          lesson_id: clean(scope.lesson_id || ""),
          mode: scope.mode,
          page: scope.page,
          regionKey,
          randomOrder: Boolean(options.randomOrder || saved.randomOrder),
          order,
          questionIndex: Math.min(Math.max(0, normalizedSequence.length - 1), Math.max(0, Math.floor(Number(saved.questionIndex != null ? saved.questionIndex : index) || 0))),
          completed: { ...savedCompleted },
          results: { ...savedResults },
        };
      };

      const updatePdfAiQuestionSaveProgressButton = (panel = null, tone = "", message = "") => {
        const targetPanel = panel || document.getElementById("ft-pdf-ai-question-panel");
        const button = targetPanel && targetPanel.querySelector("[data-pdf-ai-question-save-progress]");
        if (!button) {
          return;
        }
        button.dataset.tone = clean(tone || "");
        if (message) {
          button.title = message;
          button.setAttribute("aria-label", message);
        } else {
          button.title = "Save MishiKa progress";
          button.setAttribute("aria-label", "Save MishiKa progress");
        }
      };

      const summarizePdfAiQuestionProgress = (progress = null, total = 0) => {
        const safeProgress = progress && typeof progress === "object" ? progress : {};
        const results = safeProgress.results && typeof safeProgress.results === "object" ? safeProgress.results : {};
        const values = Object.values(results).filter((item) => item && typeof item === "object");
        const answered = values.length;
        const correct = values.filter((item) => Boolean(item.firstCorrect != null ? item.firstCorrect : item.correct)).length;
        const wrong = Math.max(0, answered - correct);
        const count = Math.max(Number(total || 0) || 0, Array.isArray(safeProgress.order) ? safeProgress.order.length : 0, answered);
        return { correct, wrong, answered, total: count };
      };

      const updatePdfAiQuestionPanelScore = (progress = null, total = 0) => {
        const panel = document.getElementById("ft-pdf-ai-question-panel");
        const score = panel && panel.querySelector("[data-pdf-ai-question-score]");
        if (!score) {
          return;
        }
        const summary = summarizePdfAiQuestionProgress(progress || pdfAiQuestionActiveProgress, total);
        score.querySelector("[data-pdf-ai-question-score-correct]").textContent = String(summary.correct || 0);
        score.querySelector("[data-pdf-ai-question-score-wrong]").textContent = String(summary.wrong || 0);
        score.title = `${summary.correct || 0} correct, ${summary.wrong || 0} incorrect`;
        score.classList.toggle("has-progress", summary.answered > 0);
      };

      const updatePdfAiQuestionRegionScoreBadges = (regionKey = "", progress = null, total = 0) => {
        if (!regionKey || !pdfEls || !pdfEls.aiNoticeLayer) {
          return;
        }
        const summary = summarizePdfAiQuestionProgress(progress, total);
        pdfEls.aiNoticeLayer.querySelectorAll("[data-ai-question-region-key]").forEach((node) => {
          if (clean(node.dataset.aiQuestionRegionKey || "") !== regionKey) {
            return;
          }
          node.dataset.score = summary.total ? `${summary.answered}/${summary.total}` : "";
          node.classList.toggle("has-score", summary.answered > 0 || summary.total > 0);
        });
      };

      // Added 2026-07-09: coalesces rapid MishiKa answer saves while local progress remains immediate.
      const schedulePdfAiQuestionActiveProgressSave = (options = {}) => {
        if (pdfAiQuestionAutoSaveTimer) {
          window.clearTimeout(pdfAiQuestionAutoSaveTimer);
          pdfAiQuestionAutoSaveTimer = 0;
        }
        const delayMs = Math.max(40, Math.floor(Number(options.delayMs || 180) || 180));
        pdfAiQuestionAutoSaveTimer = window.setTimeout(() => {
          pdfAiQuestionAutoSaveTimer = 0;
          void savePdfAiQuestionActiveProgress({ silent: true });
        }, delayMs);
      };

      // Added 2026-07-10: keeps MishiKa region badges and local/server progress in sync when moving between questions.
      const touchPdfAiQuestionActiveProgress = (options = {}) => {
        if (!pdfAiQuestionActiveProgress || !pdfAiQuestionActiveProgress.regionKey) {
          return;
        }
        pdfAiQuestionActiveProgress.localSavedAt = new Date().toISOString();
        pdfAiQuestionActiveProgress.pendingServerSync = true;
        pdfAiQuestionProgressCache.set(pdfAiQuestionActiveProgress.regionKey, { ...pdfAiQuestionActiveProgress });
        rememberPdfAiQuestionLocalProgress(pdfAiQuestionActiveProgress);
        const total = Array.isArray(pdfAiQuestionActiveProgress.sequence)
          ? pdfAiQuestionActiveProgress.sequence.length
          : (Array.isArray(pdfAiQuestionActiveProgress.order) ? pdfAiQuestionActiveProgress.order.length : 0);
        updatePdfAiQuestionRegionScoreBadges(pdfAiQuestionActiveProgress.regionKey, pdfAiQuestionActiveProgress, total);
        updatePdfAiQuestionPanelScore(pdfAiQuestionActiveProgress, total);
        if (options && options.save !== false) {
          schedulePdfAiQuestionActiveProgressSave({ delayMs: options.delayMs });
        }
      };

      const markPdfAiQuestionProgressResult = (question = {}, result = {}) => {
        if (!pdfAiQuestionActiveProgress || !question) {
          return;
        }
        const sequence = Array.isArray(pdfAiQuestionActiveProgress.sequence) ? pdfAiQuestionActiveProgress.sequence : [];
        const index = sequence.findIndex((item, itemIndex) => item === question || pdfAiQuestionNodeKey(item, itemIndex) === pdfAiQuestionNodeKey(question, itemIndex));
        const safeIndex = index >= 0 ? index : Math.max(0, Math.floor(Number(pdfAiQuestionActiveProgress.questionIndex || 0) || 0));
        const key = pdfAiQuestionNodeKey(question, safeIndex);
        const existingResult = pdfAiQuestionActiveProgress.results && pdfAiQuestionActiveProgress.results[key] && typeof pdfAiQuestionActiveProgress.results[key] === "object"
          ? pdfAiQuestionActiveProgress.results[key]
          : null;
        const firstCorrect = existingResult && existingResult.firstCorrect != null
          ? Boolean(existingResult.firstCorrect)
          : Boolean(result && (result.firstCorrect != null ? result.firstCorrect : result.correct));
        pdfAiQuestionActiveProgress.questionIndex = safeIndex;
        pdfAiQuestionActiveProgress.completed = {
          ...(pdfAiQuestionActiveProgress.completed || {}),
          [key]: {
            done: true,
            at: new Date().toISOString(),
          },
        };
        pdfAiQuestionActiveProgress.results = {
          ...(pdfAiQuestionActiveProgress.results || {}),
          [key]: {
            ...(existingResult || {}),
            ...(result && typeof result === "object" ? result : {}),
            firstCorrect,
            firstAttemptAt: existingResult && existingResult.firstAttemptAt ? existingResult.firstAttemptAt : new Date().toISOString(),
            questionType: normalizePdfAiQuestionType(question.questionType || "choice"),
            at: new Date().toISOString(),
          },
        };
        touchPdfAiQuestionActiveProgress();
      };

      const savePdfAiQuestionActiveProgress = async (options = {}) => {
        const silent = Boolean(options && options.silent);
        const panel = document.getElementById("ft-pdf-ai-question-panel");
        if (!pdfAiQuestionActiveProgress || !pdfAiQuestionActiveProgress.regionKey) {
          if (!silent) {
            updatePdfAiQuestionSaveProgressButton(panel, "error", "No MishiKa progress to save yet");
            setPdfStatus("No MishiKa progress to save yet.", true);
          }
          return null;
        }
        const requestProgress = pdfAiQuestionActiveProgress;
        const payload = {
          path: requestProgress.path,
          mode: requestProgress.mode,
          page: requestProgress.page,
          regionKey: requestProgress.regionKey,
          randomOrder: Boolean(requestProgress.randomOrder),
          order: Array.isArray(requestProgress.order) ? requestProgress.order : [],
          questionIndex: Math.max(0, Math.floor(Number(requestProgress.questionIndex || 0) || 0)),
          completed: requestProgress.completed || {},
          results: requestProgress.results || {},
          savedAt: new Date().toISOString(),
          resetProgress: Boolean(options && options.resetProgress),
        };
        if (!silent) {
          updatePdfAiQuestionSaveProgressButton(panel, "saving", "Saving MishiKa progress...");
        }
        const outboxRow = enqueueProgressOutboxRequest(
          "space_pdf_ai_question",
          "/space-pdf/ai-question-progress?client_source=offline_outbox",
          payload,
          pdfAiQuestionLocalProgressKey(payload.regionKey),
        );
        try {
          const { payload: responsePayload } = await fetchAuthJson("/space-pdf/ai-question-progress?client_source=pdf_ai_question_progress_save", {
            method: "POST",
            body: JSON.stringify(payload),
          });
          const saved = responsePayload && responsePayload.progress && typeof responsePayload.progress === "object"
            ? responsePayload.progress
            : responsePayload;
          if (outboxRow) acknowledgeProgressOutboxRequest(outboxRow, payload);
          if (pdfAiQuestionActiveProgress !== requestProgress) {
            if (payload.regionKey) {
              const cachedProgress = {
                ...requestProgress,
                ...(saved && typeof saved === "object" ? saved : {}),
                sequence: requestProgress.sequence,
                pendingServerSync: false,
                localSavedAt: new Date().toISOString(),
              };
              pdfAiQuestionProgressCache.set(payload.regionKey, cachedProgress);
              rememberPdfAiQuestionLocalProgress(cachedProgress);
            }
            return saved;
          }
          pdfAiQuestionActiveProgress = {
            ...pdfAiQuestionActiveProgress,
            ...(saved && typeof saved === "object" ? saved : {}),
            sequence: pdfAiQuestionActiveProgress.sequence,
            pendingServerSync: false,
            localSavedAt: new Date().toISOString(),
          };
          pdfAiQuestionProgressCache.set(pdfAiQuestionActiveProgress.regionKey, { ...pdfAiQuestionActiveProgress });
          rememberPdfAiQuestionLocalProgress(pdfAiQuestionActiveProgress);
          updatePdfAiQuestionRegionScoreBadges(pdfAiQuestionActiveProgress.regionKey, pdfAiQuestionActiveProgress);
          updatePdfAiQuestionPanelScore(pdfAiQuestionActiveProgress);
          if (!silent) {
            updatePdfAiQuestionSaveProgressButton(panel, "saved", "MishiKa progress saved");
            setPdfStatus("MishiKa progress saved for this user.");
            window.setTimeout(() => updatePdfAiQuestionSaveProgressButton(panel), 1600);
          }
          return saved;
        } catch (error) {
          scheduleProgressOutboxDrain(progressOutboxRetryMs);
          const message = error && error.message ? error.message : "Could not save MishiKa progress.";
          if (!silent) {
            updatePdfAiQuestionSaveProgressButton(panel, "error", message);
            setPdfStatus(message, true);
          }
          return null;
        }
      };

      const loadPdfAiQuestionProgress = async (regionKey = "", scope = null) => {
        const safeScope = scope && typeof scope === "object" ? scope : currentPdfAiRegionNoticeScope();
        const key = clean(regionKey || "");
        if (!key || !safeScope.path) {
          return null;
        }
        const localProgress = readPdfAiQuestionLocalProgress(key);
        const query = new URLSearchParams();
        query.set("path", safeScope.path);
        if (safeScope.lesson_id) query.set("lesson_id", safeScope.lesson_id);
        if (clean(pdfState && pdfState.lessonHandle || "")) query.set("lesson_handle", clean(pdfState.lessonHandle));
        query.set("page", String(safeScope.page || 1));
        query.set("mode", safeScope.mode || "pdf");
        query.set("regionKey", key);
        query.set("client_source", "pdf_ai_question_progress_load");
        try {
          const { payload } = await fetchAuthJson(`/space-pdf/ai-question-progress?${query.toString()}`, { timeoutMs: 10000 });
          const serverProgress = payload && payload.progress && typeof payload.progress === "object" ? payload.progress : null;
          const progress = newerPdfAiQuestionProgress(serverProgress, localProgress);
          if (progress) {
            pdfAiQuestionProgressCache.set(key, progress);
          }
          return progress;
        } catch (error) {
          return localProgress;
        }
      };

      const pdfAiQuestionGateAudioStorageKey = () => {
        const username = clean(currentAuthUsername || (authUser && authUser.value) || "guest").toLowerCase();
        return `${PDF_AI_QUESTION_GATE_AUDIO_CACHE_KEY}:${username || "guest"}`;
      };

      const loadPdfAiQuestionGateAudioCache = () => {
        if (pdfAiQuestionGateAudioCache.size) {
          return;
        }
        try {
          const raw = localStorage.getItem(pdfAiQuestionGateAudioStorageKey());
          const parsed = raw ? JSON.parse(raw) : {};
          Object.entries(parsed && typeof parsed === "object" ? parsed : {}).forEach(([key, value]) => {
            if (value && typeof value === "object" && clean(value.audio_path || value.audioPath || "")) {
              pdfAiQuestionGateAudioCache.set(key, value);
            }
          });
        } catch (error) {}
      };

      const savePdfAiQuestionGateAudioCache = () => {
        try {
          const payload = {};
          Array.from(pdfAiQuestionGateAudioCache.entries()).slice(-18).forEach(([key, value]) => {
            payload[key] = value;
          });
          localStorage.setItem(pdfAiQuestionGateAudioStorageKey(), JSON.stringify(payload));
        } catch (error) {}
      };

      // Added 2026-07-01: asks MishiKa gate prompts with server-created audio, then reuses the saved clip.
      const pdfAiQuestionTimingPayloadFromVoicePayload = (payload = {}) => {
        const source = payload && typeof payload === "object" ? payload : {};
        const audio = source.audio && typeof source.audio === "object" ? source.audio : {};
        const timings = Array.isArray(source.timings)
          ? source.timings
          : (Array.isArray(audio.timings) ? audio.timings : []);
        const timingTokens = Array.isArray(source.timing_tokens)
          ? source.timing_tokens
          : (Array.isArray(source.timingTokens)
            ? source.timingTokens
            : (Array.isArray(audio.timing_tokens)
              ? audio.timing_tokens
              : (Array.isArray(audio.timingTokens) ? audio.timingTokens : [])));
        const durationMs = Number(source.duration_ms ?? source.durationMs ?? audio.duration_ms ?? audio.durationMs ?? 0) || 0;
        return {
          timings,
          timing_tokens: timingTokens,
          timingTokens,
          duration_ms: Math.max(0, Math.round(durationMs)),
          durationMs: Math.max(0, Math.round(durationMs)),
        };
      };

      const pdfAiQuestionTimingPayloadHasRows = (payload = null) => {
        const source = payload && typeof payload === "object" ? payload : {};
        return Array.isArray(source.timings) && source.timings.length;
      };

      // Added 2026-07-01: MishiKa voice must include server timing rows so typed text can follow speech.
      const playPdfAiQuestionGateVoice = async (text = "", voice = PDF_AI_QUESTION_DEFAULT_VOICE) => {
        const promptText = preserveQuestionText(text || "");
        const voiceKey = clean(voice || PDF_AI_QUESTION_DEFAULT_VOICE) || PDF_AI_QUESTION_DEFAULT_VOICE;
        if (!promptText) {
          return null;
        }
        loadPdfAiQuestionGateAudioCache();
        const cacheKey = `${voiceKey}\n${promptText}`;
        const cached = pdfAiQuestionGateAudioCache.get(cacheKey);
        const cachedPath = cached && clean(cached.audio_path || cached.audioPath || cached.path || "");
        const cachedTimingPayload = pdfAiQuestionTimingPayloadFromVoicePayload(cached || {});
        if (cachedPath && pdfAiQuestionTimingPayloadHasRows(cachedTimingPayload)) {
          return playPdfAiQuestionAudioPath(cachedPath, cachedTimingPayload);
        }
        try {
          const { payload } = await fetchAuthJson("/pdf/speak?client_source=pdf_speak", {
            method: "POST",
            timeoutMs: 70000,
            body: JSON.stringify({ text: promptText, voice: voiceKey }),
          });
          const audioPath = payload && clean(payload.audio_path || payload.audioPath || (payload.audio && payload.audio.path) || "");
          if (audioPath) {
            const timingPayload = pdfAiQuestionTimingPayloadFromVoicePayload(payload);
            pdfAiQuestionGateAudioCache.set(cacheKey, {
              audio_path: audioPath,
              audio_mime: clean(payload.audio_mime || payload.audioMime || (payload.audio && payload.audio.mime) || ""),
              voice: clean(payload.voice || voiceKey) || voiceKey,
              ...timingPayload,
              updatedAt: new Date().toISOString(),
            });
            savePdfAiQuestionGateAudioCache();
            return playPdfAiQuestionAudioPath(audioPath, timingPayload);
          }
        } catch (error) {}
        if (cachedPath) {
          return playPdfAiQuestionAudioPath(cachedPath);
        }
        return null;
      };

      const pdfAiQuestionAnimationOwnerKey = () => {
        const username = clean(currentAuthUsername || (authUser && authUser.value) || "guest").toLowerCase();
        return username || "guest";
      };

      const pdfAiQuestionAnimationPauseStorageKey = () => `${PDF_AI_QUESTION_ANIMATION_PAUSE_KEY}:${pdfAiQuestionAnimationOwnerKey()}`;

      const readPdfAiQuestionAnimationPausePreference = () => {
        try {
          const raw = localStorage.getItem(pdfAiQuestionAnimationPauseStorageKey());
          if (!raw) {
            return false;
          }
          if (raw === "1" || raw === "true") {
            return true;
          }
          const parsed = JSON.parse(raw);
          return Boolean(parsed && parsed.paused);
        } catch (error) {
          return false;
        }
      };

      const savePdfAiQuestionAnimationPausePreference = (paused) => {
        try {
          localStorage.setItem(pdfAiQuestionAnimationPauseStorageKey(), JSON.stringify({
            paused: Boolean(paused),
            updatedAt: new Date().toISOString(),
          }));
        } catch (error) {}
      };

      const clearPdfAiQuestionAnimationPauseTimer = () => {
        if (pdfAiQuestionAnimationPauseTimer) {
          window.clearTimeout(pdfAiQuestionAnimationPauseTimer);
          pdfAiQuestionAnimationPauseTimer = 0;
        }
      };

      const updatePdfAiQuestionAnimationToggle = (panel = null) => {
        const targetPanel = panel || document.getElementById("ft-pdf-ai-question-panel");
        if (!targetPanel) {
          return false;
        }
        const paused = readPdfAiQuestionAnimationPausePreference();
        const button = targetPanel.querySelector("[data-pdf-ai-question-animation-toggle]");
        targetPanel.classList.toggle("is-animation-pause-requested", paused);
        if (!paused) {
          targetPanel.classList.remove("is-animation-paused");
        }
        if (button) {
          button.classList.toggle("is-active", paused);
          button.setAttribute("aria-pressed", paused ? "true" : "false");
          button.setAttribute("aria-label", paused ? "Resume MishiKa ambient animation" : "Pause MishiKa ambient animation");
          button.title = paused ? "Resume ambient animation" : "Pause ambient animation after intro";
        }
        return paused;
      };

      const schedulePdfAiQuestionAnimationPause = (panel = null) => {
        const targetPanel = panel || document.getElementById("ft-pdf-ai-question-panel");
        clearPdfAiQuestionAnimationPauseTimer();
        if (!targetPanel) {
          return;
        }
        targetPanel.classList.remove("is-animation-paused");
        if (!updatePdfAiQuestionAnimationToggle(targetPanel)) {
          return;
        }
        pdfAiQuestionAnimationPauseTimer = window.setTimeout(() => {
          pdfAiQuestionAnimationPauseTimer = 0;
          const activePanel = document.getElementById("ft-pdf-ai-question-panel");
          if (!activePanel || activePanel.classList.contains("is-hidden") || activePanel.classList.contains("is-closing")) {
            return;
          }
          if (activePanel.classList.contains("is-tail-ready") && activePanel.classList.contains("is-animation-pause-requested")) {
            activePanel.classList.add("is-animation-paused");
          }
        }, 920);
      };

      const preloadPdfAiQuestionCharacter = () => {
        try {
          if (pdfAiQuestionCharacterPreload) {
            return pdfAiQuestionCharacterPreload;
          }
          const image = new Image();
          image.decoding = "async";
          image.loading = "eager";
          image.src = PDF_AI_QUESTION_CHARACTER_URL;
          pdfAiQuestionCharacterPreload = image;
          return image;
        } catch (error) {
          return null;
        }
      };
      window.preloadPdfAiQuestionCharacter = preloadPdfAiQuestionCharacter;

      const normalizePdfAiQuestionAnswer = (raw = {}, index = 0) => {
        const source = raw && typeof raw === "object" ? raw : {};
        const text = preserveQuestionText(source.text || source.answer || "");
        if (!text) {
          return null;
        }
        const mode = clean(source.explanationMode || source.explanation_mode || "text_voice").toLowerCase();
        return {
          id: clean(source.id || "") || `answer-${index + 1}`,
          text,
          correct: Boolean(source.correct || source.isCorrect),
          explanationText: preserveQuestionText(source.explanationText || source.explanation_text || source.explanation || ""),
          explanationMode: mode === "voice" || mode === "click" ? "voice" : (mode === "text" || mode === "off" ? "text" : "text_voice"),
          explanationVoice: clean(source.explanationVoice || source.explanation_voice || source.voice || PDF_AI_QUESTION_DEFAULT_VOICE) || PDF_AI_QUESTION_DEFAULT_VOICE,
          explanationVoiceLabel: clean(source.explanationVoiceLabel || source.explanation_voice_label || ""),
          audioPath: clean(source.audioPath || source.audio_path || ""),
          audioMime: clean(source.audioMime || source.audio_mime || ""),
        };
      };

      const normalizePdfAiQuestionType = (value = "choice") => {
        const raw = clean(value).toLowerCase().replace(/[-\s]+/g, "_");
        if (raw === "input" || raw === "typed" || raw === "free" || raw === "text" || raw === "essay") {
          return "input";
        }
        if (raw === "theory" || raw === "theory_vi" || raw === "learn_theory" || raw === "read_theory") {
          return "theory";
        }
        if (raw === "speak_en" || raw === "speak_english" || raw === "speech_en" || raw === "read_en") {
          return "speak_en";
        }
        if (raw === "speak_vi" || raw === "speak_vn" || raw === "speak_vietnamese" || raw === "speech_vi" || raw === "read_vi") {
          return "speak_vi";
        }
        return "choice";
      };

      const normalizePdfAiTypedMatchPercent = (value = 100) => {
        const numeric = Number(value);
        if (!Number.isFinite(numeric)) {
          return 100;
        }
        return Math.min(100, Math.max(1, Math.round(numeric)));
      };

      const normalizePdfAiTypedAnswerText = (value = "") => {
        return preserveQuestionText(value)
          .toLowerCase()
          .replace(/[“”"'.?!,:;()[\]{}]+/g, "")
          .replace(/\s+/g, " ")
          .trim();
      };

      const pdfAiTypedAnswerTokenScore = (typedValue = "", correctValue = "") => {
        const typed = normalizePdfAiTypedAnswerText(typedValue).split(/\s+/).filter(Boolean);
        const correct = normalizePdfAiTypedAnswerText(correctValue).split(/\s+/).filter(Boolean);
        if (!typed.length || !correct.length) {
          return normalizePdfAiTypedAnswerText(typedValue) && normalizePdfAiTypedAnswerText(typedValue) === normalizePdfAiTypedAnswerText(correctValue) ? 100 : 0;
        }
        const typedCounts = new Map();
        typed.forEach((token) => typedCounts.set(token, (typedCounts.get(token) || 0) + 1));
        let matched = 0;
        correct.forEach((token) => {
          const count = typedCounts.get(token) || 0;
          if (count > 0) {
            matched += 1;
            typedCounts.set(token, count - 1);
          }
        });
        return Math.round((matched / Math.max(typed.length, correct.length)) * 100);
      };

      const bestPdfAiTypedAnswerMatch = (typedValue = "", correctAnswers = []) => {
        let best = null;
        (Array.isArray(correctAnswers) ? correctAnswers : []).forEach((answer) => {
          const score = pdfAiTypedAnswerTokenScore(typedValue, answer && answer.text || "");
          if (!best || score > best.score) {
            best = { answer, score };
          }
        });
        return best;
      };

      // Added 2026-07-10: highlights typed tokens that are not present in the best matching input answer.
      const pdfAiTypedAnswerFeedbackBlocks = (typedValue = "", correctAnswers = []) => {
        const typedTokens = preserveQuestionText(typedValue).split(/\s+/).map((token) => clean(token)).filter(Boolean);
        const bestMatch = bestPdfAiTypedAnswerMatch(typedValue, correctAnswers);
        const answerText = bestMatch && bestMatch.answer ? preserveQuestionText(bestMatch.answer.text || "") : "";
        const correctCounts = new Map();
        normalizePdfAiTypedAnswerText(answerText).split(/\s+/).filter(Boolean).forEach((token) => {
          correctCounts.set(token, (correctCounts.get(token) || 0) + 1);
        });
        return typedTokens.map((token) => {
          const key = normalizePdfAiTypedAnswerText(token);
          const count = correctCounts.get(key) || 0;
          const matched = Boolean(key && count > 0);
          if (matched) {
            correctCounts.set(key, count - 1);
          }
          return { token, matched };
        });
      };

      const pdfAiSpeechTokenKey = (value = "") => {
        return normalizePdfAiTypedAnswerText(value)
          .replace(/[đĐ]/g, "d")
          .normalize("NFD")
          .replace(/[\u0300-\u036f]/g, "")
          .replace(/[^a-z0-9]+/g, "")
          .trim();
      };

      const pdfAiSpeechTokenRows = (value = "") => {
        return preserveQuestionText(value)
          .split(/\s+/)
          .map((token) => clean(token).replace(/^[“”"'.?!,:;()[\]{}]+|[“”"'.?!,:;()[\]{}]+$/g, ""))
          .filter(Boolean)
          .map((token) => ({ token, key: pdfAiSpeechTokenKey(token) }))
          .filter((row) => row.key);
      };

      const pdfAiSpeechTokens = (value = "") => pdfAiSpeechTokenRows(value).map((row) => row.token);

      const bestPdfAiSpeechTokenMatch = (spokenValue = "", correctAnswers = []) => {
        const spokenRows = pdfAiSpeechTokenRows(spokenValue);
        const spokenTokens = spokenRows.map((row) => row.key);
        let best = null;
        (Array.isArray(correctAnswers) ? correctAnswers : []).forEach((answer) => {
          const targetRows = pdfAiSpeechTokenRows(answer && answer.text || "");
          const used = new Set();
          const blocks = targetRows.map((row) => {
            const hitIndex = spokenTokens.findIndex((spoken, index) => !used.has(index) && spoken === row.key);
            const matched = hitIndex >= 0;
            if (matched) {
              used.add(hitIndex);
            }
            return { token: row.token, matched };
          });
          const matchedCount = blocks.filter((block) => block.matched).length;
          const score = targetRows.length ? Math.round((matchedCount / targetRows.length) * 100) : 0;
          if (!best || score > best.score) {
            best = { answer, score, blocks, spokenTokens: spokenRows.map((row) => row.token) };
          }
        });
        return best || { answer: null, score: 0, blocks: [], spokenTokens };
      };

      const shufflePdfAiQuestionAnswers = (answers = []) => {
        const rows = Array.isArray(answers) ? answers.slice() : [];
        for (let index = rows.length - 1; index > 0; index -= 1) {
          const swapIndex = Math.floor(Math.random() * (index + 1));
          const current = rows[index];
          rows[index] = rows[swapIndex];
          rows[swapIndex] = current;
        }
        return rows;
      };

      const stopPdfAiQuestionDialogueTyping = (dialogue = null) => {
        if (!dialogue) {
          return;
        }
        if (pdfAiQuestionDialogueFrame) {
          window.cancelAnimationFrame(pdfAiQuestionDialogueFrame);
          pdfAiQuestionDialogueFrame = 0;
        }
        if (dialogue._pdfAiTypeTimer) {
          window.clearTimeout(dialogue._pdfAiTypeTimer);
          dialogue._pdfAiTypeTimer = 0;
        }
        if (dialogue._pdfAiVaporDoneTimer) {
          window.clearTimeout(dialogue._pdfAiVaporDoneTimer);
          dialogue._pdfAiVaporDoneTimer = 0;
        }
        dialogue.classList.remove("is-typing", "is-typing-done", "is-vapor-reading");
        dialogue.removeAttribute("data-vapor-text");
        if (dialogue._pdfAiActiveVapor && dialogue._pdfAiActiveVapor.isConnected) {
          dialogue._pdfAiActiveVapor.remove();
        }
        dialogue._pdfAiActiveVapor = null;
      };

      const PDF_AI_QUESTION_HIGHLIGHT_COLORS = [
        { id: "gold", color: "#ffe78a" },
        { id: "red", color: "#ff8aa0" },
        { id: "cyan", color: "#7effe8" },
        { id: "green", color: "#a7ffbd" },
        { id: "violet", color: "#d9b7ff" },
        { id: "rose", color: "#ff5d7f" },
        { id: "orange", color: "#ffb25f" },
        { id: "blue", color: "#7db7ff" },
        { id: "lime", color: "#d8ff73" },
        { id: "white", color: "#ffffff" },
      ];

      const PDF_AI_NOTICE_FONT_OPTIONS = ["Inter", "Arial", "Georgia", "Times New Roman", "Verdana", "Tahoma", "Trebuchet MS", "Courier New"];

      const normalizePdfAiNoticeFont = (value = "", fallback = "Inter") => {
        const raw = clean(value || "").trim();
        return PDF_AI_NOTICE_FONT_OPTIONS.includes(raw) ? raw : fallback;
      };

      const applyPdfAiNoticeFont = (node, value = "") => {
        if (!node) return;
        const font = normalizePdfAiNoticeFont(value);
        node.style.fontFamily = `"${font.replace(/"/g, "")}", Arial, sans-serif`;
      };

      const normalizePdfAiQuestionHighlightColor = (value = "", fallback = "#ffe78a") => {
        const raw = clean(value || "").trim();
        if (/^#[0-9a-f]{6}$/i.test(raw)) {
          return raw.toLowerCase();
        }
        if (/^#[0-9a-f]{3}$/i.test(raw)) {
          return `#${raw.slice(1).split("").map((char) => `${char}${char}`).join("")}`.toLowerCase();
        }
        return fallback;
      };

      const escapePdfAiNoticeHtml = (value = "") => {
        return String(value || "")
          .replace(/&/g, "&amp;")
          .replace(/</g, "&lt;")
          .replace(/>/g, "&gt;")
          .replace(/"/g, "&quot;")
          .replace(/'/g, "&#39;");
      };

      const renderPdfAiNoticeRichHtml = (value = "", highlights = []) => {
        const source = String(value || "").replace(/\r\n?/g, "\n");
        const ranges = normalizePdfAiTextHighlights(highlights || [], source);
        const styleAt = (offset) => {
          const matches = ranges.filter((item) => offset >= item.start && offset < item.end);
          if (!matches.length) return { color: "", bold: false, italic: false, font: "" };
          return matches.reduce((acc, range) => ({
            color: range.color || acc.color || "",
            bold: Boolean(acc.bold || range.bold),
            italic: Boolean(acc.italic || range.italic),
            font: range.font || acc.font || "",
          }), { color: "", bold: false, italic: false, font: "" });
        };
        const chars = [];
        let bold = false;
        let italic = false;
        for (let index = 0; index < source.length;) {
          if (source.startsWith("***", index)) {
            bold = !bold;
            italic = !italic;
            index += 3;
            continue;
          }
          if (source.startsWith("**", index)) {
            bold = !bold;
            index += 2;
            continue;
          }
          if (source.startsWith("*", index)) {
            italic = !italic;
            index += 1;
            continue;
          }
          const rangeStyle = styleAt(index);
          chars.push({
            char: source[index],
            color: rangeStyle.color,
            bold: Boolean(bold || rangeStyle.bold),
            italic: Boolean(italic || rangeStyle.italic),
            font: rangeStyle.font,
          });
          index += 1;
        }
        let html = "";
        let buffer = "";
        let currentKey = "";
        const flush = () => {
          if (!buffer) return;
          let body = escapePdfAiNoticeHtml(buffer).replace(/\n/g, "<br>");
          const [color, isBold, isItalic, font] = currentKey.split("|");
          if (isItalic === "1") body = `<em>${body}</em>`;
          if (isBold === "1") body = `<strong>${body}</strong>`;
          if (font) body = `<span style="font-family:'${escapePdfAiNoticeHtml(font)}', Arial, sans-serif">${body}</span>`;
          if (color) body = `<span class="ft-pdf-ai-notice-highlight" style="--ai-notice-hl:${escapePdfAiNoticeHtml(color)}">${body}</span>`;
          html += body;
          buffer = "";
        };
        chars.forEach((item) => {
          const key = `${item.color || ""}|${item.bold ? "1" : "0"}|${item.italic ? "1" : "0"}|${item.font || ""}`;
          if (buffer && key !== currentKey) {
            flush();
          }
          currentKey = key;
          buffer += item.char;
        });
        flush();
        return html;
      };

      const pdfAiQuestionHighlightColorStorageKey = () => {
        const owner = typeof pdfDrawingOwnerUsername === "function"
          ? (clean(pdfDrawingOwnerUsername() || "").toLowerCase() || "guest")
          : "guest";
        return `future_pdf_ai_question_highlight_colors:${owner}`;
      };

      const readPdfAiQuestionSavedHighlightColors = () => {
        try {
          const rows = JSON.parse(localStorage.getItem(pdfAiQuestionHighlightColorStorageKey()) || "[]");
          return (Array.isArray(rows) ? rows : [])
            .map((color) => normalizePdfAiQuestionHighlightColor(color, ""))
            .filter(Boolean)
            .slice(0, 24);
        } catch (error) {
          return [];
        }
      };

      const savePdfAiQuestionSavedHighlightColor = (color = "") => {
        const normalized = normalizePdfAiQuestionHighlightColor(color, "");
        if (!normalized) {
          return [];
        }
        const rows = readPdfAiQuestionSavedHighlightColors().filter((item) => item !== normalized);
        rows.unshift(normalized);
        const next = rows.slice(0, 24);
        try {
          localStorage.setItem(pdfAiQuestionHighlightColorStorageKey(), JSON.stringify(next));
        } catch (error) {
        }
        return next;
      };

      const normalizePdfAiTextHighlights = (items = [], text = "") => {
        const length = String(text || "").length;
        const paletteById = new Map(PDF_AI_QUESTION_HIGHLIGHT_COLORS.map((item) => [item.id, item]));
        return (Array.isArray(items) ? items : [])
          .map((item) => {
            const source = item && typeof item === "object" ? item : {};
            const start = Math.max(0, Math.min(length, Math.floor(Number(source.start || 0) || 0)));
            const end = Math.max(start, Math.min(length, Math.floor(Number(source.end || 0) || 0)));
            const rawColor = clean(source.color || "");
            const palette = paletteById.get(clean(source.colorId || source.color_id || "")) || PDF_AI_QUESTION_HIGHLIGHT_COLORS.find((entry) => entry.color.toLowerCase() === rawColor.toLowerCase()) || null;
            const color = palette ? palette.color : normalizePdfAiQuestionHighlightColor(rawColor, "");
            const font = normalizePdfAiNoticeFont(source.font || source.fontFamily || source.font_family || "", "");
            const bold = Boolean(source.bold || source.isBold || source.strong);
            const italic = Boolean(source.italic || source.isItalic || source.em);
            if ((!color && !bold && !italic && !font) || end <= start) {
              return null;
            }
            return { start, end, colorId: palette ? palette.id : (color ? "custom" : ""), color, bold, italic, font };
          })
          .filter(Boolean)
          .slice(-80);
      };

      const pdfAiQuestionHighlightsToCharStyles = (text = "", highlights = []) => {
        const chars = Array.from(String(text || ""));
        const offsets = [];
        let offset = 0;
        chars.forEach((char) => {
          offsets.push(offset);
          offset += char.length;
        });
        const styles = new Array(chars.length).fill(null);
        normalizePdfAiTextHighlights(highlights, text).forEach((range) => {
          offsets.forEach((charOffset, index) => {
            if (charOffset >= range.start && charOffset < range.end) {
              styles[index] = range;
            }
          });
        });
        return { chars, styles };
      };

      const renderPdfAiQuestionPlainDialogueText = (value = "") => escapeHtml(preserveQuestionText(value || ""));

      const renderPdfAiQuestionHighlightedText = (text = "", highlights = [], visibleCount = 0, options = {}) => {
        const { chars, styles } = pdfAiQuestionHighlightsToCharStyles(text, highlights);
        const count = Math.max(0, Math.min(chars.length, Math.floor(Number(visibleCount || 0) || 0)));
        const bodyCount = count;
        let html = "";
        let runText = "";
        let runStyle = null;
        let runStart = 0;
        const styleKey = (style) => style && style.color ? style.color : "";
        const flush = (isLastRun = false) => {
          if (!runText) return;
          const runChars = Array.from(runText);
          let body = escapeHtml(runText);
          const liveStart = Math.max(0, Math.floor(Number(options.liveStart ?? -1) || -1));
          const liveEnd = Math.max(liveStart, Math.floor(Number(options.liveEnd ?? -1) || -1));
          const activeIndexValue = Number(options.activeIndex ?? -1);
          const activeIndex = Number.isFinite(activeIndexValue) ? Math.floor(activeIndexValue) : -1;
          const activeStartValue = Number(options.activeStart ?? -1);
          const activeEndValue = Number(options.activeEnd ?? -1);
          const activeStart = Number.isFinite(activeStartValue) ? Math.floor(activeStartValue) : -1;
          const activeEnd = Number.isFinite(activeEndValue) ? Math.floor(activeEndValue) : -1;
          if (options.reserveFull) {
            let grouped = "";
            let groupText = "";
            let groupClass = "";
            const flushGroup = () => {
              if (!groupText) return;
              grouped += groupClass
                ? `<span class="${groupClass}">${escapeHtml(groupText)}</span>`
                : escapeHtml(groupText);
              groupText = "";
            };
            runChars.forEach((char, localIndex) => {
              const globalIndex = runStart + localIndex;
              const nextClass = globalIndex >= count
                ? "ft-pdf-ai-question-type-unrevealed"
                : (globalIndex >= liveStart && globalIndex < liveEnd ? "ft-pdf-ai-question-type-live-word" : "");
              if (groupText && nextClass !== groupClass) {
                flushGroup();
              }
              groupClass = nextClass;
              groupText += char;
            });
            flushGroup();
            body = grouped;
          } else {
            const localActiveIndex = activeIndex - runStart;
            if (localActiveIndex >= 0 && localActiveIndex < runChars.length && /\S/u.test(runChars[localActiveIndex] || "")) {
              const cometColor = runStyle && runStyle.color ? escapeHtml(runStyle.color) : "#7effe8";
              body = [
                escapeHtml(runChars.slice(0, localActiveIndex).join("")),
                `<span class="ft-pdf-ai-question-type-comet-char" style="--ai-type-comet:${cometColor}">`,
                `<span class="ft-pdf-ai-question-type-comet-particles" aria-hidden="true"></span>`,
                `<span class="ft-pdf-ai-question-type-comet-glyph">${escapeHtml(runChars[localActiveIndex])}</span>`,
                `</span>`,
                escapeHtml(runChars.slice(localActiveIndex + 1).join("")),
              ].join("");
            } else {
              body = escapeHtml(runText);
            }
          }
          if (isLastRun && options.last && runChars.length && /\S/.test(runChars[runChars.length - 1])) {
            const prefix = escapeHtml(runChars.slice(0, -1).join(""));
            const liveChar = escapeHtml(runChars[runChars.length - 1]);
            body = `${prefix}<span class="ft-pdf-ai-question-type-live">${liveChar}</span>`;
          }
          html += runStyle
            ? `<span class="ft-pdf-ai-question-highlight" style="--ai-hl:${escapeHtml(runStyle.color)}">${body}</span>`
            : body;
          runText = "";
        };
        const renderCount = options.reserveFull ? chars.length : bodyCount;
        for (let index = 0; index < renderCount; index += 1) {
          const style = styles[index];
          const isLast = index === renderCount - 1;
          if (runText && styleKey(style) !== styleKey(runStyle)) {
            flush(false);
          }
          if (!runText) {
            runStart = index;
          }
          runStyle = style;
          runText += chars[index];
          if (isLast) {
            flush(Boolean(options.last));
          }
        }
        return html;
      };

      const pdfAiQuestionCharCountToUnitIndex = (text = "", count = 0) => Array.from(text).slice(0, count).join("").length;

      const pdfAiQuestionUnitIndexToCharCount = (text = "", unitIndex = 0) => Array.from(text.slice(0, Math.max(0, unitIndex))).length;

      const pdfAiQuestionTokenKey = (value = "") => clean(value || "").toLowerCase().replace(/[^\p{L}\p{N}]+/gu, "");

      const pdfAiQuestionLastVisibleWordRange = (text = "", visibleCount = 0) => {
        const chars = Array.from(text || "");
        const count = Math.max(0, Math.min(chars.length, Math.floor(Number(visibleCount || 0) || 0)));
        if (!count) {
          return null;
        }
        let end = count;
        while (end > 0 && /\s/u.test(chars[end - 1] || "")) {
          end -= 1;
        }
        let start = end;
        while (start > 0 && !/\s/u.test(chars[start - 1] || "")) {
          start -= 1;
        }
        return end > start ? { start, end } : null;
      };

      const renderPdfAiQuestionDialogueVisibleText = (value = "", highlights = [], count = 0, options = {}) => {
        const body = renderPdfAiQuestionHighlightedText(value, highlights, count);
        if (!options.animateLastWord) {
          return body;
        }
        const range = pdfAiQuestionLastVisibleWordRange(value, count);
        if (!range) {
          return body;
        }
        return renderPdfAiQuestionHighlightedText(value, highlights, range.end, { activeIndex: range.end - 1 });
      };

      const renderPdfAiQuestionDialogueReadingText = (value = "", highlights = [], activeRange = null) => {
        return renderPdfAiQuestionPlainDialogueText(value);
      };

      const clearPdfAiQuestionActiveVapor = (dialogue = null) => {
        if (!dialogue) {
          return;
        }
        if (dialogue._pdfAiActiveVapor && dialogue._pdfAiActiveVapor.isConnected) {
          dialogue._pdfAiActiveVapor.remove();
        }
        dialogue._pdfAiActiveVapor = null;
      };

      const updatePdfAiQuestionActiveVapor = (dialogue = null, value = "", step = null) => {
        if (!dialogue || !step || !dialogue.isConnected) {
          clearPdfAiQuestionActiveVapor(dialogue);
          return;
        }
        const startChar = Math.max(0, Math.floor(Number(step.activeStart) || 0));
        const endChar = Math.max(startChar, Math.floor(Number(step.activeEnd) || 0));
        if (endChar <= startChar) {
          clearPdfAiQuestionActiveVapor(dialogue);
          return;
        }
        const textNode = Array.from(dialogue.childNodes).find((node) => node && node.nodeType === Node.TEXT_NODE);
        if (!textNode) {
          clearPdfAiQuestionActiveVapor(dialogue);
          return;
        }
        const startUnit = Math.max(0, Math.min(textNode.length, pdfAiQuestionCharCountToUnitIndex(value, startChar)));
        const endUnit = Math.max(startUnit, Math.min(textNode.length, pdfAiQuestionCharCountToUnitIndex(value, endChar)));
        if (endUnit <= startUnit) {
          clearPdfAiQuestionActiveVapor(dialogue);
          return;
        }
        const range = document.createRange();
        range.setStart(textNode, startUnit);
        range.setEnd(textNode, endUnit);
        const rects = Array.from(range.getClientRects()).filter((rect) => rect.width > 0 && rect.height > 0);
        range.detach();
        if (!rects.length) {
          clearPdfAiQuestionActiveVapor(dialogue);
          return;
        }
        const baseRect = dialogue.getBoundingClientRect();
        const left = Math.min(...rects.map((rect) => rect.left)) - baseRect.left;
        const top = Math.min(...rects.map((rect) => rect.top)) - baseRect.top;
        const right = Math.max(...rects.map((rect) => rect.right)) - baseRect.left;
        const bottom = Math.max(...rects.map((rect) => rect.bottom)) - baseRect.top;
        const overlay = dialogue._pdfAiActiveVapor && dialogue._pdfAiActiveVapor.isConnected
          ? dialogue._pdfAiActiveVapor
          : document.createElement("span");
        if (!overlay.isConnected) {
          overlay.className = "ft-pdf-ai-question-active-vapor";
          overlay.setAttribute("aria-hidden", "true");
          dialogue.appendChild(overlay);
          dialogue._pdfAiActiveVapor = overlay;
        }
        overlay.style.left = `${Math.max(0, left - 5)}px`;
        overlay.style.top = `${Math.max(0, top - 12)}px`;
        overlay.style.width = `${Math.max(8, right - left + 10)}px`;
        overlay.style.height = `${Math.max(8, bottom - top + 20)}px`;
      };

      const buildPdfAiQuestionFallbackWordSteps = (text = "", stepMs = 120) => {
        const value = preserveQuestionText(text || "");
        const matches = Array.from(value.matchAll(/\S+\s*/gu));
        if (!matches.length) {
          return [];
        }
        return matches.map((match, index) => {
          const startUnit = Number(match.index || 0);
          const wordEndUnit = startUnit + String(match[0] || "").replace(/\s+$/u, "").length;
          const endUnit = startUnit + match[0].length;
          return {
            activeStart: pdfAiQuestionUnitIndexToCharCount(value, startUnit),
            activeEnd: pdfAiQuestionUnitIndexToCharCount(value, wordEndUnit),
            endChar: pdfAiQuestionUnitIndexToCharCount(value, endUnit),
            start: index * stepMs,
            end: (index + 1) * stepMs,
          };
        });
      };

      // Added 2026-07-01: maps server /pdf/speak timing rows onto MishiKa dialogue word reveal steps.
      const buildPdfAiQuestionTimedRevealSteps = (text = "", timingPayload = null) => {
        const value = preserveQuestionText(text || "");
        const payload = timingPayload && typeof timingPayload === "object" ? timingPayload : {};
        const rows = Array.isArray(payload.timings) ? payload.timings : [];
        if (!value || !rows.length) {
          return [];
        }
        const tokens = Array.isArray(payload.timing_tokens)
          ? payload.timing_tokens
          : (Array.isArray(payload.timingTokens) ? payload.timingTokens : []);
        const lower = value.toLowerCase();
        let searchUnit = 0;
        let lastEndChar = 0;
        return rows.map((row, rowIndex) => {
          const indexValue = row ? (row.i ?? row.index ?? row.word ?? rowIndex) : rowIndex;
          const tokenInfo = tokens[Math.max(0, Math.floor(Number(indexValue) || 0))] || {};
          const rawToken = clean(tokenInfo.t || tokenInfo.text || (row && (row.t || row.word || row.text)) || "");
          const tokenKey = pdfAiQuestionTokenKey(rawToken);
          if (!tokenKey) {
            return null;
          }
          let foundStart = -1;
          let foundEnd = -1;
          const direct = rawToken ? lower.indexOf(rawToken.toLowerCase(), searchUnit) : -1;
          if (direct >= 0) {
            foundStart = direct;
            foundEnd = direct + rawToken.length;
          } else {
            const wordMatches = Array.from(value.slice(searchUnit).matchAll(/\S+/gu));
            for (const match of wordMatches) {
              if (pdfAiQuestionTokenKey(match[0]) === tokenKey) {
                foundStart = searchUnit + Number(match.index || 0);
                foundEnd = foundStart + match[0].length;
                break;
              }
            }
          }
          if (foundEnd < 0) {
            return null;
          }
          const activeStart = pdfAiQuestionUnitIndexToCharCount(value, foundStart);
          const activeEnd = pdfAiQuestionUnitIndexToCharCount(value, foundEnd);
          while (foundEnd < value.length && /\s/u.test(value.charAt(foundEnd))) {
            foundEnd += 1;
          }
          searchUnit = Math.max(searchUnit, foundEnd);
          const endChar = Math.max(lastEndChar + 1, pdfAiQuestionUnitIndexToCharCount(value, foundEnd));
          lastEndChar = endChar;
          const startValue = row ? (row.s ?? row.start ?? row.startMs ?? 0) : 0;
          const endValue = row ? (row.e ?? row.end ?? row.endMs ?? 0) : 0;
          const start = Math.max(0, Number(startValue) || 0);
          const end = Math.max(start + 1, Number(endValue) || 0);
          return { activeStart, activeEnd, endChar, start: Math.round(start), end: Math.round(end) };
        }).filter(Boolean).sort((a, b) => a.start - b.start);
      };

      const setPdfAiQuestionDialogueText = (dialogue = null, text = "", options = {}) => {
        if (!dialogue) {
          return;
        }
        stopPdfAiQuestionDialogueTyping(dialogue);
        const value = preserveQuestionText(text || "");
        const highlights = normalizePdfAiTextHighlights(options.highlights || [], value);
        if (options.type === false || !value) {
          dialogue.innerHTML = value ? renderPdfAiQuestionPlainDialogueText(value) : "";
          dialogue.removeAttribute("data-vapor-text");
          return;
        }
        const chars = Array.from(value);
        const stepMs = Math.max(12, Math.min(52, Number(options.stepMs || 24) || 24));
        const audio = options.audio && typeof options.audio === "object" ? options.audio : null;
        const timingPayload = options.timingPayload || (audio && audio._pdfAiQuestionTimingPayload) || null;
        const timedSteps = buildPdfAiQuestionTimedRevealSteps(value, timingPayload);
        if (timedSteps.length && audio) {
          dialogue.classList.add("is-typing", "is-vapor-reading");
          dialogue.setAttribute("data-vapor-text", value);
          dialogue.innerHTML = renderPdfAiQuestionPlainDialogueText(value);
          fitPdfAiQuestionPanelToViewport();
          let lastActiveKey = "";
          const activeStepForMs = (ms) => {
            let activeStep = null;
            for (const step of timedSteps) {
              if (ms >= step.start && ms <= step.end) {
                activeStep = step;
                break;
              }
              if (ms > step.end) {
                activeStep = step;
              } else {
                break;
              }
            }
            return activeStep;
          };
          const tick = () => {
            if (!dialogue.isConnected) {
              return;
            }
            if (audio.ended) {
              dialogue.classList.remove("is-typing", "is-vapor-reading");
              dialogue.removeAttribute("data-vapor-text");
              clearPdfAiQuestionActiveVapor(dialogue);
              dialogue.classList.add("is-typing-done");
              fitPdfAiQuestionPanelToViewport();
              return;
            }
            const activeStep = activeStepForMs(Number(audio.currentTime || 0) * 1000);
            const activeKey = activeStep ? `${activeStep.activeStart}:${activeStep.activeEnd}` : "";
            if (activeKey !== lastActiveKey) {
              lastActiveKey = activeKey;
              updatePdfAiQuestionActiveVapor(dialogue, value, activeStep);
            }
            pdfAiQuestionDialogueFrame = window.requestAnimationFrame(tick);
          };
          const start = () => {
            stopPdfAiQuestionDialogueTyping(dialogue);
            dialogue.classList.add("is-typing", "is-vapor-reading");
            dialogue.setAttribute("data-vapor-text", value);
            tick();
          };
          if (audio.paused && !audio.ended) {
            audio.addEventListener("play", start, { once: true });
            dialogue._pdfAiTypeTimer = window.setTimeout(start, 900);
          } else {
            start();
          }
          return;
        }
        const fallbackSteps = buildPdfAiQuestionFallbackWordSteps(value, Math.max(80, stepMs * 5));
        if (fallbackSteps.length) {
          dialogue.classList.add("is-typing", "is-vapor-reading");
          dialogue.setAttribute("data-vapor-text", value);
          dialogue.innerHTML = renderPdfAiQuestionPlainDialogueText(value);
          fitPdfAiQuestionPanelToViewport();
          const totalMs = Math.max(420, fallbackSteps.length * Math.max(80, stepMs * 5));
          let stepIndex = 0;
          const renderActiveFallback = () => {
            const step = fallbackSteps[Math.min(stepIndex, fallbackSteps.length - 1)];
            updatePdfAiQuestionActiveVapor(dialogue, value, step);
            stepIndex += 1;
            if (stepIndex < fallbackSteps.length) {
              dialogue._pdfAiTypeTimer = window.setTimeout(renderActiveFallback, Math.max(60, Math.min(260, stepMs * 5 + Math.floor(Math.random() * 32))));
            }
          };
          renderActiveFallback();
          dialogue._pdfAiVaporDoneTimer = window.setTimeout(() => {
            if (dialogue._pdfAiTypeTimer) {
              window.clearTimeout(dialogue._pdfAiTypeTimer);
              dialogue._pdfAiTypeTimer = 0;
            }
            clearPdfAiQuestionActiveVapor(dialogue);
            dialogue.classList.remove("is-typing", "is-vapor-reading");
            dialogue.removeAttribute("data-vapor-text");
            dialogue.classList.add("is-typing-done");
            fitPdfAiQuestionPanelToViewport();
          }, totalMs);
          return;
        }
        dialogue.classList.add("is-typing", "is-vapor-reading");
        dialogue.setAttribute("data-vapor-text", value);
        dialogue.innerHTML = renderPdfAiQuestionPlainDialogueText(value);
        dialogue._pdfAiTypeTimer = window.setTimeout(() => {
          clearPdfAiQuestionActiveVapor(dialogue);
          dialogue.classList.remove("is-typing", "is-vapor-reading");
          dialogue.removeAttribute("data-vapor-text");
          dialogue.classList.add("is-typing-done");
          fitPdfAiQuestionPanelToViewport();
        }, Math.max(120, stepMs * 4));
      };

      const normalizePdfAiRegionQuestion = (raw = {}) => {
        const source = raw && typeof raw === "object" ? raw : {};
        const rect = normalizePdfSelectionState(source.rect || source.selection || source);
        const question = preserveQuestionText(source.question || source.text || "");
        const imageSrc = normalizePdfAiQuestionImageSrc(source.imageSrc || source.image_src || source.questionImage || source.question_image || source.imageUrl || source.image_url || "");
        const imageAlt = clean(source.imageAlt || source.image_alt || "");
        const regionName = clean(source.regionName || source.region_name || source.aiQuestionRegionName || source.ai_question_region_name || "").slice(0, 120);
        const answers = (Array.isArray(source.answers) ? source.answers : [])
          .map((answer, index) => normalizePdfAiQuestionAnswer(answer, index))
          .filter(Boolean);
        if (!rect || !question) {
          return null;
        }
        if (answers.length && !answers.some((answer) => answer.correct)) {
          answers[0].correct = true;
        }
        const scope = currentPdfAiRegionNoticeScope();
        const rawUnion = source.unionRects || source.union_rects || [];
        const unionRects = Array.isArray(rawUnion) ? rawUnion.map((u) => normalizePdfSelectionState(u)).filter(Boolean) : [];
        return {
          id: clean(source.id || ""),
          path: normalizeServerPathValue(source.path || scope.path),
          mode: clean(source.mode || scope.mode) === "picture" ? "picture" : "pdf",
          page: Math.max(1, Math.floor(Number(source.page || scope.page || 1) || 1)),
          rect,
          unionRects: unionRects.length ? unionRects : [],
          regionName,
          question,
          imageSrc,
          imageAlt,
          questionHighlights: normalizePdfAiTextHighlights(source.questionHighlights || source.question_highlights || [], question),
          questionType: normalizePdfAiQuestionType(source.questionType || source.question_type || "choice"),
          typedMatchPercent: normalizePdfAiTypedMatchPercent(source.typedMatchPercent || source.typed_match_percent || source.matchPercent || source.match_percent || 100),
          randomOrder: Boolean(source.randomOrder || source.random_order),
          pinned: pdfAiQuestionNodeIsPinned(source),
          mikasaIntro: preserveQuestionText(source.mikasaIntro || source.mikasa_intro || ""),
          mikasaIntroHighlights: normalizePdfAiTextHighlights(source.mikasaIntroHighlights || source.mikasa_intro_highlights || [], preserveQuestionText(source.mikasaIntro || source.mikasa_intro || "")),
          voice: clean(source.voice || PDF_AI_QUESTION_DEFAULT_VOICE) || PDF_AI_QUESTION_DEFAULT_VOICE,
          introAudioPath: clean(source.introAudioPath || source.intro_audio_path || ""),
          introAudioMime: clean(source.introAudioMime || source.intro_audio_mime || ""),
          introTimingPayload: pdfAiQuestionTimingPayloadFromVoicePayload(source.introTimingPayload || source.intro_timing_payload || {}),
          title: clean(source.title || question.splitlines()[0] || "AI question"),
          answers: answers.slice(0, 8),
          updatedAt: clean(source.updated_at || source.updatedAt || ""),
        };
      };

      // Added 2026-07-02: keeps optional MishiKa question images normalized across editor, save, and runtime.
      const normalizePdfAiQuestionImageSrc = (value = "") => {
        const text = clean(value);
        if (!text) {
          return "";
        }
        if (/^data:image\//i.test(text)) {
          return text;
        }
        return text.replace(/\\/g, "/");
      };

      // Added 2026-07-02: compresses pasted question images before they are saved into the AI question node.
      const compressPdfAiQuestionImageBlob = (blob = null) => new Promise((resolve, reject) => {
        if (!blob || !String(blob.type || "").toLowerCase().startsWith("image/")) {
          reject(new Error("Clipboard does not contain an image."));
          return;
        }
        const reader = new FileReader();
        reader.onerror = () => reject(new Error("Could not read clipboard image."));
        reader.onload = () => {
          const originalUrl = String(reader.result || "");
          const image = new Image();
          image.onerror = () => resolve(originalUrl);
          image.onload = () => {
            const maxSide = 980;
            const width = Math.max(1, image.naturalWidth || image.width || 1);
            const height = Math.max(1, image.naturalHeight || image.height || 1);
            const scale = Math.min(1, maxSide / Math.max(width, height));
            const targetWidth = Math.max(1, Math.round(width * scale));
            const targetHeight = Math.max(1, Math.round(height * scale));
            const canvas = document.createElement("canvas");
            canvas.width = targetWidth;
            canvas.height = targetHeight;
            const ctx = canvas.getContext("2d");
            if (!ctx) {
              resolve(originalUrl);
              return;
            }
            ctx.drawImage(image, 0, 0, targetWidth, targetHeight);
            try {
              resolve(canvas.toDataURL("image/webp", 0.82));
            } catch (error) {
              try {
                resolve(canvas.toDataURL("image/jpeg", 0.84));
              } catch (fallbackError) {
                resolve(originalUrl);
              }
            }
          };
          image.src = originalUrl;
        };
        reader.readAsDataURL(blob);
      });

      const pdfAiNoticeRectKey = (rect = null) => {
        const safeRect = normalizePdfSelectionState(rect);
        if (!safeRect) {
          return "";
        }
        return ["x", "y", "w", "h"].map((key) => Math.round(Number(safeRect[key] || 0) * 10000)).join(":");
      };
      let pdfAiNoticeAltKeyDown = false;
      const pdfAiNoticeAdminAltActive = (event = null) => Boolean(
        currentAuthIsAdmin
        && ((event && event.altKey) || pdfAiNoticeAltKeyDown || (typeof window !== "undefined" && window.event && window.event.altKey))
      );

      const currentPdfAiQuestionForSelection = () => {
        const rect = getPdfAiNoticeRect();
        const key = pdfAiNoticeRectKey(rect);
        if (!key) {
          return null;
        }
        return (Array.isArray(pdfState.aiRegionQuestions) ? pdfState.aiRegionQuestions : [])
          .find((item) => clean(item && item.id || "") === clean(pdfAiQuestionEditingId) && pdfAiNoticeRectKey(item && item.rect) === key)
          || (Array.isArray(pdfState.aiRegionQuestions) ? pdfState.aiRegionQuestions : [])
            .find((item) => pdfAiNoticeRectKey(item && item.rect) === key) || null;
      };

      const pdfAiQuestionsForSelection = () => {
        const rect = getPdfAiNoticeRect();
        const key = pdfAiNoticeRectKey(rect);
        if (!key) {
          return [];
        }
        return (Array.isArray(pdfState.aiRegionQuestions) ? pdfState.aiRegionQuestions : [])
          .filter((item) => pdfAiNoticeRectKey(item && item.rect) === key);
      };

      const currentPdfAiNoticeForSelection = () => {
        const rect = getPdfAiNoticeRect();
        const key = pdfAiNoticeRectKey(rect);
        if (!key) {
          return null;
        }
        return (Array.isArray(pdfState.aiRegionNotices) ? pdfState.aiRegionNotices : [])
          .find((item) => pdfAiNoticeRectKey(item && item.rect) === key) || null;
      };

      const applyPdfAiRegionNoticePayload = (payload = {}) => {
        const rows = Array.isArray(payload && payload.notices) ? payload.notices : [];
        pdfState.aiRegionNotices = rows.map((item) => normalizePdfAiRegionNotice(item)).filter(Boolean);
        pdfAiRegionNoticeCache[pdfPageSideDataCacheKey(currentPdfAiRegionNoticeScope())] = pdfState.aiRegionNotices.slice();
        if (!pdfState.aiRegionNotices.length) {
          pdfState.aiNoticeRegionsVisible = false;
        }
        renderPdfAiRegionNoticeHitboxes();
        updatePdfChrome();
        return pdfState.aiRegionNotices;
      };

      const applyPdfAiRegionQuestionPayload = (payload = {}) => {
        const rows = Array.isArray(payload && payload.questions) ? payload.questions : [];
        pdfState.aiRegionQuestions = rows.map((item) => normalizePdfAiRegionQuestion(item)).filter(Boolean);
        pdfAiRegionQuestionCache[pdfPageSideDataCacheKey(currentPdfAiRegionNoticeScope())] = pdfState.aiRegionQuestions.slice();
        renderPdfAiRegionNoticeHitboxes();
        updatePdfChrome();
        return pdfState.aiRegionQuestions;
      };

      const loadPdfAiRegionNotices = async (options = {}) => {
        if (!pdfModeActive || !pdfState || !pdfState.path) {
          pdfState.aiRegionNotices = [];
          renderPdfAiRegionNoticeHitboxes();
          return [];
        }
        const scope = currentPdfAiRegionNoticeScope();
        const cacheKey = pdfPageSideDataCacheKey(scope);
        const cached = pdfAiRegionNoticeCache[cacheKey];
        if (cached) {
          pdfState.aiRegionNotices = cached.slice();
          renderPdfAiRegionNoticeHitboxes();
          updatePdfChrome();
          if (!options.force) {
            return pdfState.aiRegionNotices;
          }
        }
        if (pdfAiRegionNoticeLoadInflight[cacheKey]) {
          return pdfAiRegionNoticeLoadInflight[cacheKey];
        }
        const requestToken = ++pdfAiRegionNoticeLoadToken;
        const query = new URLSearchParams();
        query.set("path", scope.path);
        if (scope.lesson_id) query.set("lesson_id", scope.lesson_id);
        if (clean(pdfState && pdfState.lessonHandle || "")) query.set("lesson_handle", clean(pdfState.lessonHandle));
        query.set("page", String(scope.page));
        query.set("mode", scope.mode);
        query.set("client_source", clean(options.clientSource || "pdf_side_data_ai_notices"));
        const promise = (async () => {
          const { payload } = await fetchAuthJson(`/space-pdf/ai-region-notices?${query.toString()}`);
          if (requestToken !== pdfAiRegionNoticeLoadToken || !isSamePdfAiRegionNoticeScope(scope)) {
            return [];
          }
          return applyPdfAiRegionNoticePayload(payload || {});
        })();
        pdfAiRegionNoticeLoadInflight[cacheKey] = promise;
        try {
          return await promise;
        } catch (error) {
          if (requestToken === pdfAiRegionNoticeLoadToken && isSamePdfAiRegionNoticeScope(scope)) {
            pdfState.aiRegionNotices = [];
            renderPdfAiRegionNoticeHitboxes();
          }
          return [];
        } finally {
          if (pdfAiRegionNoticeLoadInflight[cacheKey] === promise) {
            delete pdfAiRegionNoticeLoadInflight[cacheKey];
          }
        }
      };

      const positionPdfAiNoticeNode = (node, rect = null) => {
        const safeRect = normalizePdfSelectionState(rect);
        if (!node || !safeRect || !pdfEls || !pdfEls.image) {
          return;
        }
        const width = Math.max(1, Number(pdfEls.image.clientWidth || pdfEls.wrap && pdfEls.wrap.clientWidth || 0) || 1);
        const height = Math.max(1, Number(pdfEls.image.clientHeight || pdfEls.wrap && pdfEls.wrap.clientHeight || 0) || 1);
        Object.assign(node.style, {
          left: `${Math.round(width * safeRect.x)}px`,
          top: `${Math.round(height * safeRect.y)}px`,
          width: `${Math.round(width * safeRect.w)}px`,
          height: `${Math.round(height * safeRect.h)}px`,
        });
      };

      const renderPdfAiRegionNoticeHitboxes = () => {
        if (!pdfEls || !pdfEls.aiNoticeLayer) {
          return;
        }
        const layer = pdfEls.aiNoticeLayer;
        _pdfMiniFireballAnims.clear();
        layer.replaceChildren();
        const assistRegionsVisible = !pdfState || pdfState.aiAssistRegionsVisible !== false;
        layer.hidden = !(pdfModeActive && pdfState && pdfState.path && assistRegionsVisible);
        layer.classList.toggle("is-user-hidden", !assistRegionsVisible);
        if (layer.hidden) {
          hidePdfAiNoticeFireball({ immediate: true });
          return;
        }
        layer.classList.toggle("is-admin-visible", Boolean(currentAuthIsAdmin && pdfState.aiNoticeRegionsVisible));
        const notices = (Array.isArray(pdfState.aiRegionNotices) ? pdfState.aiRegionNotices : [])
          .filter((item) => item && item.text && item.rect);
        const questionRows = (Array.isArray(pdfState.aiRegionQuestions) ? pdfState.aiRegionQuestions : [])
          .filter((item) => item && item.question && item.rect && Array.isArray(item.answers));
        if (!notices.length && !questionRows.length) {
          hidePdfAiNoticeFireball({ immediate: false });
          return;
        }
        if (!notices.length) {
          hidePdfAiNoticeFireball({ immediate: false });
        }
        const randomMiniPoint = () => ({
          x: Math.round(8 + Math.random() * 76),
          y: Math.round(8 + Math.random() * 76),
        });
        notices.forEach((notice, index) => {
          const isUnion = Boolean(notice.unionRects && notice.unionRects.length > 1 && pdfEls && pdfEls.image);
          if (isUnion) {
            const imgW = Math.max(1, Number(pdfEls.image.clientWidth || pdfEls.wrap.clientWidth || layer.clientWidth || 0) || 1);
            const imgH = Math.max(1, Number(pdfEls.image.clientHeight || pdfEls.wrap.clientHeight || layer.clientHeight || 0) || 1);
              const pixelRects = notice.unionRects.map((r) => ({
                x: Math.round(r.x * imgW),
                y: Math.round(r.y * imgH),
                w: Math.round(r.w * imgW),
                h: Math.round(r.h * imgH),
              }));
              const unionMinX = Math.min(...pixelRects.map(r => r.x));
              const unionMinY = Math.min(...pixelRects.map(r => r.y));
              const unionMaxX = Math.max(...pixelRects.map(r => r.x + r.w));
              const unionMaxY = Math.max(...pixelRects.map(r => r.y + r.h));
              const unionW = unionMaxX - unionMinX;
              const unionH = unionMaxY - unionMinY;
              const pathData = buildPdfUnionBoundaryPath(pixelRects);
              if (pathData) {
                const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
                svg.setAttribute("class", "ft-pdf-ai-notice-union-svg");
                svg.setAttribute("width", String(unionW));
                svg.setAttribute("height", String(unionH));
                svg.setAttribute("viewBox", `${unionMinX} ${unionMinY} ${unionW} ${unionH}`);
                svg.style.left = unionMinX + "px";
                svg.style.top = unionMinY + "px";
                svg.dataset.noticeId = notice.id || `notice-${index}`;
                svg.dataset.noticeIndex = String(index + 1);
                const path = document.createElementNS("http://www.w3.org/2000/svg", "path");
              path.setAttribute("class", "ft-pdf-ai-notice-union-path");
              path.setAttribute("d", pathData);
              path.dataset.noticeId = notice.id || `notice-${index}`;
              path.dataset.noticeIndex = String(index + 1);
              path.classList.toggle("is-active", pdfAiNoticeRectKey(notice.rect) === pdfAiNoticeRectKey(pdfState.selection));
              svg.classList.toggle("is-active", pdfAiNoticeRectKey(notice.rect) === pdfAiNoticeRectKey(pdfState.selection));
                svg.appendChild(path);
                const miniFireballs = [];
                notice.unionRects.forEach((r) => {
                  const cx = (r.x + r.w / 2) * imgW;
                  const cy = (r.y + r.h / 2) * imgH;
                  const foreign = document.createElementNS("http://www.w3.org/2000/svg", "foreignObject");
                foreign.setAttribute("x", String(Math.round(cx - 26)));
                foreign.setAttribute("y", String(Math.round(cy - 26)));
                foreign.setAttribute("width", "52");
                foreign.setAttribute("height", "52");
                foreign.setAttribute("aria-hidden", "true");
                const mini = document.createElement("span");
                mini.className = "ft-pdf-ai-notice-mini-fireball";
                mini.innerHTML = `
                  <span class="ft-world-fireball" style="--world-facing:1">
                    <span class="ft-world-eye is-left"></span>
                    <span class="ft-world-eye is-right"></span>
                    <span class="ft-world-cheek is-left"></span>
                    <span class="ft-world-cheek is-right"></span>
                    <span class="ft-world-smile"></span>
                    <span class="ft-world-bandage"></span>
                    <span class="ft-world-bump"></span>
                    <span class="ft-world-sweat"></span>
                  </span>
                `;
                foreign.appendChild(mini);
                svg.appendChild(foreign);
                miniFireballs.push({ foreign, mini, cx, cy });
              });
              svg._unionBounds = { minX: unionMinX, minY: unionMinY, maxX: unionMaxX, maxY: unionMaxY };
              svg._unionPixelRects = pixelRects;
              registerPdfMiniFireball(svg);
              const connectEvents = (el) => {
                el.addEventListener("pointerenter", () => {
                  el.classList.add("is-hovering");
                  svg.classList.add("is-hovering");
                  schedulePdfAiNoticeHoverFireball(notice, el);
                });
                el.addEventListener("pointerleave", () => {
                  el.classList.remove("is-hovering");
                  svg.classList.remove("is-hovering");
                  clearPdfAiNoticeHoverFireball();
                });
                el.addEventListener("pointerdown", (event) => {
                  if (event.button != null && event.button !== 0) {
                    return;
                  }
                  event.preventDefault();
                  event.stopPropagation();
                  if (pdfAiNoticeAdminAltActive(event)) {
                    selectPdfAiNoticeRegion(notice, { openEditor: true, hitbox: el });
                  }
                });
                el.addEventListener("click", (event) => {
                  event.preventDefault();
                  event.stopPropagation();
                  if (pdfAiNoticeAdminAltActive(event)) {
                    selectPdfAiNoticeRegion(notice, { openEditor: true, hitbox: el });
                    return;
                  }
                  showPdfAiNoticeFireball(notice, el);
                });
                el.addEventListener("dblclick", (event) => {
                  event.preventDefault();
                  event.stopPropagation();
                  if (pdfAiNoticeAdminAltActive(event)) {
                    selectPdfAiNoticeRegion(notice, { openEditor: true, hitbox: el });
                    return;
                  }
                  showPdfAiNoticeFireball(notice, el, { instant: true });
                });
              };
              connectEvents(path);
              layer.appendChild(svg);
            }
          } else {
            const imgW = Math.max(1, Number(pdfEls.image.clientWidth || pdfEls.wrap.clientWidth || layer.clientWidth || 0) || 1);
            const imgH = Math.max(1, Number(pdfEls.image.clientHeight || pdfEls.wrap.clientHeight || layer.clientHeight || 0) || 1);
            const r = notice.rect;
            const pixelRect = {
              x: Math.round(r.x * imgW),
              y: Math.round(r.y * imgH),
              w: Math.round(r.w * imgW),
              h: Math.round(r.h * imgH),
            };
            const { x: rx, y: ry, w: rw, h: rh } = pixelRect;
            const pathData = `M${rx},${ry}L${rx + rw},${ry}L${rx + rw},${ry + rh}L${rx},${ry + rh}Z`;
            if (pathData) {
              const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
              svg.setAttribute("class", "ft-pdf-ai-notice-union-svg");
              svg.setAttribute("width", String(rw));
              svg.setAttribute("height", String(rh));
              svg.setAttribute("viewBox", `${rx} ${ry} ${rw} ${rh}`);
              svg.style.left = rx + "px";
              svg.style.top = ry + "px";
              svg.dataset.noticeId = notice.id || `notice-${index}`;
              svg.dataset.noticeIndex = String(index + 1);
              const path = document.createElementNS("http://www.w3.org/2000/svg", "path");
              path.setAttribute("class", "ft-pdf-ai-notice-union-path");
              path.setAttribute("d", pathData);
              path.dataset.noticeId = notice.id || `notice-${index}`;
              path.dataset.noticeIndex = String(index + 1);
              path.classList.toggle("is-active", pdfAiNoticeRectKey(notice.rect) === pdfAiNoticeRectKey(pdfState.selection));
              svg.classList.toggle("is-active", pdfAiNoticeRectKey(notice.rect) === pdfAiNoticeRectKey(pdfState.selection));
              svg.appendChild(path);
              const cx = (r.x + r.w / 2) * imgW;
              const cy = (r.y + r.h / 2) * imgH;
              const foreign = document.createElementNS("http://www.w3.org/2000/svg", "foreignObject");
              foreign.setAttribute("x", String(Math.round(cx - 26)));
              foreign.setAttribute("y", String(Math.round(cy - 26)));
              foreign.setAttribute("width", "52");
              foreign.setAttribute("height", "52");
              foreign.setAttribute("aria-hidden", "true");
              const mini = document.createElement("span");
              mini.className = "ft-pdf-ai-notice-mini-fireball";
              mini.innerHTML = `
                <span class="ft-world-fireball" style="--world-facing:1">
                  <span class="ft-world-eye is-left"></span>
                  <span class="ft-world-eye is-right"></span>
                  <span class="ft-world-cheek is-left"></span>
                  <span class="ft-world-cheek is-right"></span>
                  <span class="ft-world-smile"></span>
                  <span class="ft-world-bandage"></span>
                  <span class="ft-world-bump"></span>
                  <span class="ft-world-sweat"></span>
                </span>
              `;
              foreign.appendChild(mini);
              svg.appendChild(foreign);
              svg._miniFireballs = [{ foreign, mini, cx, cy }];
              svg._unionPixelRects = [pixelRect];
              registerPdfMiniFireball(svg);
              const connectEvents = (el) => {
                el.addEventListener("pointerenter", () => {
                  el.classList.add("is-hovering");
                  svg.classList.add("is-hovering");
                  schedulePdfAiNoticeHoverFireball(notice, el);
                });
                el.addEventListener("pointerleave", () => {
                  el.classList.remove("is-hovering");
                  svg.classList.remove("is-hovering");
                  clearPdfAiNoticeHoverFireball();
                });
                el.addEventListener("pointerdown", (event) => {
                  if (event.button != null && event.button !== 0) {
                    return;
                  }
                  event.preventDefault();
                  event.stopPropagation();
                  if (pdfAiNoticeAdminAltActive(event)) {
                    selectPdfAiNoticeRegion(notice, { openEditor: true, hitbox: el });
                  }
                });
                el.addEventListener("click", (event) => {
                  event.preventDefault();
                  event.stopPropagation();
                  if (pdfAiNoticeAdminAltActive(event)) {
                    selectPdfAiNoticeRegion(notice, { openEditor: true, hitbox: el });
                    return;
                  }
                  showPdfAiNoticeFireball(notice, el);
                });
                el.addEventListener("dblclick", (event) => {
                  event.preventDefault();
                  event.stopPropagation();
                  if (pdfAiNoticeAdminAltActive(event)) {
                    selectPdfAiNoticeRegion(notice, { openEditor: true, hitbox: el });
                    return;
                  }
                  showPdfAiNoticeFireball(notice, el, { instant: true });
                });
              };
              connectEvents(path);
              layer.appendChild(svg);
            }
          }
        });
        const questionGroups = [];
        const questionGroupByRect = new Map();
        questionRows.forEach((item) => {
          const key = pdfAiNoticeRectKey(item && item.rect);
          if (!key) {
            return;
          }
          let group = questionGroupByRect.get(key);
          if (!group) {
            group = { question: item, nodes: [] };
            questionGroupByRect.set(key, group);
            questionGroups.push(group);
          }
          group.nodes.push(item);
        });
        const questions = questionGroups.map((group) => ({ ...group.question, _questionNodes: group.nodes }));
        questions.forEach((question, index) => {
          const rects = Array.isArray(question.unionRects) && question.unionRects.length ? question.unionRects : [question.rect];
          const imgW = Math.max(1, Number(pdfEls.image.clientWidth || pdfEls.wrap.clientWidth || layer.clientWidth || 0) || 1);
          const imgH = Math.max(1, Number(pdfEls.image.clientHeight || pdfEls.wrap.clientHeight || layer.clientHeight || 0) || 1);
          rects.forEach((r, rectIndex) => {
            const safe = normalizePdfSelectionState(r);
            if (!safe) {
              return;
            }
            const rx = Math.round(safe.x * imgW);
            const ry = Math.round(safe.y * imgH);
            const rw = Math.max(3, Math.round(safe.w * imgW));
            const rh = Math.max(3, Math.round(safe.h * imgH));
            const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
            svg.setAttribute("class", "ft-pdf-ai-question-region");
            svg.setAttribute("width", String(rw));
            svg.setAttribute("height", String(rh));
            svg.setAttribute("viewBox", `${rx} ${ry} ${rw} ${rh}`);
            svg.style.left = rx + "px";
            svg.style.top = ry + "px";
            svg.dataset.questionId = question.id || `question-${index}`;
            svg.dataset.questionIndex = String(index + 1);
            const path = document.createElementNS("http://www.w3.org/2000/svg", "path");
            path.setAttribute("class", "ft-pdf-ai-question-path");
            path.setAttribute("d", `M${rx},${ry}L${rx + rw},${ry}L${rx + rw},${ry + rh}L${rx},${ry + rh}Z`);
            const badge = document.createElement("span");
            badge.className = "ft-pdf-ai-question-badge";
            const groupedNodes = Array.isArray(question._questionNodes) && question._questionNodes.length ? question._questionNodes : [question];
            const groupRegionKey = pdfAiQuestionRegionKey(groupedNodes);
            badge.dataset.aiQuestionRegionKey = groupRegionKey;
            badge.textContent = groupedNodes.length > 1 ? String(groupedNodes.length) : "?";
            const foreign = document.createElementNS("http://www.w3.org/2000/svg", "foreignObject");
            foreign.setAttribute("x", String(Math.round(rx + rw - 72)));
            foreign.setAttribute("y", String(Math.round(ry + 6)));
            foreign.setAttribute("width", "68");
            foreign.setAttribute("height", "24");
            foreign.appendChild(badge);
            svg.appendChild(path);
            svg.appendChild(foreign);
            const clickbox = document.createElement("button");
            clickbox.type = "button";
            clickbox.className = "ft-pdf-ai-question-clickbox";
            clickbox.style.left = rx + "px";
            clickbox.style.top = ry + "px";
            clickbox.style.width = rw + "px";
            clickbox.style.height = rh + "px";
            clickbox.dataset.questionId = question.id || `question-${index}`;
            clickbox.dataset.questionIndex = String(index + 1);
            clickbox.setAttribute("aria-label", groupedNodes.length > 1 ? `Open one of ${groupedNodes.length} AI questions` : "Open AI question");
            const pickQuestionNode = () => groupedNodes[Math.floor(Math.random() * groupedNodes.length)] || question;
            const openQuestion = async (event, instant = false) => {
              event.preventDefault();
              event.stopPropagation();
              const pickedQuestion = pickQuestionNode();
              if (pdfAiNoticeAdminAltActive(event)) {
                pdfAiQuestionEditingId = clean(pickedQuestion && pickedQuestion.id || "");
                selectPdfAiQuestionRegion(pickedQuestion, { openEditor: true, hitbox: clickbox });
                return;
              }
              const randomOrder = Boolean((groupedNodes[0] || pickedQuestion || {}).randomOrder);
              const baseRegionKey = pdfAiQuestionRegionKey(groupedNodes);
              const savedProgress = await loadPdfAiQuestionProgress(baseRegionKey, currentPdfAiRegionNoticeScope());
              const savedOrder = savedProgress && Array.isArray(savedProgress.order) ? savedProgress.order : [];
              const questionSequence = savedOrder.length
                ? pdfAiQuestionOrderByIds(groupedNodes, savedOrder)
                : (randomOrder ? pdfAiQuestionShuffleNodes(groupedNodes) : groupedNodes.slice());
              const progressState = makePdfAiQuestionProgressState(questionSequence, 0, {
                regionKey: baseRegionKey,
                randomOrder,
                savedProgress,
              });
              progressState.sequence = questionSequence;
              showPdfAiQuestionStartGate({
                instant,
                rawNodes: groupedNodes,
                questionSequence,
                regionKey: baseRegionKey,
                randomOrder,
                progressState,
                hitbox: clickbox,
              });
            };
            clickbox.addEventListener("pointerenter", () => svg.classList.add("is-hovering"));
            clickbox.addEventListener("pointerleave", () => svg.classList.remove("is-hovering"));
            clickbox.addEventListener("focus", () => svg.classList.add("is-hovering"));
            clickbox.addEventListener("blur", () => svg.classList.remove("is-hovering"));
            svg.addEventListener("click", (event) => openQuestion(event, false));
            svg.addEventListener("dblclick", (event) => openQuestion(event, true));
            svg.addEventListener("contextmenu", (event) => {
              if (currentAuthIsAdmin) {
                event.preventDefault();
                event.stopPropagation();
                const pickedQuestion = pickQuestionNode();
                pdfAiQuestionEditingId = clean(pickedQuestion && pickedQuestion.id || "");
                selectPdfAiQuestionRegion(pickedQuestion, { openEditor: true, hitbox: clickbox });
              }
            });
            clickbox.addEventListener("click", (event) => openQuestion(event, false));
            clickbox.addEventListener("dblclick", (event) => openQuestion(event, true));
            clickbox.addEventListener("contextmenu", (event) => {
              if (currentAuthIsAdmin) {
                event.preventDefault();
                event.stopPropagation();
                const pickedQuestion = pickQuestionNode();
                pdfAiQuestionEditingId = clean(pickedQuestion && pickedQuestion.id || "");
                selectPdfAiQuestionRegion(pickedQuestion, { openEditor: true, hitbox: clickbox });
              }
            });
            layer.appendChild(svg);
            layer.appendChild(clickbox);
            if (pdfAiQuestionProgressCache.has(groupRegionKey)) {
              updatePdfAiQuestionRegionScoreBadges(groupRegionKey, pdfAiQuestionProgressCache.get(groupRegionKey), groupedNodes.length);
            } else {
              const localProgress = readPdfAiQuestionLocalProgress(groupRegionKey);
              if (localProgress) {
                pdfAiQuestionProgressCache.set(groupRegionKey, localProgress);
                updatePdfAiQuestionRegionScoreBadges(groupRegionKey, localProgress, groupedNodes.length);
              }
            }
          });
        });
      };

      const togglePdfAiNoticeRegions = (visible = !pdfState.aiNoticeRegionsVisible) => {
        pdfState.aiNoticeRegionsVisible = Boolean(currentAuthIsAdmin && visible);
        if (!pdfState.aiNoticeRegionsVisible) {
          clearPdfAiNoticeHoverFireball();
          hidePdfAiNoticeFireball({ immediate: true });
        }
        renderPdfAiRegionNoticeHitboxes();
        updatePdfChrome();
        setPdfStatus(pdfState.aiNoticeRegionsVisible
          ? "AI notice regions are visible. Click a region to edit or delete it."
          : "AI notice regions hidden.");
      };

      // Added 2026-07-01: user-facing lightweight toggle for all AI notice/question overlay regions.
      const togglePdfAiAssistRegions = (visible = !(pdfState && pdfState.aiAssistRegionsVisible !== false)) => {
        if (!pdfState) return;
        pdfState.aiAssistRegionsVisible = Boolean(visible);
        if (!pdfState.aiAssistRegionsVisible) {
          clearPdfAiNoticeHoverFireball();
          hidePdfAiNoticeFireball({ immediate: true });
          hidePdfAiQuestionPanel();
          closePdfAiNoticeEditor();
        }
        renderPdfAiRegionNoticeHitboxes();
        updatePdfChrome();
        setPdfStatus(pdfState.aiAssistRegionsVisible
          ? "AI notice and question regions are visible."
          : "AI notice and question regions are hidden for a lighter view.");
      };

      const selectPdfAiNoticeRegion = (notice = null, options = {}) => {
        if (!notice || !notice.rect) {
          return;
        }
        const rect = normalizePdfSelectionState(notice.rect);
        if (!rect) {
          return;
        }
        const key = pdfAiNoticeRectKey(rect);
        const currentSelections = normalizePdfSelectionList(
          Array.isArray(pdfState.selections) ? pdfState.selections : []
        );
        const alreadySelected = currentSelections.some((s) => pdfAiNoticeRectKey(s) === key);
        const unionRects = Array.isArray(notice.unionRects) && notice.unionRects.length
          ? notice.unionRects.map((u) => normalizePdfSelectionState(u)).filter(Boolean)
          : [];
        if (alreadySelected && currentSelections.length > 1) {
          pdfState.selections = currentSelections;
        } else {
          pdfState.selections = unionRects.length ? unionRects : [rect];
        }
        pdfState.selection = pdfState.selections[pdfState.selections.length - 1];
        setPdfShiftSelectionActive(false);
        clearPdfPointSelection();
        syncPdfSelectionOverlay(true);
        updatePdfChrome();
        renderPdfAiRegionNoticeHitboxes();
        if (options.hitbox && !options.openEditor) {
          showPdfAiNoticeFireball(notice, options.hitbox);
        }
        if (options.openEditor) {
          void openPdfAiNoticeEditor();
        }
      };

      const pdfAiNoticeRectContainsPoint = (rect = null, x = 0, y = 0, pad = 0.002) => {
        const safe = normalizePdfSelectionState(rect);
        if (!safe) {
          return false;
        }
        return x >= safe.x - pad
          && y >= safe.y - pad
          && x <= safe.x + safe.w + pad
          && y <= safe.y + safe.h + pad;
      };

      const noticeAtPdfImagePoint = (x = 0, y = 0) => {
        const rows = Array.isArray(pdfState && pdfState.aiRegionNotices) ? pdfState.aiRegionNotices : [];
        for (let index = rows.length - 1; index >= 0; index -= 1) {
          const notice = rows[index];
          if (!notice || !notice.rect) {
            continue;
          }
          const unionRects = Array.isArray(notice.unionRects) ? notice.unionRects : [];
          if (unionRects.some((rect) => pdfAiNoticeRectContainsPoint(rect, x, y))) {
            return notice;
          }
          if (pdfAiNoticeRectContainsPoint(notice.rect, x, y)) {
            return notice;
          }
        }
        return null;
      };

      const handlePdfAiNoticeAdminAltOpen = (event) => {
        if (!pdfAiNoticeAdminAltActive(event) || !event || event.ctrlKey || event.metaKey || event.button !== 0) {
          return false;
        }
        if (!pdfModeActive || !pdfEls || !pdfEls.image || !pdfState || !pdfState.path) {
          return false;
        }
        const imageRect = pdfEls.image.getBoundingClientRect();
        const width = Math.max(1, imageRect.width || 0);
        const height = Math.max(1, imageRect.height || 0);
        const x = (Number(event.clientX || 0) - imageRect.left) / width;
        const y = (Number(event.clientY || 0) - imageRect.top) / height;
        if (x < 0 || x > 1 || y < 0 || y > 1) {
          return false;
        }
        const notice = noticeAtPdfImagePoint(x, y);
        if (!notice) {
          return false;
        }
        event.preventDefault();
        event.stopPropagation();
        if (typeof event.stopImmediatePropagation === "function") {
          event.stopImmediatePropagation();
        }
        const hitbox = event.target && event.target.closest ? event.target.closest(".ft-pdf-ai-notice-union-svg,.ft-pdf-ai-notice-hitbox") : null;
        selectPdfAiNoticeRegion(notice, { openEditor: true, hitbox });
        return true;
      };

      const setPdfAiNoticeEditorStatus = (message = "", tone = "") => {
        if (!pdfEls || !pdfEls.aiNoticeStatus) {
          return;
        }
        pdfEls.aiNoticeStatus.textContent = message;
        pdfEls.aiNoticeStatus.dataset.tone = tone;
      };

      const pdfAiNoticeHistoryText = (item = {}) => {
        return preserveQuestionText(item.vietnamese || item.answer_vi || item.english || item.answer_en || item.text || "");
      };

      const pdfAiNoticeHistoryMatchesScope = (item = {}) => {
        const scope = currentPdfAiRegionNoticeScope();
        const file = normalizeServerPathValue(item.file || (item.context && item.context.file) || "");
        const rawPage = item.page || (item.context && item.context.page) || "";
        const page = rawPage ? Math.max(1, Math.floor(Number(rawPage) || 1)) : 0;
        const space = clean(item.space || (item.context && item.context.space) || "");
        if (file && file !== scope.path) {
          return false;
        }
        if (page && page !== scope.page) {
          return false;
        }
        if (space && scope.mode === "picture" && !/picture/i.test(space)) {
          return false;
        }
        if (space && scope.mode === "pdf" && /picture/i.test(space)) {
          return false;
        }
        return true;
      };

      const renderPdfAiNoticeHistory = (rows = []) => {
        if (!pdfEls || !pdfEls.aiNoticeHistoryList) {
          return;
        }
        const list = pdfEls.aiNoticeHistoryList;
        list.replaceChildren();
        const allRows = Array.isArray(rows) ? rows : [];
        const scopedRows = allRows.filter(pdfAiNoticeHistoryMatchesScope);
        const scoped = scopedRows.length ? scopedRows : allRows;
        const selectedText = clean(pdfState.ocrText || (pdfEls.exploreInput && pdfEls.exploreInput.value) || "");
        const ranked = scoped.map((item) => {
          const body = pdfAiNoticeHistoryText(item);
          const title = clean(item.title || "Ghost AI answer");
          const score = selectedText && (body.includes(selectedText.slice(0, 80)) || title.includes(selectedText.slice(0, 80))) ? 2 : 1;
          return { item, body, title, score };
        }).filter((row) => row.body).sort((a, b) => b.score - a.score).slice(0, 20);
        if (!ranked.length) {
          const empty = document.createElement("div");
          empty.className = "ft-pdf-ai-notice-history-empty";
          empty.textContent = "No matching Ghost AI history yet.";
          list.appendChild(empty);
          return;
        }
        ranked.forEach(({ item, body, title }) => {
          const button = document.createElement("button");
          button.type = "button";
          button.className = "ft-pdf-ai-notice-history-row";
          button.dataset.pdfAction = "useAiNoticeHistory";
          button.dataset.historyId = clean(item.id || "");
          const strong = document.createElement("strong");
          strong.textContent = title;
          const span = document.createElement("span");
          span.textContent = body.slice(0, 420);
          button.append(strong, span);
          list.appendChild(button);
        });
      };

      const loadPdfAiNoticeHistory = async () => {
        renderPdfAiNoticeHistory(pdfState.agentHistory || aiAgentHistoryCache || []);
        setPdfAiNoticeEditorStatus("Loading Ghost AI history...", "");
        try {
          const { payload } = await fetchAuthJson("/ai-agent/history?limit=120");
          pdfState.agentHistory = pdfAgentHistoryRows(payload && payload.history);
          aiAgentHistoryCache = pdfState.agentHistory.slice();
          renderPdfAiNoticeHistory(pdfState.agentHistory);
          setPdfAiNoticeEditorStatus("History ready.", "ok");
        } catch (error) {
          setPdfAiNoticeEditorStatus(error && error.message ? error.message : "Could not load history.", "error");
        }
      };

      const getPdfAiNoticeRect = () => {
        const selections = normalizePdfSelectionList(Array.isArray(pdfState && pdfState.selections) ? pdfState.selections : (pdfState && pdfState.selection ? [pdfState.selection] : []));
        if (selections.length > 1) {
          let minX = 1, minY = 1, maxX = 0, maxY = 0;
          selections.forEach((s) => {
            minX = Math.min(minX, s.x);
            minY = Math.min(minY, s.y);
            maxX = Math.max(maxX, s.x + s.w);
            maxY = Math.max(maxY, s.y + s.h);
          });
          minX = Math.max(0, minX);
          minY = Math.max(0, minY);
          maxX = Math.min(1, maxX);
          maxY = Math.min(1, maxY);
          const w = maxX - minX;
          const h = maxY - minY;
          if (w > 0.001 && h > 0.001) {
            return { x: minX, y: minY, w, h, unionRects: selections.map((s) => ({ x: s.x, y: s.y, w: s.w, h: s.h })) };
          }
        }
        return normalizePdfSelectionState(pdfState && pdfState.selection);
      };

      const openPdfAiNoticeEditor = async () => {
        if (!currentAuthIsAdmin) {
          setPdfStatus("Only admin can set AI notices.", true);
          return;
        }
        const rect = getPdfAiNoticeRect();
        if (!rect) {
          setPdfStatus("Select a Ghost Eye region first.", true);
          return;
        }
        if (!pdfEls || !pdfEls.aiNoticeModal || !pdfEls.aiNoticeInput) {
          return;
        }
        hidePdfAiNoticeFireball({ immediate: true });
        const existing = currentPdfAiNoticeForSelection();
        pdfEls.aiNoticeInput.value = existing ? existing.text : clean(pdfEls.exploreInput && pdfEls.exploreInput.value || pdfState.ocrText || "");
        pdfEls.aiNoticeInput._pdfAiTextHighlights = normalizePdfAiTextHighlights(existing && (existing.noticeTextHighlights || existing.notice_text_highlights || existing.textHighlights || existing.text_highlights) || [], pdfEls.aiNoticeInput.value || "");
        bindPdfAiNoticeHighlightTextarea(pdfEls.aiNoticeInput, {
          title: "Notice text color",
          setStatus: setPdfAiNoticeEditorStatus,
        });
        renderPdfAiNoticeTextHighlightPreview(pdfEls.aiNoticeInput);
        if (pdfEls.aiNoticeTextFont) {
          pdfEls.aiNoticeTextFont.value = normalizePdfAiNoticeFont(existing && (existing.noticeTextFont || existing.notice_text_font || existing.textFont || existing.text_font) || "Inter");
        }
        if (pdfEls.aiNoticeDisplayMode) {
          const mode = clean(existing && (existing.displayMode || existing.display_mode) || pdfEls.aiNoticeDisplayMode.value || "type").toLowerCase();
          pdfEls.aiNoticeDisplayMode.value = mode === "full" ? "full" : "type";
        }
        if (pdfEls.aiNoticeStyle) {
          const style = clean(existing && (existing.noticeStyle || existing.notice_style || existing.style) || pdfEls.aiNoticeStyle.value || "fireball").toLowerCase();
          pdfEls.aiNoticeStyle.value = style === "image" ? "image" : "fireball";
        }
        if (pdfEls.aiNoticeImageSrc) {
          setPdfAiNoticeEditorImage(existing && (existing.imageSrc || existing.image_src || existing.imagePath || existing.image_path) || "", { status: false });
        }
        if (pdfEls.aiNoticeTheme) {
          const theme = clean(existing && (existing.noticeTheme || existing.notice_theme || existing.theme) || pdfEls.aiNoticeTheme.value || "red").toLowerCase();
          pdfEls.aiNoticeTheme.value = theme === "cyan" ? "cyan" : "red";
        }
        if (pdfEls.aiNoticeFocusText) {
          pdfEls.aiNoticeFocusText.value = preservePdfAiNoticeText(existing && (existing.focusText || existing.focus_text || existing.focus || existing.hudText || existing.hud_text) || "", 520);
          pdfEls.aiNoticeFocusText._pdfAiTextHighlights = normalizePdfAiTextHighlights(existing && (existing.focusTextHighlights || existing.focus_text_highlights || existing.focusHighlights || existing.focus_highlights) || [], pdfEls.aiNoticeFocusText.value || "");
          bindPdfAiNoticeHighlightTextarea(pdfEls.aiNoticeFocusText, {
            title: "Focus HUD color",
            setStatus: setPdfAiNoticeEditorStatus,
          });
          renderPdfAiNoticeTextHighlightPreview(pdfEls.aiNoticeFocusText);
        }
        if (pdfEls.aiNoticeFocusFont) {
          pdfEls.aiNoticeFocusFont.value = normalizePdfAiNoticeFont(existing && (existing.focusTextFont || existing.focus_text_font || existing.focusFont || existing.focus_font) || "Inter");
        }
        if (pdfEls.aiNoticeAudioText) {
          pdfEls.aiNoticeAudioText.value = preservePdfAiNoticeText(existing && (existing.audioText || existing.audio_text) || pdfEls.aiNoticeInput.value || "", 2400);
        }
        if (pdfEls.aiNoticeSpeakMode) {
          const speakMode = clean(existing && (existing.speakMode || existing.speak_mode) || pdfEls.aiNoticeSpeakMode.value || "once").toLowerCase();
          pdfEls.aiNoticeSpeakMode.value = speakMode === "click" || speakMode === "when_click" || speakMode === "every" ? "click" : (speakMode === "off" ? "off" : "once");
        }
        if (pdfEls.aiNoticeVoice) {
          renderPdfSharedAudioVoiceOptions(pdfAudioMarkerVoicePayload || {});
          pdfEls.aiNoticeVoice.value = clean(existing && existing.voice || pdfEls.aiNoticeVoice.value || PDF_SHARED_AUDIO_DEFAULT_VOICE) || PDF_SHARED_AUDIO_DEFAULT_VOICE;
        }
        pdfEls.aiNoticeModal.classList.remove("is-hidden");
        pdfEls.aiNoticeModal.setAttribute("aria-hidden", "false");
        setPdfAiNoticeEditorStatus(existing ? "Editing notice for this region." : "New notice for this region.", "");
        window.setTimeout(() => {
          try { pdfEls.aiNoticeInput.focus(); } catch (error) {}
        }, 40);
        await Promise.all([loadPdfAiNoticeHistory(), loadPdfSharedAudioVoices(), loadPdfAiNoticeImageList()]);
      };

      const closePdfAiNoticeEditor = () => {
        if (!pdfEls || !pdfEls.aiNoticeModal) {
          return;
        }
        pdfEls.aiNoticeModal.classList.add("is-hidden");
        pdfEls.aiNoticeModal.setAttribute("aria-hidden", "true");
      };

      const usePdfAiNoticeHistory = (id = "") => {
        if (!pdfEls || !pdfEls.aiNoticeInput) {
          return;
        }
        const wanted = clean(id);
        const rows = Array.isArray(pdfState.agentHistory) ? pdfState.agentHistory : [];
        const item = rows.find((row) => clean(row && row.id) === wanted);
        const body = item ? pdfAiNoticeHistoryText(item) : "";
        if (body) {
          pdfEls.aiNoticeInput.value = body;
          setPdfAiNoticeEditorStatus("Copied this answer into the notice box.", "ok");
        }
      };

      const savePdfAiRegionNotice = async () => {
        if (!currentAuthIsAdmin) {
          setPdfAiNoticeEditorStatus("Only admin can set AI notices.", "error");
          return;
        }
        const rect = getPdfAiNoticeRect();
        const text = preservePdfAiNoticeText(pdfEls && pdfEls.aiNoticeInput ? pdfEls.aiNoticeInput.value : "");
        if (!rect || !text) {
          setPdfAiNoticeEditorStatus("Select a region and enter notice text.", "error");
          return;
        }
        const scope = currentPdfAiRegionNoticeScope();
        const existing = currentPdfAiNoticeForSelection();
        try {
          console.log("FT_SAVE", JSON.stringify({ selectionsLen: (Array.isArray(pdfState.selections) ? pdfState.selections.length : 0), rect, unionRectsLen: (rect.unionRects || []).length, existingId: (existing && existing.id) || "", existingUnionRectsLen: (existing && existing.unionRects || []).length }));
        } catch (_e) {
        }
        const displayMode = pdfEls && pdfEls.aiNoticeDisplayMode && clean(pdfEls.aiNoticeDisplayMode.value).toLowerCase() === "full"
          ? "full"
          : "type";
        const noticeStyle = pdfEls && pdfEls.aiNoticeStyle && clean(pdfEls.aiNoticeStyle.value).toLowerCase() === "image"
          ? "image"
          : "fireball";
        const imageSrc = noticeStyle === "image" && pdfEls && pdfEls.aiNoticeImageSrc
          ? normalizePdfAiQuestionImageSrc(pdfEls.aiNoticeImageSrc.value || "")
          : "";
        const noticeTheme = pdfEls && pdfEls.aiNoticeTheme && clean(pdfEls.aiNoticeTheme.value).toLowerCase() === "cyan" ? "cyan" : "red";
        const focusText = preservePdfAiNoticeText(pdfEls && pdfEls.aiNoticeFocusText ? pdfEls.aiNoticeFocusText.value : (existing && (existing.focusText || existing.focus_text || "")), 520);
        const noticeTextHighlights = normalizePdfAiTextHighlights(pdfEls && pdfEls.aiNoticeInput ? pdfEls.aiNoticeInput._pdfAiTextHighlights || [] : [], text);
        const focusTextHighlights = normalizePdfAiTextHighlights(pdfEls && pdfEls.aiNoticeFocusText ? pdfEls.aiNoticeFocusText._pdfAiTextHighlights || [] : [], focusText);
        const noticeTextFont = normalizePdfAiNoticeFont(pdfEls && pdfEls.aiNoticeTextFont ? pdfEls.aiNoticeTextFont.value : (existing && (existing.noticeTextFont || existing.notice_text_font || existing.textFont || existing.text_font)));
        const focusTextFont = normalizePdfAiNoticeFont(pdfEls && pdfEls.aiNoticeFocusFont ? pdfEls.aiNoticeFocusFont.value : (existing && (existing.focusTextFont || existing.focus_text_font || existing.focusFont || existing.focus_font)));
        const voice = pdfEls && pdfEls.aiNoticeVoice
          ? clean(pdfEls.aiNoticeVoice.value || PDF_SHARED_AUDIO_DEFAULT_VOICE) || PDF_SHARED_AUDIO_DEFAULT_VOICE
          : clean(existing && existing.voice || PDF_SHARED_AUDIO_DEFAULT_VOICE) || PDF_SHARED_AUDIO_DEFAULT_VOICE;
        const speakMode = pdfEls && pdfEls.aiNoticeSpeakMode
          ? clean(pdfEls.aiNoticeSpeakMode.value || "once").toLowerCase()
          : clean(existing && (existing.speakMode || existing.speak_mode) || "once").toLowerCase();
        const audioText = preservePdfAiNoticeText(pdfEls && pdfEls.aiNoticeAudioText ? pdfEls.aiNoticeAudioText.value : (existing && (existing.audioText || existing.audio_text) || text), 2400);
        setPdfAiNoticeEditorStatus("Saving notice...", "");
        try {
          const { payload } = await fetchAuthJson("/space-pdf/ai-region-notices?client_source=pdf_ai_notice_mutation", {
            method: "POST",
            timeoutMs: audioText ? 150000 : 15000,
            body: JSON.stringify({ ...scope, id: existing ? existing.id : "", rect: { x: rect.x, y: rect.y, w: rect.w, h: rect.h }, unionRects: rect.unionRects && rect.unionRects.length ? rect.unionRects : (existing && existing.unionRects && existing.unionRects.length ? existing.unionRects : []), text, focusText, noticeTextHighlights, focusTextHighlights, noticeTextFont, focusTextFont, displayMode, noticeStyle, noticeTheme, imageSrc, voice, speakMode, audioText }),
          });
          applyPdfAiRegionNoticePayload(payload || {});
          const saved = payload && payload.notice ? normalizePdfAiRegionNotice(payload.notice) : null;
          if (saved && saved.audioPath && (!existing || !existing.audioPath || existing.audioPath !== saved.audioPath)) {
            playPdfAiNoticeVoice(saved, { force: true, preview: true });
          }
          closePdfAiNoticeEditor();
          setPdfStatus("AI notice set for this Ghost Eye region.");
        } catch (error) {
          setPdfAiNoticeEditorStatus(error && error.message ? error.message : "Could not save notice.", "error");
        }
      };

      const setPdfAiRegionNoticeVoice = async () => {
        if (!currentAuthIsAdmin) {
          setPdfAiNoticeEditorStatus("Only admin can set AI notice voice.", "error");
          return;
        }
        const rect = getPdfAiNoticeRect();
        const text = preservePdfAiNoticeText(pdfEls && pdfEls.aiNoticeInput ? pdfEls.aiNoticeInput.value : "");
        const audioText = preservePdfAiNoticeText(pdfEls && pdfEls.aiNoticeAudioText ? pdfEls.aiNoticeAudioText.value : text, 2400);
        if (!rect || !text || !audioText) {
          setPdfAiNoticeEditorStatus("Select a region, notice text, and voice text first.", "error");
          return;
        }
        const scope = currentPdfAiRegionNoticeScope();
        const existing = currentPdfAiNoticeForSelection();
        const displayMode = pdfEls && pdfEls.aiNoticeDisplayMode && clean(pdfEls.aiNoticeDisplayMode.value).toLowerCase() === "full" ? "full" : "type";
        const voice = pdfEls && pdfEls.aiNoticeVoice ? clean(pdfEls.aiNoticeVoice.value || PDF_SHARED_AUDIO_DEFAULT_VOICE) || PDF_SHARED_AUDIO_DEFAULT_VOICE : PDF_SHARED_AUDIO_DEFAULT_VOICE;
        const speakMode = pdfEls && pdfEls.aiNoticeSpeakMode ? clean(pdfEls.aiNoticeSpeakMode.value || "once").toLowerCase() : "once";
        const focusText = preservePdfAiNoticeText(pdfEls && pdfEls.aiNoticeFocusText ? pdfEls.aiNoticeFocusText.value : (existing && (existing.focusText || existing.focus_text || "")), 520);
        const noticeTextHighlights = normalizePdfAiTextHighlights(pdfEls && pdfEls.aiNoticeInput ? pdfEls.aiNoticeInput._pdfAiTextHighlights || [] : [], text);
        const focusTextHighlights = normalizePdfAiTextHighlights(pdfEls && pdfEls.aiNoticeFocusText ? pdfEls.aiNoticeFocusText._pdfAiTextHighlights || [] : [], focusText);
        const noticeTextFont = normalizePdfAiNoticeFont(pdfEls && pdfEls.aiNoticeTextFont ? pdfEls.aiNoticeTextFont.value : (existing && (existing.noticeTextFont || existing.notice_text_font || existing.textFont || existing.text_font)));
        const focusTextFont = normalizePdfAiNoticeFont(pdfEls && pdfEls.aiNoticeFocusFont ? pdfEls.aiNoticeFocusFont.value : (existing && (existing.focusTextFont || existing.focus_text_font || existing.focusFont || existing.focus_font)));
        setPdfAiNoticeEditorStatus("Building AI notice voice...", "");
        try {
          const { payload } = await fetchAuthJson("/space-pdf/ai-region-notices?client_source=pdf_ai_notice_mutation", {
            method: "POST",
            timeoutMs: 150000,
            body: JSON.stringify({ ...scope, id: existing ? existing.id : "", rect: { x: rect.x, y: rect.y, w: rect.w, h: rect.h }, unionRects: rect.unionRects && rect.unionRects.length ? rect.unionRects : (existing && existing.unionRects && existing.unionRects.length ? existing.unionRects : []), text, focusText, noticeTextHighlights, focusTextHighlights, noticeTextFont, focusTextFont, displayMode, voice, speakMode, audioText, action: "build_audio" }),
          });
          applyPdfAiRegionNoticePayload(payload || {});
          const saved = payload && payload.notice ? payload.notice : null;
          if (saved && pdfEls.aiNoticeAudioText) {
            pdfEls.aiNoticeAudioText.value = preservePdfAiNoticeText(saved.audio_text || saved.audioText || audioText, 2400);
          }
          const savedAudioPath = clean(saved && (saved.audio_path || saved.audioPath || ""));
          if (savedAudioPath) {
            playPdfAiNoticeVoice(normalizePdfAiRegionNotice(saved) || saved, { force: true, preview: true });
          }
          setPdfAiNoticeEditorStatus(savedAudioPath ? "Voice ready. Playing preview now." : "Voice saved, but no audio path came back.", savedAudioPath ? "ok" : "error");
          setPdfStatus("AI notice voice built and saved.");
        } catch (error) {
          setPdfAiNoticeEditorStatus(error && error.message ? error.message : "Could not build AI notice voice.", "error");
        }
      };

      const deletePdfAiRegionNotice = async () => {
        if (!currentAuthIsAdmin) {
          setPdfAiNoticeEditorStatus("Only admin can delete AI notices.", "error");
          return;
        }
        const rect = getPdfAiNoticeRect();
        if (!rect) {
          setPdfAiNoticeEditorStatus("Select a region first.", "error");
          return;
        }
        const scope = currentPdfAiRegionNoticeScope();
        const existing = currentPdfAiNoticeForSelection();
        if (!existing || !existing.id) {
          setPdfAiNoticeEditorStatus("This region has no saved notice yet.", "error");
          return;
        }
        setPdfAiNoticeEditorStatus("Deleting notice...", "");
        try {
          const { payload } = await fetchAuthJson("/space-pdf/ai-region-notices?client_source=pdf_ai_notice_mutation", {
            method: "POST",
            body: JSON.stringify({ ...scope, id: existing.id, rect, action: "delete" }),
          });
          applyPdfAiRegionNoticePayload(payload || {});
          closePdfAiNoticeEditor();
          setPdfStatus("AI notice removed for this region.");
        } catch (error) {
          setPdfAiNoticeEditorStatus(error && error.message ? error.message : "Could not delete notice.", "error");
        }
      };

      const selectPdfAiQuestionRegion = (question = null, options = {}) => {
        if (!question || !question.rect) {
          return;
        }
        const rect = normalizePdfSelectionState(question.rect);
        if (!rect) {
          return;
        }
        const unionRects = Array.isArray(question.unionRects) && question.unionRects.length
          ? question.unionRects.map((u) => normalizePdfSelectionState(u)).filter(Boolean)
          : [];
        pdfState.selections = unionRects.length ? unionRects : [rect];
        pdfState.selection = pdfState.selections[pdfState.selections.length - 1];
        setPdfShiftSelectionActive(false);
        clearPdfPointSelection();
        syncPdfSelectionOverlay(true);
        updatePdfChrome();
        renderPdfAiRegionNoticeHitboxes();
        if (options.hitbox) {
          showPdfAiQuestionPanel(question, options.hitbox);
        }
        if (options.openEditor) {
          void openPdfAiQuestionEditor();
        }
      };

      const setPdfAiQuestionEditorStatus = (message = "", tone = "") => {
        if (!pdfEls || !pdfEls.aiQuestionStatus) {
          return;
        }
        pdfEls.aiQuestionStatus.textContent = message;
        pdfEls.aiQuestionStatus.dataset.tone = tone;
      };

      // Added 2026-07-02: shows admins which missing MishiKa voice files are being built during save.
      const collectPdfAiQuestionMissingAudioJobs = (nodes = []) => {
        const sequence = Array.isArray(nodes) ? nodes : [];
        const jobs = [];
        sequence.forEach((node, nodeIndex) => {
          const nodeTitle = clean(node && (node.title || node.question) || `Node ${nodeIndex + 1}`).slice(0, 54) || `Node ${nodeIndex + 1}`;
          if (preserveQuestionText(node && node.mikasaIntro || "") && !clean(node && (node.introAudioPath || node.intro_audio_path) || "")) {
            jobs.push({
              nodeIndex,
              label: `Q${nodeIndex + 1} intro | ${nodeTitle}`,
            });
          }
          (Array.isArray(node && node.answers) ? node.answers : []).forEach((answer, answerIndex) => {
            const mode = clean(answer && (answer.explanationMode || answer.explanation_mode) || "text_voice").toLowerCase();
            const explanation = preserveQuestionText(answer && (answer.explanationText || answer.explanation_text) || "");
            if (mode !== "text" && explanation && !clean(answer && (answer.audioPath || answer.audio_path) || "")) {
              const answerText = clean(answer && answer.text || `Answer ${answerIndex + 1}`).slice(0, 46) || `Answer ${answerIndex + 1}`;
              jobs.push({
                nodeIndex,
                label: `Q${nodeIndex + 1} answer ${answerIndex + 1} | ${answerText}`,
              });
            }
          });
        });
        return jobs;
      };

      // Added 2026-07-02: renders per-node missing-audio progress in the MishiKa editor footer.
      const setPdfAiQuestionAudioBuildStatus = (jobs = [], activeNodeIndex = -1, savedNodes = 0, totalNodes = 0) => {
        if (!jobs.length) {
          setPdfAiQuestionEditorStatus(`Saving ${totalNodes} AI question node${totalNodes > 1 ? "s" : ""}. No missing audio to build.`, "");
          return;
        }
        const activeJobs = jobs.filter((job) => job.nodeIndex === activeNodeIndex);
        const doneCount = jobs.filter((job) => job.nodeIndex < activeNodeIndex).length;
        const preview = (activeJobs.length ? activeJobs : jobs.slice(doneCount, doneCount + 3))
          .slice(0, 4)
          .map((job) => `- ${job.label}`)
          .join("\n");
        const nodeProgress = totalNodes ? `Node ${Math.min(savedNodes + 1, totalNodes)}/${totalNodes}` : "Node";
        const audioProgress = `${Math.min(doneCount + activeJobs.length, jobs.length)}/${jobs.length}`;
        setPdfAiQuestionEditorStatus(`${nodeProgress} | building missing audio ${audioProgress}\n${preview}`, "");
      };

      const PDF_AI_QUESTION_AUTOSIZE_SELECTOR = "#ft-pdf-ai-question-input, #ft-pdf-ai-question-intro, .ft-pdf-ai-question-answer-text, .ft-pdf-ai-question-explain-text";

      const resizePdfAiQuestionTextarea = (textarea) => {
        if (!textarea || !textarea.matches || !textarea.matches(PDF_AI_QUESTION_AUTOSIZE_SELECTOR)) {
          return;
        }
        textarea.style.height = "auto";
        const nextHeight = Math.max(textarea.scrollHeight, 40);
        textarea.style.height = `${nextHeight}px`;
        textarea.style.overflowY = "hidden";
      };

      const resizePdfAiQuestionTextareas = (scope = null) => {
        const root = scope || (pdfEls && pdfEls.aiQuestionModal) || document;
        if (!root || !root.querySelectorAll) {
          return;
        }
        root.querySelectorAll(PDF_AI_QUESTION_AUTOSIZE_SELECTOR).forEach(resizePdfAiQuestionTextarea);
      };

      const hidePdfAiQuestionHighlightPalette = () => {
        ["ft-pdf-ai-question-highlight-palette", "ft-pdf-ai-notice-highlight-palette"].forEach((id) => {
          const palette = document.getElementById(id);
          if (palette) {
            palette.remove();
          }
        });
      };

      const ensurePdfAiQuestionTextHighlightField = (textarea = null) => {
        if (!textarea || !textarea.parentNode) {
          return null;
        }
        let field = textarea._pdfAiTextHighlightField || null;
        if (!field || !field.isConnected) {
          field = document.createElement("span");
          field.className = "ft-pdf-ai-question-highlight-field";
          textarea.parentNode.insertBefore(field, textarea);
          field.appendChild(textarea);
          textarea._pdfAiTextHighlightField = field;
        }
        field.classList.toggle("is-intro", textarea.matches && textarea.matches(".ft-pdf-ai-question-intro-text"));
        field.classList.toggle("is-question", textarea.id === "ft-pdf-ai-question-input");
        field.classList.toggle("is-notice", Boolean(textarea && textarea.id === "ft-pdf-ai-notice-input"));
        field.classList.toggle("is-notice-focus", Boolean(textarea && textarea.id === "ft-pdf-ai-notice-focus-text"));
        let overlay = textarea._pdfAiTextHighlightOverlay || null;
        if (!overlay || !overlay.isConnected) {
          overlay = document.createElement("span");
          overlay.className = "ft-pdf-ai-question-highlight-overlay";
          overlay.setAttribute("aria-hidden", "true");
          field.insertBefore(overlay, textarea);
          textarea._pdfAiTextHighlightOverlay = overlay;
        }
        return field;
      };

      const renderPdfAiQuestionTextHighlightPreview = (textarea = null) => {
        if (!textarea || !textarea.parentNode) {
          return;
        }
        const field = ensurePdfAiQuestionTextHighlightField(textarea);
        if (!field) {
          return;
        }
        const stalePreview = textarea._pdfAiTextHighlightPreview || null;
        if (stalePreview && stalePreview.isConnected) {
          stalePreview.remove();
        }
        const value = preserveQuestionText(textarea.value || "");
        const highlights = normalizePdfAiTextHighlights(textarea._pdfAiTextHighlights || [], value);
        textarea._pdfAiTextHighlights = highlights;
        const overlay = textarea._pdfAiTextHighlightOverlay || null;
        field.classList.toggle("has-highlight", Boolean(value && highlights.length));
        if (overlay) {
          overlay.innerHTML = value && highlights.length
          ? renderPdfAiQuestionHighlightedText(value, highlights, Array.from(value).length)
          : "";
          overlay.style.transform = `translate(${-textarea.scrollLeft || 0}px, ${-textarea.scrollTop || 0}px)`;
        }
      };

      const showPdfAiQuestionHighlightPalette = (textarea, event) => {
        if (!textarea || typeof textarea.selectionStart !== "number" || typeof textarea.selectionEnd !== "number") {
          return false;
        }
        const start = Math.min(textarea.selectionStart, textarea.selectionEnd);
        const end = Math.max(textarea.selectionStart, textarea.selectionEnd);
        if (end <= start) {
          return false;
        }
        hidePdfAiQuestionHighlightPalette();
        const palette = document.createElement("div");
        palette.id = "ft-pdf-ai-question-highlight-palette";
        palette.className = "ft-pdf-ai-question-highlight-palette";
        const savedColors = readPdfAiQuestionSavedHighlightColors();
        const activeColor = savedColors[0] || "#ffe78a";
        palette.innerHTML = `
          <strong>Text color</strong>
          <div class="ft-pdf-ai-question-highlight-swatches">
            ${PDF_AI_QUESTION_HIGHLIGHT_COLORS.map((item) => `<button type="button" data-color="${escapeHtml(item.color)}" style="--swatch:${escapeHtml(item.color)}" aria-label="${escapeHtml(item.id)}"></button>`).join("")}
          </div>
          <div class="ft-pdf-ai-question-highlight-custom">
            <input type="color" value="${escapeHtml(activeColor)}" aria-label="Custom text color">
            <button type="button" data-highlight-apply>Apply</button>
            <button type="button" data-highlight-save>Save</button>
          </div>
          <div class="ft-pdf-ai-question-highlight-saved">
            ${savedColors.map((color) => `<button type="button" data-color="${escapeHtml(color)}" style="--swatch:${escapeHtml(color)}" aria-label="${escapeHtml(color)}"></button>`).join("")}
          </div>
        `;
        const rect = textarea.getBoundingClientRect();
        const left = Math.min(Math.max(12, Number(event && event.clientX || rect.left + 24)), Math.max(12, window.innerWidth - 284));
        const top = Math.min(Math.max(12, Number(event && event.clientY || rect.top + 24)), Math.max(12, window.innerHeight - 190));
        palette.style.left = `${left}px`;
        palette.style.top = `${top}px`;
        palette.addEventListener("pointerdown", (paletteEvent) => {
          paletteEvent.stopPropagation();
        });
        const applyColor = (rawColor = "", options = {}) => {
          const color = normalizePdfAiQuestionHighlightColor(rawColor, "");
          if (!color) {
            return;
          }
          const existing = normalizePdfAiTextHighlights(textarea._pdfAiTextHighlights || [], textarea.value || "");
          textarea._pdfAiTextHighlights = normalizePdfAiTextHighlights([
            ...existing,
            { start, end, color },
          ], textarea.value || "");
          renderPdfAiQuestionTextHighlightPreview(textarea);
          mergePdfAiQuestionEditorDraft();
          if (options.save) {
            savePdfAiQuestionSavedHighlightColor(color);
          }
          hidePdfAiQuestionHighlightPalette();
          textarea.focus();
          try {
            textarea.setSelectionRange(start, end);
          } catch (error) {}
          setPdfAiQuestionEditorStatus(options.save ? "Text color saved and applied." : "Text color applied to the selected range.", "ok");
        };
        palette.addEventListener("click", (paletteEvent) => {
          const button = paletteEvent.target && paletteEvent.target.closest ? paletteEvent.target.closest("[data-color], [data-highlight-apply], [data-highlight-save]") : null;
          if (!button) {
            return;
          }
          paletteEvent.preventDefault();
          paletteEvent.stopPropagation();
          const picker = palette.querySelector('input[type="color"]');
          if (button.hasAttribute("data-highlight-apply")) {
            applyColor(picker ? picker.value : activeColor);
            return;
          }
          if (button.hasAttribute("data-highlight-save")) {
            applyColor(picker ? picker.value : activeColor, { save: true });
            return;
          }
          applyColor(button.dataset.color || activeColor);
        });
        document.body.appendChild(palette);
        window.setTimeout(() => {
          const close = (closeEvent) => {
            if (closeEvent && closeEvent.target && palette.contains(closeEvent.target)) {
              return;
            }
            hidePdfAiQuestionHighlightPalette();
            document.removeEventListener("pointerdown", close, true);
          };
          document.addEventListener("pointerdown", close, true);
        }, 0);
        return true;
      };

      const bindPdfAiQuestionHighlightTextarea = (textarea) => {
        if (!textarea || textarea._pdfAiHighlightBound) {
          return;
        }
        textarea._pdfAiHighlightBound = true;
        textarea.addEventListener("contextmenu", (event) => {
          if (showPdfAiQuestionHighlightPalette(textarea, event)) {
            event.preventDefault();
            event.stopPropagation();
          }
        });
        textarea.addEventListener("click", (event) => {
          if (!event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) {
            return;
          }
          if (showPdfAiQuestionHighlightPalette(textarea, event)) {
            event.preventDefault();
            event.stopPropagation();
          }
        });
        textarea.addEventListener("input", () => {
          textarea._pdfAiTextHighlights = normalizePdfAiTextHighlights(textarea._pdfAiTextHighlights || [], textarea.value || "");
          renderPdfAiQuestionTextHighlightPreview(textarea);
        });
        textarea.addEventListener("scroll", () => {
          renderPdfAiQuestionTextHighlightPreview(textarea);
        });
        renderPdfAiQuestionTextHighlightPreview(textarea);
      };

      const renderPdfAiNoticeTextHighlightPreview = (textarea = null) => {
        if (!textarea || !textarea.parentNode) {
          return;
        }
        const field = ensurePdfAiQuestionTextHighlightField(textarea);
        if (!field) {
          return;
        }
        const value = preserveQuestionText(textarea.value || "");
        const highlights = normalizePdfAiTextHighlights(textarea._pdfAiTextHighlights || [], value);
        textarea._pdfAiTextHighlights = highlights;
        const overlay = textarea._pdfAiTextHighlightOverlay || null;
        field.classList.toggle("has-highlight", Boolean(value && highlights.length));
        if (overlay) {
          overlay.innerHTML = value && highlights.length
            ? renderPdfAiNoticeRichHtml(value, highlights)
            : "";
          overlay.style.transform = `translate(${-textarea.scrollLeft || 0}px, ${-textarea.scrollTop || 0}px)`;
        }
      };

      const showPdfAiNoticeHighlightPalette = (textarea, event, options = {}) => {
        if (!textarea || typeof textarea.selectionStart !== "number" || typeof textarea.selectionEnd !== "number") {
          return false;
        }
        const start = Math.min(textarea.selectionStart, textarea.selectionEnd);
        const end = Math.max(textarea.selectionStart, textarea.selectionEnd);
        if (end <= start) {
          return false;
        }
        hidePdfAiQuestionHighlightPalette();
        const palette = document.createElement("div");
        palette.id = "ft-pdf-ai-notice-highlight-palette";
        palette.className = "ft-pdf-ai-question-highlight-palette";
        const savedColors = readPdfAiQuestionSavedHighlightColors();
        const activeColor = savedColors[0] || "#ffe78a";
        palette.innerHTML = `
          <strong>${escapeHtml(options.title || "Text color")}</strong>
          <div class="ft-pdf-ai-notice-format-row" role="group" aria-label="Selected text format">
            <button type="button" data-format-bold title="Bold selected text">B</button>
            <button type="button" data-format-italic title="Italic selected text"><em>I</em></button>
            <select data-format-font aria-label="Selected text font">
              <option value="">Font</option>
              ${PDF_AI_NOTICE_FONT_OPTIONS.map((font) => `<option value="${escapeHtml(font)}">${escapeHtml(font)}</option>`).join("")}
            </select>
            <button type="button" data-format-reset title="Reset selected text to original style">Reset</button>
          </div>
          <div class="ft-pdf-ai-question-highlight-swatches">
            ${PDF_AI_QUESTION_HIGHLIGHT_COLORS.map((item) => `<button type="button" data-color="${escapeHtml(item.color)}" style="--swatch:${escapeHtml(item.color)}" aria-label="${escapeHtml(item.id)}"></button>`).join("")}
          </div>
          <div class="ft-pdf-ai-question-highlight-custom">
            <input type="color" value="${escapeHtml(activeColor)}" aria-label="Custom text color">
            <button type="button" data-highlight-apply>Apply</button>
            <button type="button" data-highlight-save>Save</button>
          </div>
          <div class="ft-pdf-ai-question-highlight-saved">
            ${savedColors.map((color) => `<button type="button" data-color="${escapeHtml(color)}" style="--swatch:${escapeHtml(color)}" aria-label="${escapeHtml(color)}"></button>`).join("")}
          </div>
        `;
        const rect = textarea.getBoundingClientRect();
        const left = Math.min(Math.max(12, Number(event && event.clientX || rect.left + 24)), Math.max(12, window.innerWidth - 284));
        const top = Math.min(Math.max(12, Number(event && event.clientY || rect.top + 24)), Math.max(12, window.innerHeight - 190));
        palette.style.left = `${left}px`;
        palette.style.top = `${top}px`;
        palette.addEventListener("pointerdown", (paletteEvent) => {
          paletteEvent.stopPropagation();
        });
        const resetSelectedFormat = () => {
          const existing = normalizePdfAiTextHighlights(textarea._pdfAiTextHighlights || [], textarea.value || "");
          const next = [];
          existing.forEach((range) => {
            if (!range || range.end <= start || range.start >= end) {
              next.push(range);
              return;
            }
            if (range.start < start) {
              next.push({ ...range, end: start });
            }
            if (range.end > end) {
              next.push({ ...range, start: end });
            }
          });
          textarea._pdfAiTextHighlights = normalizePdfAiTextHighlights(next, textarea.value || "");
          renderPdfAiNoticeTextHighlightPreview(textarea);
          if (typeof options.onChange === "function") {
            options.onChange(textarea._pdfAiTextHighlights || []);
          }
          hidePdfAiQuestionHighlightPalette();
          textarea.focus();
          try {
            textarea.setSelectionRange(start, end);
          } catch (error) {}
          if (typeof options.setStatus === "function") {
            options.setStatus("Selected text returned to original style.", "ok");
          }
        };
        const applyFormat = (format = {}, paletteOptions = {}) => {
          const nextFormat = { ...format };
          if (nextFormat.color !== undefined) {
            nextFormat.color = normalizePdfAiQuestionHighlightColor(nextFormat.color, "");
          }
          if (nextFormat.font !== undefined) {
            nextFormat.font = normalizePdfAiNoticeFont(nextFormat.font, "");
          }
          if (!nextFormat.color && !nextFormat.bold && !nextFormat.italic && !nextFormat.font) {
            return;
          }
          const existing = normalizePdfAiTextHighlights(textarea._pdfAiTextHighlights || [], textarea.value || "");
          textarea._pdfAiTextHighlights = normalizePdfAiTextHighlights([
            ...existing,
            { start, end, ...nextFormat },
          ], textarea.value || "");
          renderPdfAiNoticeTextHighlightPreview(textarea);
          if (typeof options.onChange === "function") {
            options.onChange(textarea._pdfAiTextHighlights || []);
          }
          if (paletteOptions.save) {
            savePdfAiQuestionSavedHighlightColor(nextFormat.color);
          }
          hidePdfAiQuestionHighlightPalette();
          textarea.focus();
          try {
            textarea.setSelectionRange(start, end);
          } catch (error) {}
          const status = paletteOptions.message || (paletteOptions.save ? "Text color saved and applied." : "Format applied to the selected range.");
          if (typeof options.setStatus === "function") {
            options.setStatus(status, "ok");
          }
        };
        palette.addEventListener("click", (paletteEvent) => {
          const button = paletteEvent.target && paletteEvent.target.closest ? paletteEvent.target.closest("[data-color], [data-highlight-apply], [data-highlight-save], [data-format-bold], [data-format-italic], [data-format-reset]") : null;
          if (!button) {
            return;
          }
          paletteEvent.preventDefault();
          paletteEvent.stopPropagation();
          const picker = palette.querySelector('input[type="color"]');
          if (button.hasAttribute("data-format-reset")) {
            resetSelectedFormat();
            return;
          }
          if (button.hasAttribute("data-highlight-apply")) {
            applyFormat({ color: picker ? picker.value : activeColor }, { message: "Text color applied to the selected range." });
            return;
          }
          if (button.hasAttribute("data-highlight-save")) {
            applyFormat({ color: picker ? picker.value : activeColor }, { save: true });
            return;
          }
          if (button.hasAttribute("data-format-bold")) {
            applyFormat({ bold: true }, { message: "Bold applied to the selected range." });
            return;
          }
          if (button.hasAttribute("data-format-italic")) {
            applyFormat({ italic: true }, { message: "Italic applied to the selected range." });
            return;
          }
          applyFormat({ color: button.dataset.color || activeColor }, { message: "Text color applied to the selected range." });
        });
        const fontSelect = palette.querySelector("[data-format-font]");
        if (fontSelect) {
          fontSelect.addEventListener("change", () => {
            applyFormat({ font: fontSelect.value || "" }, { message: "Font applied to the selected range." });
          });
        }
        document.body.appendChild(palette);
        window.setTimeout(() => {
          const close = (closeEvent) => {
            if (closeEvent && closeEvent.target && palette.contains(closeEvent.target)) {
              return;
            }
            hidePdfAiQuestionHighlightPalette();
            document.removeEventListener("pointerdown", close, true);
          };
          document.addEventListener("pointerdown", close, true);
        }, 0);
        return true;
      };

      const bindPdfAiNoticeHighlightTextarea = (textarea, options = {}) => {
        if (!textarea || textarea._pdfAiHighlightBound) {
          return;
        }
        textarea._pdfAiHighlightBound = true;
        textarea.addEventListener("contextmenu", (event) => {
          if (showPdfAiNoticeHighlightPalette(textarea, event, options)) {
            event.preventDefault();
            event.stopPropagation();
          }
        });
        textarea.addEventListener("click", (event) => {
          if (!event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) {
            return;
          }
          if (showPdfAiNoticeHighlightPalette(textarea, event, options)) {
            event.preventDefault();
            event.stopPropagation();
          }
        });
        textarea.addEventListener("input", () => {
          textarea._pdfAiTextHighlights = normalizePdfAiTextHighlights(textarea._pdfAiTextHighlights || [], textarea.value || "");
          renderPdfAiNoticeTextHighlightPreview(textarea);
          if (typeof options.onChange === "function") {
            options.onChange(textarea._pdfAiTextHighlights || []);
          }
        });
        textarea.addEventListener("scroll", () => {
          renderPdfAiNoticeTextHighlightPreview(textarea);
        });
        renderPdfAiNoticeTextHighlightPreview(textarea);
      };

      // Added 2026-07-02: updates the Set AI Question image input and preview for URL/path or pasted clipboard images.
      const syncPdfAiQuestionImagePreview = () => {
        if (!pdfEls || !pdfEls.aiQuestionImageSrc || !pdfEls.aiQuestionImagePreview) {
          return;
        }
        const src = normalizePdfAiQuestionImageSrc(pdfEls.aiQuestionImageSrc.value || "");
        const preview = pdfEls.aiQuestionImagePreview;
        const img = preview.querySelector("img");
        if (!src || !img) {
          preview.hidden = true;
          if (img) {
            img.removeAttribute("src");
          }
          return;
        }
        preview.hidden = false;
        img.onerror = () => {
          preview.classList.add("is-broken");
        };
        img.onload = () => {
          preview.classList.remove("is-broken");
        };
        if (img.getAttribute("src") !== src) {
          img.setAttribute("src", src);
        }
      };

      const setPdfAiQuestionEditorImage = (src = "", options = {}) => {
        if (!pdfEls || !pdfEls.aiQuestionImageSrc) {
          return;
        }
        pdfEls.aiQuestionImageSrc.value = normalizePdfAiQuestionImageSrc(src);
        syncPdfAiQuestionImagePreview();
        if (options.status !== false) {
          setPdfAiQuestionEditorStatus(src ? "Question image updated. Save to apply it to this node." : "Question image cleared.", "");
        }
      };

      const pdfAiNoticeImageRuntimeSrc = (value = "") => {
        const src = normalizePdfAiQuestionImageSrc(value);
        if (!src) return "";
        if (/^(data:image\/|https?:\/\/|\/)/i.test(src)) return src;
        const normalized = src.replace(/^\.?\/*/, "");
        const folderMatch = normalized.match(/(?:^|\/)Ai_notice_image\/(.+)$/i);
        if (folderMatch && folderMatch[1]) {
          return `/space-pdf/ai-notice-image?path=${encodeURIComponent(folderMatch[1])}`;
        }
        if (/^Ai_notice_image\//i.test(normalized)) {
          return `/space-pdf/ai-notice-image?path=${encodeURIComponent(normalized.replace(/^Ai_notice_image\//i, ""))}`;
        }
        return src;
      };

      const syncPdfAiNoticeImagePreview = () => {
        if (!pdfEls || !pdfEls.aiNoticeImageSrc || !pdfEls.aiNoticeImagePreview) {
          return;
        }
        const src = pdfAiNoticeImageRuntimeSrc(pdfEls.aiNoticeImageSrc.value || "");
        const preview = pdfEls.aiNoticeImagePreview;
        const img = preview.querySelector("img");
        if (!src || !img) {
          preview.hidden = true;
          if (img) img.removeAttribute("src");
          return;
        }
        preview.hidden = false;
        img.onerror = () => preview.classList.add("is-broken");
        img.onload = () => preview.classList.remove("is-broken");
        if (img.getAttribute("src") !== src) {
          img.setAttribute("src", src);
        }
      };

      const setPdfAiNoticeEditorImage = (src = "", options = {}) => {
        if (!pdfEls || !pdfEls.aiNoticeImageSrc) {
          return;
        }
        pdfEls.aiNoticeImageSrc.value = normalizePdfAiQuestionImageSrc(src);
        syncPdfAiNoticeImagePreview();
        if (options.status !== false) {
          setPdfAiNoticeEditorStatus(src ? "Notice character image updated. Save to keep it." : "Notice character image cleared.", "");
        }
      };

      let pdfAiNoticeImageListLoaded = false;
      const loadPdfAiNoticeImageList = async (options = {}) => {
        if (!pdfEls || !pdfEls.aiNoticeImageList) {
          return [];
        }
        if (pdfAiNoticeImageListLoaded && !options.force) {
          return [];
        }
        try {
          const { payload } = await fetchAuthJson("/space-pdf/ai-notice-image-list", { timeoutMs: 12000 });
          const rows = Array.isArray(payload && payload.images) ? payload.images : [];
          pdfEls.aiNoticeImageList.innerHTML = `<option value="">Folder images</option>`;
          rows.forEach((item) => {
            const name = clean(item && item.name || item && item.path || "");
            const path = clean(item && item.path || name);
            if (!name || !path) return;
            const option = document.createElement("option");
            option.value = `Ai_notice_image/${path}`;
            option.textContent = name;
            pdfEls.aiNoticeImageList.appendChild(option);
          });
          const current = normalizePdfAiQuestionImageSrc(pdfEls.aiNoticeImageSrc ? pdfEls.aiNoticeImageSrc.value : "");
          if (current) {
            const found = Array.from(pdfEls.aiNoticeImageList.options || []).find((option) => normalizePdfAiQuestionImageSrc(option.value).toLowerCase() === current.toLowerCase());
            pdfEls.aiNoticeImageList.value = found ? found.value : "";
          }
          pdfAiNoticeImageListLoaded = true;
          if (options.status !== false) {
            setPdfAiNoticeEditorStatus(rows.length ? `Loaded ${rows.length} notice images.` : "No images found in Ai_notice_image.", rows.length ? "ok" : "");
          }
          return rows;
        } catch (error) {
          if (options.status !== false) {
            setPdfAiNoticeEditorStatus(error && error.message ? error.message : "Could not load notice image list.", "error");
          }
          return [];
        }
      };

      const pastePdfAiQuestionImageFromClipboard = async () => {
        if (!navigator.clipboard || typeof navigator.clipboard.read !== "function") {
          setPdfAiQuestionEditorStatus("Clipboard image paste is not available in this browser. Paste into the image path field instead.", "error");
          return;
        }
        try {
          const items = await navigator.clipboard.read();
          for (const item of items) {
            const type = (item.types || []).find((candidate) => String(candidate || "").toLowerCase().startsWith("image/"));
            if (!type) {
              continue;
            }
            const blob = await item.getType(type);
            const dataUrl = await compressPdfAiQuestionImageBlob(blob);
            setPdfAiQuestionEditorImage(dataUrl, { status: false });
            setPdfAiQuestionEditorStatus("Clipboard image pasted into this question node. Save to keep it.", "");
            return;
          }
          setPdfAiQuestionEditorStatus("Clipboard has no image. Paste a URL or local path into the image field.", "error");
        } catch (error) {
          setPdfAiQuestionEditorStatus(error && error.message ? error.message : "Could not paste clipboard image.", "error");
        }
      };

      const pdfAiQuestionEditorDraftFromForm = () => ({
        id: clean(pdfAiQuestionEditingId || ""),
        regionName: clean(pdfEls && pdfEls.aiQuestionRegionName ? pdfEls.aiQuestionRegionName.value : "").slice(0, 120),
        question: preserveQuestionText(pdfEls && pdfEls.aiQuestionInput ? pdfEls.aiQuestionInput.value : ""),
        imageSrc: normalizePdfAiQuestionImageSrc(pdfEls && pdfEls.aiQuestionImageSrc ? pdfEls.aiQuestionImageSrc.value : ""),
        imageAlt: "",
        questionHighlights: normalizePdfAiTextHighlights(pdfEls && pdfEls.aiQuestionInput ? pdfEls.aiQuestionInput._pdfAiTextHighlights || [] : [], pdfEls && pdfEls.aiQuestionInput ? pdfEls.aiQuestionInput.value : ""),
        questionType: normalizePdfAiQuestionType(pdfEls && pdfEls.aiQuestionType ? pdfEls.aiQuestionType.value : "choice"),
        typedMatchPercent: normalizePdfAiTypedMatchPercent(pdfEls && pdfEls.aiQuestionMatchPercent ? pdfEls.aiQuestionMatchPercent.value : 100),
        randomOrder: Boolean(pdfEls && pdfEls.aiQuestionRandomMode && pdfEls.aiQuestionRandomMode.value === "on"),
        pinned: Boolean(pdfEls && pdfEls.aiQuestionPinNode && pdfEls.aiQuestionPinNode.checked),
        mikasaIntro: preserveQuestionText(pdfEls && pdfEls.aiQuestionIntro ? pdfEls.aiQuestionIntro.value : ""),
        mikasaIntroHighlights: normalizePdfAiTextHighlights(pdfEls && pdfEls.aiQuestionIntro ? pdfEls.aiQuestionIntro._pdfAiTextHighlights || [] : [], pdfEls && pdfEls.aiQuestionIntro ? pdfEls.aiQuestionIntro.value : ""),
        voice: clean(pdfEls && pdfEls.aiQuestionIntroVoice ? pdfEls.aiQuestionIntroVoice.value : PDF_AI_QUESTION_DEFAULT_VOICE) || PDF_AI_QUESTION_DEFAULT_VOICE,
        answers: collectPdfAiQuestionAnswers({ allowEmpty: true }),
      });

      const mergePdfAiQuestionEditorDraft = () => {
        if (!pdfAiQuestionEditingId || !Array.isArray(pdfAiQuestionEditorNodes)) {
          return;
        }
        const index = pdfAiQuestionEditorNodes.findIndex((item) => clean(item && item.id || "") === clean(pdfAiQuestionEditingId));
        if (index < 0) {
          return;
        }
        pdfAiQuestionEditorNodes[index] = {
          ...pdfAiQuestionEditorNodes[index],
          ...pdfAiQuestionEditorDraftFromForm(),
        };
        const randomOrder = Boolean(pdfAiQuestionEditorNodes[index].randomOrder);
        const regionName = clean(pdfAiQuestionEditorNodes[index].regionName || "");
        pdfAiQuestionEditorNodes = pdfAiQuestionEditorNodes.map((item) => ({ ...item, randomOrder, regionName }));
      };

      // Added 2026-07-02: keeps the Set AI Question region name shared across every node in the current region.
      const syncPdfAiQuestionRegionNameToEditorNodes = (regionName = "") => {
        const safeName = clean(regionName).slice(0, 120);
        if (!Array.isArray(pdfAiQuestionEditorNodes)) {
          return safeName;
        }
        pdfAiQuestionEditorNodes = pdfAiQuestionEditorNodes.map((item) => ({ ...item, regionName: safeName }));
        return safeName;
      };

      const pdfAiQuestionBlankNode = () => ({
        id: `draft-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`,
        question: clean(pdfEls && pdfEls.exploreInput && pdfEls.exploreInput.value || pdfState.ocrText || ""),
        questionType: "choice",
        typedMatchPercent: 100,
        randomOrder: Boolean(pdfEls && pdfEls.aiQuestionRandomMode && pdfEls.aiQuestionRandomMode.value === "on"),
        regionName: clean(pdfEls && pdfEls.aiQuestionRegionName ? pdfEls.aiQuestionRegionName.value : "").slice(0, 120),
        pinned: false,
        mikasaIntro: "",
        imageSrc: "",
        imageAlt: "",
        questionHighlights: [],
        mikasaIntroHighlights: [],
        voice: PDF_AI_QUESTION_DEFAULT_VOICE,
        answers: [
          { text: "", correct: true, explanationMode: "text_voice", explanationVoice: PDF_AI_QUESTION_DEFAULT_VOICE },
          { text: "", correct: false, explanationMode: "text_voice", explanationVoice: PDF_AI_QUESTION_DEFAULT_VOICE },
        ],
      });

      // Added 2026-07-02: duplicates the current MishiKa editor node while keeping reusable media fields.
      const clonePdfAiQuestionEditorNode = (node = {}) => {
        const cloned = JSON.parse(JSON.stringify(node && typeof node === "object" ? node : pdfAiQuestionBlankNode()));
        cloned.id = `draft-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`;
        cloned.answers = (Array.isArray(cloned.answers) ? cloned.answers : []).map((answer, index) => ({
          ...answer,
          id: `answer-${index + 1}-${Math.random().toString(36).slice(2, 6)}`,
        }));
        return cloned;
      };

      const clearPdfAiQuestionNodeDropState = () => {
        if (!pdfEls || !pdfEls.aiQuestionNodeList) {
          return;
        }
        pdfEls.aiQuestionNodeList.querySelectorAll(".ft-pdf-ai-question-node.is-drop-target, .ft-pdf-ai-question-node.is-right-dragging, .ft-pdf-ai-question-node.is-dragging").forEach((item) => {
          item.classList.remove("is-drop-target");
          item.classList.remove("is-right-dragging");
          item.classList.remove("is-dragging");
        });
        pdfEls.aiQuestionNodeList.classList.remove("is-right-drag-active");
      };

      const syncPdfAiQuestionNodeNavigator = () => {
        if (!pdfEls || !pdfEls.aiQuestionNodeIndex) {
          return;
        }
        const nodes = Array.isArray(pdfAiQuestionEditorNodes) ? pdfAiQuestionEditorNodes : [];
        const activeIndex = nodes.findIndex((item) => clean(item && item.id || "") === clean(pdfAiQuestionEditingId));
        pdfEls.aiQuestionNodeIndex.value = activeIndex >= 0 ? String(activeIndex + 1) : (nodes.length ? "1" : "");
        pdfEls.aiQuestionNodeIndex.max = String(Math.max(1, nodes.length));
        pdfEls.aiQuestionNodeIndex.placeholder = nodes.length ? `1-${nodes.length}` : "0";
      };

      const scrollPdfAiQuestionEditorNodeIntoView = (nodeId = "") => {
        if (!pdfEls || !pdfEls.aiQuestionNodeList) {
          return;
        }
        const id = clean(nodeId);
        if (!id) {
          return;
        }
        const target = pdfEls.aiQuestionNodeList.querySelector(`.ft-pdf-ai-question-node[data-question-node-id="${CSS.escape(id)}"]`);
        if (target && typeof target.scrollIntoView === "function") {
          target.scrollIntoView({ block: "center", inline: "nearest", behavior: "smooth" });
        }
      };

      const flashPdfAiQuestionGotoNode = (nodeId = "") => {
        pdfAiQuestionGotoHighlightId = clean(nodeId);
        if (pdfAiQuestionGotoHighlightTimer) {
          window.clearTimeout(pdfAiQuestionGotoHighlightTimer);
          pdfAiQuestionGotoHighlightTimer = 0;
        }
        pdfAiQuestionGotoHighlightTimer = window.setTimeout(() => {
          pdfAiQuestionGotoHighlightId = "";
          pdfAiQuestionGotoHighlightTimer = 0;
          renderPdfAiQuestionNodeList({ keepScroll: true });
        }, 2800);
      };

      const updatePdfAiQuestionRightDragHover = (event) => {
        if (!pdfAiQuestionRightDragActive || !pdfEls || !pdfEls.aiQuestionNodeList) {
          return;
        }
        if (!event || !Number.isFinite(Number(event.clientX)) || !Number.isFinite(Number(event.clientY))) {
          return;
        }
        const target = document.elementFromPoint(event.clientX, event.clientY);
        const nodeButton = target && target.closest ? target.closest(".ft-pdf-ai-question-node") : null;
        const targetId = nodeButton && pdfEls.aiQuestionNodeList.contains(nodeButton) ? clean(nodeButton.dataset.questionNodeId || "") : "";
        pdfAiQuestionRightDragOverId = targetId && targetId !== clean(pdfAiQuestionDraggingNodeId) ? targetId : "";
        clearPdfAiQuestionNodeDropState();
        pdfEls.aiQuestionNodeList.classList.add("is-right-drag-active");
        const draggingNode = pdfEls.aiQuestionNodeList.querySelector(`.ft-pdf-ai-question-node[data-question-node-id="${CSS.escape(clean(pdfAiQuestionDraggingNodeId))}"]`);
        if (draggingNode) {
          draggingNode.classList.add("is-right-dragging");
        }
        if (pdfAiQuestionRightDragOverId) {
          const dropNode = pdfEls.aiQuestionNodeList.querySelector(`.ft-pdf-ai-question-node[data-question-node-id="${CSS.escape(pdfAiQuestionRightDragOverId)}"]`);
          if (dropNode) {
            dropNode.classList.add("is-drop-target");
          }
        }
      };

      const finishPdfAiQuestionRightDrag = (event) => {
        if (!pdfAiQuestionRightDragActive) {
          return;
        }
        if (event) {
          event.preventDefault();
          event.stopPropagation();
        }
        updatePdfAiQuestionRightDragHover(event || { clientX: 0, clientY: 0 });
        const sourceId = clean(pdfAiQuestionDraggingNodeId);
        const targetId = clean(pdfAiQuestionRightDragOverId);
        pdfAiQuestionDraggingNodeId = "";
        pdfAiQuestionRightDragActive = false;
        pdfAiQuestionRightDragOverId = "";
        clearPdfAiQuestionNodeDropState();
        if (sourceId && targetId && sourceId !== targetId) {
          movePdfAiQuestionEditorNodeBefore(sourceId, targetId);
        } else if (sourceId) {
          renderPdfAiQuestionNodeList({ keepScroll: true });
        }
      };

      // Added 2026-07-02: lets admins jump between MishiKa question nodes without scrolling the list.
      const focusPdfAiQuestionEditorNodeAt = (index = 0, options = {}) => {
        mergePdfAiQuestionEditorDraft();
        const nodes = Array.isArray(pdfAiQuestionEditorNodes) ? pdfAiQuestionEditorNodes : [];
        if (!nodes.length) {
          syncPdfAiQuestionNodeNavigator();
          return;
        }
        const targetIndex = Math.min(nodes.length - 1, Math.max(0, Math.floor(Number(index) || 0)));
        const target = nodes[targetIndex];
        if (!target) {
          return;
        }
        pdfAiQuestionEditingId = clean(target.id || "");
        flashPdfAiQuestionGotoNode(pdfAiQuestionEditingId);
        hydratePdfAiQuestionEditorNode(target);
        renderPdfAiQuestionNodeList({ keepScroll: true });
        scrollPdfAiQuestionEditorNodeIntoView(pdfAiQuestionEditingId);
        setPdfAiQuestionEditorStatus(`Question node ${targetIndex + 1}/${nodes.length} selected.`, "");
        if (options.focusInput && pdfEls && pdfEls.aiQuestionInput) {
          window.setTimeout(() => {
            try { pdfEls.aiQuestionInput.focus(); } catch (error) {}
          }, 20);
        }
      };

      const navigatePdfAiQuestionEditorNode = (direction = "") => {
        const nodes = Array.isArray(pdfAiQuestionEditorNodes) ? pdfAiQuestionEditorNodes : [];
        if (!nodes.length) {
          return;
        }
        const activeIndex = Math.max(0, nodes.findIndex((item) => clean(item && item.id || "") === clean(pdfAiQuestionEditingId)));
        if (direction === "first") {
          focusPdfAiQuestionEditorNodeAt(0);
        } else if (direction === "previous") {
          focusPdfAiQuestionEditorNodeAt(activeIndex - 1);
        } else if (direction === "next") {
          focusPdfAiQuestionEditorNodeAt(activeIndex + 1);
        } else if (direction === "end") {
          focusPdfAiQuestionEditorNodeAt(nodes.length - 1);
        }
      };

      // Added 2026-07-02: lets admins move a question node before another node by drag/drop.
      const movePdfAiQuestionEditorNodeBefore = (dragId = "", targetId = "") => {
        const sourceId = clean(dragId);
        const beforeId = clean(targetId);
        if (!sourceId || !beforeId || sourceId === beforeId) {
          clearPdfAiQuestionNodeDropState();
          return;
        }
        mergePdfAiQuestionEditorDraft();
        const nodes = Array.isArray(pdfAiQuestionEditorNodes) ? pdfAiQuestionEditorNodes.slice() : [];
        const sourceIndex = nodes.findIndex((item) => clean(item && item.id || "") === sourceId);
        if (sourceIndex < 0) {
          clearPdfAiQuestionNodeDropState();
          return;
        }
        const [moved] = nodes.splice(sourceIndex, 1);
        const targetIndex = nodes.findIndex((item) => clean(item && item.id || "") === beforeId);
        if (targetIndex < 0) {
          nodes.push(moved);
        } else {
          nodes.splice(targetIndex, 0, moved);
        }
        pdfAiQuestionEditorNodes = nodes;
        pdfAiQuestionEditingId = sourceId;
        pdfAiQuestionRightDragActive = false;
        pdfAiQuestionRightDragOverId = "";
        clearPdfAiQuestionNodeDropState();
        renderPdfAiQuestionNodeList({ keepScroll: true });
        syncPdfAiQuestionNodeNavigator();
        setPdfAiQuestionEditorStatus("Question node moved. Save to keep this order.", "");
      };

      const renderPdfAiQuestionNodeList = (options = {}) => {
        if (!pdfEls || !pdfEls.aiQuestionNodeList) {
          return;
        }
        const nodes = Array.isArray(pdfAiQuestionEditorNodes) ? pdfAiQuestionEditorNodes : [];
        const previousScrollTop = pdfEls.aiQuestionNodeList.scrollTop || 0;
        pdfEls.aiQuestionNodeList.replaceChildren();
        nodes.forEach((node, index) => {
          const button = document.createElement("button");
          button.type = "button";
          button.className = "ft-pdf-ai-question-node";
          button.draggable = false;
          button.dataset.questionNodeId = clean(node.id || "");
          button.classList.toggle("is-active", clean(node.id || "") === clean(pdfAiQuestionEditingId));
          button.classList.toggle("is-pinned", pdfAiQuestionNodeIsPinned(node));
          button.classList.toggle("is-goto-highlight", clean(node.id || "") === clean(pdfAiQuestionGotoHighlightId));
          button.classList.toggle("is-right-dragging", clean(node.id || "") === clean(pdfAiQuestionDraggingNodeId));
          button.classList.toggle("is-drop-target", clean(node.id || "") === clean(pdfAiQuestionRightDragOverId));
          const title = clean(node.question || node.title || `Question ${index + 1}`) || `Question ${index + 1}`;
          const intro = clean(node.mikasaIntro || "");
          const imageLabel = normalizePdfAiQuestionImageSrc(node.imageSrc || node.image_src || "") ? "Image | " : "";
          const regionLabel = clean(node.regionName || node.region_name || "") ? `Region: ${clean(node.regionName || node.region_name || "")} | ` : "";
          const pinnedLabel = pdfAiQuestionNodeIsPinned(node) ? `<em>PIN</em>` : "";
          button.innerHTML = `
            <strong><span class="ft-pdf-ai-question-node-title">${escapeHtml(`Q${index + 1}. ${title}`)}</span>${pinnedLabel}</strong>
            <span>${escapeHtml(`${regionLabel}${imageLabel}${intro || "Right-click drag to move this node"}`)}</span>
          `;
          button.addEventListener("click", () => {
            selectPdfAiQuestionEditorNode(button.dataset.questionNodeId || "", { focus: false });
          });
          button.addEventListener("contextmenu", (event) => {
            event.preventDefault();
            event.stopPropagation();
          });
          button.addEventListener("pointerdown", (event) => {
            if (!event || event.button !== 2) {
              return;
            }
            event.preventDefault();
            event.stopPropagation();
            pdfAiQuestionDraggingNodeId = button.dataset.questionNodeId || "";
            pdfAiQuestionRightDragOverId = "";
            pdfAiQuestionRightDragActive = true;
            try { button.setPointerCapture(event.pointerId); } catch (error) {}
            button.classList.add("is-dragging");
            button.classList.add("is-right-dragging");
            if (pdfEls.aiQuestionNodeList) {
              pdfEls.aiQuestionNodeList.classList.add("is-right-drag-active");
            }
          });
          pdfEls.aiQuestionNodeList.appendChild(button);
        });
        if (options.keepScroll) {
          pdfEls.aiQuestionNodeList.scrollTop = previousScrollTop;
        }
        syncPdfAiQuestionNodeNavigator();
      };

      const hydratePdfAiQuestionEditorNode = (node = null) => {
        const item = node || pdfAiQuestionBlankNode();
        if (pdfEls && pdfEls.aiQuestionRegionName) {
          pdfEls.aiQuestionRegionName.value = clean(item.regionName || item.region_name || "").slice(0, 120);
        }
        if (pdfEls && pdfEls.aiQuestionInput) {
          pdfEls.aiQuestionInput.value = preserveQuestionText(item.question || "");
          pdfEls.aiQuestionInput._pdfAiTextHighlights = normalizePdfAiTextHighlights(item.questionHighlights || [], pdfEls.aiQuestionInput.value || "");
          bindPdfAiQuestionHighlightTextarea(pdfEls.aiQuestionInput);
          renderPdfAiQuestionTextHighlightPreview(pdfEls.aiQuestionInput);
        }
        if (pdfEls && pdfEls.aiQuestionIntro) {
          pdfEls.aiQuestionIntro.value = preserveQuestionText(item.mikasaIntro || "");
          pdfEls.aiQuestionIntro._pdfAiTextHighlights = normalizePdfAiTextHighlights(item.mikasaIntroHighlights || [], pdfEls.aiQuestionIntro.value || "");
          bindPdfAiQuestionHighlightTextarea(pdfEls.aiQuestionIntro);
          renderPdfAiQuestionTextHighlightPreview(pdfEls.aiQuestionIntro);
        }
        if (pdfEls && pdfEls.aiQuestionIntroVoice) {
          pdfEls.aiQuestionIntroVoice.value = clean(item.voice || PDF_AI_QUESTION_DEFAULT_VOICE) || PDF_AI_QUESTION_DEFAULT_VOICE;
        }
        if (pdfEls && pdfEls.aiQuestionImageSrc) {
          setPdfAiQuestionEditorImage(item.imageSrc || item.image_src || "", { status: false });
        }
        if (pdfEls && pdfEls.aiQuestionType) {
          pdfEls.aiQuestionType.value = normalizePdfAiQuestionType(item.questionType || "choice");
        }
        if (pdfEls && pdfEls.aiQuestionMatchPercent) {
          pdfEls.aiQuestionMatchPercent.value = String(normalizePdfAiTypedMatchPercent(item.typedMatchPercent || 100));
        }
        if (pdfEls && pdfEls.aiQuestionRandomMode) {
          pdfEls.aiQuestionRandomMode.value = item.randomOrder ? "on" : "off";
        }
        if (pdfEls && pdfEls.aiQuestionPinNode) {
          pdfEls.aiQuestionPinNode.checked = pdfAiQuestionNodeIsPinned(item);
        }
        renderPdfAiQuestionAnswerRows(item && item.answers && item.answers.length ? item.answers : [
          { text: "", correct: true, explanationMode: "text_voice", explanationVoice: PDF_AI_QUESTION_DEFAULT_VOICE },
          { text: "", correct: false, explanationMode: "text_voice", explanationVoice: PDF_AI_QUESTION_DEFAULT_VOICE },
        ]);
        syncPdfAiQuestionNodeNavigator();
        resizePdfAiQuestionTextareas();
      };

      const selectPdfAiQuestionEditorNode = (nodeId = "", options = {}) => {
        mergePdfAiQuestionEditorDraft();
        const nodes = Array.isArray(pdfAiQuestionEditorNodes) ? pdfAiQuestionEditorNodes : [];
        const node = nodes.find((item) => clean(item && item.id || "") === clean(nodeId)) || nodes[0] || pdfAiQuestionBlankNode();
        if (!nodes.length) {
          pdfAiQuestionEditorNodes = [node];
        }
        pdfAiQuestionEditingId = clean(node.id || "");
        hydratePdfAiQuestionEditorNode(node);
        renderPdfAiQuestionNodeList({ keepScroll: true });
        setPdfAiQuestionEditorStatus(options.expand ? "Editing this question node. Right-click answer rows to edit explanations." : "Question node selected.", "");
        if (options.focus && pdfEls && pdfEls.aiQuestionInput) {
          window.setTimeout(() => {
            try { pdfEls.aiQuestionInput.focus(); } catch (error) {}
          }, 20);
        }
      };

      const addPdfAiQuestionNode = () => {
        mergePdfAiQuestionEditorDraft();
        const nodes = Array.isArray(pdfAiQuestionEditorNodes) ? pdfAiQuestionEditorNodes.slice() : [];
        if (nodes.length >= 12) {
          setPdfAiQuestionEditorStatus("Maximum 12 question nodes for one region.", "error");
          return;
        }
        const node = pdfAiQuestionBlankNode();
        nodes.push(node);
        pdfAiQuestionEditorNodes = nodes;
        pdfAiQuestionEditingId = node.id;
        hydratePdfAiQuestionEditorNode(node);
        renderPdfAiQuestionNodeList({ keepScroll: true });
        scrollPdfAiQuestionEditorNodeIntoView(pdfAiQuestionEditingId);
        syncPdfAiQuestionNodeNavigator();
        setPdfAiQuestionEditorStatus("New question node added. Right-click a node to edit its details.", "");
      };

      const copyPdfAiQuestionNode = () => {
        mergePdfAiQuestionEditorDraft();
        const nodes = Array.isArray(pdfAiQuestionEditorNodes) ? pdfAiQuestionEditorNodes.slice() : [];
        if (nodes.length >= 12) {
          setPdfAiQuestionEditorStatus("Maximum 12 question nodes for one region.", "error");
          return;
        }
        const activeIndex = nodes.findIndex((item) => clean(item && item.id || "") === clean(pdfAiQuestionEditingId));
        const source = activeIndex >= 0 ? nodes[activeIndex] : nodes[0];
        if (!source) {
          addPdfAiQuestionNode();
          return;
        }
        const cloned = clonePdfAiQuestionEditorNode(source);
        const insertIndex = activeIndex >= 0 ? activeIndex + 1 : nodes.length;
        nodes.splice(insertIndex, 0, cloned);
        pdfAiQuestionEditorNodes = nodes;
        pdfAiQuestionEditingId = cloned.id;
        hydratePdfAiQuestionEditorNode(cloned);
        renderPdfAiQuestionNodeList({ keepScroll: true });
        scrollPdfAiQuestionEditorNodeIntoView(pdfAiQuestionEditingId);
        syncPdfAiQuestionNodeNavigator();
        setPdfAiQuestionEditorStatus("Current question node copied. Save to keep the new node.", "ok");
      };

      const pdfAiQuestionAnswerTemplate = (answer = {}, index = 0) => ({
        id: clean(answer.id || "") || `answer-${index + 1}`,
        text: preserveQuestionText(answer.text || ""),
        correct: Boolean(answer.correct),
        explanationText: preserveQuestionText(answer.explanationText || answer.explanation_text || ""),
        explanationMode: clean(answer.explanationMode || answer.explanation_mode || "text_voice") || "text_voice",
        explanationVoice: clean(answer.explanationVoice || answer.explanation_voice || PDF_AI_QUESTION_DEFAULT_VOICE) || PDF_AI_QUESTION_DEFAULT_VOICE,
        explanationVoiceLabel: clean(answer.explanationVoiceLabel || answer.explanation_voice_label || ""),
        audioPath: clean(answer.audioPath || answer.audio_path || ""),
        audioMime: clean(answer.audioMime || answer.audio_mime || ""),
      });

      const closePdfAiQuestionExplanationPopups = (exceptRow = null) => {
        if (!pdfEls || !pdfEls.aiQuestionAnswerList) {
          return;
        }
        Array.from(pdfEls.aiQuestionAnswerList.querySelectorAll(".ft-pdf-ai-question-answer-row.is-expanded")).forEach((row) => {
          if (exceptRow && row === exceptRow) {
            return;
          }
          row.classList.remove("is-expanded");
        });
      };

      const positionPdfAiQuestionExplanationPopup = (row, event = null) => {
        if (!row || typeof row.getBoundingClientRect !== "function") {
          return;
        }
        const rect = row.getBoundingClientRect();
        const popupWidth = Math.min(360, Math.max(280, window.innerWidth - 24));
        const anchorX = event && Number.isFinite(event.clientX) ? event.clientX : rect.right;
        const anchorY = event && Number.isFinite(event.clientY) ? event.clientY : rect.top + rect.height * 0.5;
        const left = Math.min(Math.max(12, anchorX + 12), Math.max(12, window.innerWidth - popupWidth - 12));
        const top = Math.min(Math.max(12, anchorY - 28), Math.max(12, window.innerHeight - 250));
        row.style.setProperty("--ai-question-popup-left", `${left}px`);
        row.style.setProperty("--ai-question-popup-top", `${top}px`);
        row.style.setProperty("--ai-question-popup-width", `${popupWidth}px`);
      };

      const renderPdfAiQuestionAnswerRows = (answers = []) => {
        if (!pdfEls || !pdfEls.aiQuestionAnswerList) {
          return;
        }
        const rows = (Array.isArray(answers) && answers.length ? answers : [
          { text: "", correct: true, explanationMode: "text_voice" },
          { text: "", correct: false, explanationMode: "text_voice" },
        ]).slice(0, 8).map(pdfAiQuestionAnswerTemplate);
        pdfEls.aiQuestionAnswerList.replaceChildren();
        rows.forEach((answer, index) => {
          const row = document.createElement("div");
          row.className = "ft-pdf-ai-question-answer-row";
          row.dataset.answerIndex = String(index);
          row.dataset.answerId = answer.id;
          row.dataset.audioPath = answer.audioPath || "";
          row.dataset.audioMime = answer.audioMime || "";
          row.dataset.explanationVoiceLabel = answer.explanationVoiceLabel || "";
          row.innerHTML = `
            <div class="ft-pdf-ai-question-answer-main">
              <button class="ft-pdf-ai-question-correct" type="button" data-ai-question-correct aria-pressed="${answer.correct ? "true" : "false"}">${answer.correct ? "Correct" : "Wrong"}</button>
              <textarea class="ft-pdf-ai-question-answer-text" rows="2" spellcheck="false" placeholder="Answer option">${escapeHtml(answer.text)}</textarea>
              <button class="ft-pdf-ai-question-remove" type="button" data-ai-question-remove aria-label="Remove answer">x</button>
            </div>
            <div class="ft-pdf-ai-question-explain">
              <div class="ft-pdf-ai-question-explain-head">
                <span>Answer explanation</span>
                <button class="ft-pdf-ai-question-explain-close" type="button" data-ai-question-explain-close aria-label="Close explanation">x</button>
              </div>
              <textarea class="ft-pdf-ai-question-explain-text" rows="3" spellcheck="false" placeholder="Explanation for this answer">${escapeHtml(answer.explanationText)}</textarea>
              <div class="ft-pdf-ai-question-explain-tools">
                <select class="ft-pdf-ai-question-explain-mode" aria-label="Explanation mode">
                  <option value="text">Text only</option>
                  <option value="voice">Voice only</option>
                  <option value="text_voice">Text + voice</option>
                </select>
                <select class="ft-pdf-ai-question-explain-voice" aria-label="Explanation voice">
                  <option value="kokoro:af_jessica">People | Female Jessica</option>
                  <option value="kokoro:am_adam">People | Male Adam</option>
                  <option value="kokoro_vi:diem_trinh">Kokoro VI | Diem Trinh</option>
                  <option value="kokoro_vi:hung_thinh">Kokoro VI | Hung Thinh</option>
                  <option value="kokoro_vi:mai_linh">Kokoro VI | Mai Linh</option>
                  <option value="kokoro_vi:ngoc_huyen">Kokoro VI | Ngoc Huyen</option>
                  <option value="edge:en-US-JennyNeural">Edge | English US | Jenny</option>
                  <option value="edge:vi-VN-HoaiMyNeural">Edge | Vietnamese VN | Hoai My</option>
                </select>
              </div>
            </div>
          `;
          const mode = row.querySelector(".ft-pdf-ai-question-explain-mode");
          const voice = row.querySelector(".ft-pdf-ai-question-explain-voice");
          if (mode) {
            mode.value = ["text", "voice", "text_voice"].includes(answer.explanationMode) ? answer.explanationMode : "text_voice";
          }
          if (voice) {
            voice.value = answer.explanationVoice;
          }
          row.classList.toggle("is-correct", answer.correct);
          row.addEventListener("contextmenu", (event) => {
            event.preventDefault();
            event.stopPropagation();
            closePdfAiQuestionExplanationPopups(row);
            positionPdfAiQuestionExplanationPopup(row, event);
            row.classList.toggle("is-expanded", true);
            const target = row.querySelector(".ft-pdf-ai-question-explain-text");
          if (target) {
            target.focus();
            resizePdfAiQuestionTextarea(target);
          }
          });
          const correctButton = row.querySelector("[data-ai-question-correct]");
          if (correctButton) {
            correctButton.addEventListener("click", () => {
              const active = correctButton.getAttribute("aria-pressed") !== "true";
              correctButton.setAttribute("aria-pressed", active ? "true" : "false");
              correctButton.textContent = active ? "Correct" : "Wrong";
              row.classList.toggle("is-correct", active);
            });
          }
          const closeButton = row.querySelector("[data-ai-question-explain-close]");
          if (closeButton) {
            closeButton.addEventListener("click", (event) => {
              event.preventDefault();
              event.stopPropagation();
              row.classList.remove("is-expanded");
            });
          }
          const removeButton = row.querySelector("[data-ai-question-remove]");
          if (removeButton) {
            removeButton.addEventListener("click", () => {
              row.remove();
            });
          }
          pdfEls.aiQuestionAnswerList.appendChild(row);
        });
        resizePdfAiQuestionTextareas(pdfEls.aiQuestionAnswerList);
      };

      const addPdfAiQuestionAnswerRow = () => {
        const answers = collectPdfAiQuestionAnswers({ allowEmpty: true });
        if (answers.length >= 8) {
          setPdfAiQuestionEditorStatus("Maximum 8 answers.", "error");
          return;
        }
        answers.push({ text: "", correct: false, explanationMode: "text_voice", explanationVoice: PDF_AI_QUESTION_DEFAULT_VOICE });
        renderPdfAiQuestionAnswerRows(answers);
        resizePdfAiQuestionTextareas();
      };

      const collectPdfAiQuestionAnswers = (options = {}) => {
        if (!pdfEls || !pdfEls.aiQuestionAnswerList) {
          return [];
        }
        return Array.from(pdfEls.aiQuestionAnswerList.querySelectorAll(".ft-pdf-ai-question-answer-row")).map((row, index) => {
          const text = preserveQuestionText(row.querySelector(".ft-pdf-ai-question-answer-text") && row.querySelector(".ft-pdf-ai-question-answer-text").value || "");
          const explanationText = preserveQuestionText(row.querySelector(".ft-pdf-ai-question-explain-text") && row.querySelector(".ft-pdf-ai-question-explain-text").value || "");
          const explanationMode = clean(row.querySelector(".ft-pdf-ai-question-explain-mode") && row.querySelector(".ft-pdf-ai-question-explain-mode").value || "text_voice") || "text_voice";
          const explanationVoice = clean(row.querySelector(".ft-pdf-ai-question-explain-voice") && row.querySelector(".ft-pdf-ai-question-explain-voice").value || PDF_AI_QUESTION_DEFAULT_VOICE) || PDF_AI_QUESTION_DEFAULT_VOICE;
          return {
            id: clean(row.dataset.answerId || "") || `answer-${index + 1}`,
            text,
            correct: row.classList.contains("is-correct"),
            explanationText,
            explanationMode,
            explanationVoice,
            explanationVoiceLabel: clean(row.dataset.explanationVoiceLabel || ""),
            audioPath: clean(row.dataset.audioPath || ""),
            audioMime: clean(row.dataset.audioMime || ""),
          };
        }).filter((answer) => options.allowEmpty || answer.text);
      };

      const openPdfAiQuestionEditor = async () => {
        if (!currentAuthIsAdmin) {
          setPdfStatus("Only admin can set AI questions.", true);
          return;
        }
        const rect = getPdfAiNoticeRect();
        if (!rect) {
          setPdfStatus("Select a Ghost Eye region first.", true);
          return;
        }
        if (!pdfEls || !pdfEls.aiQuestionModal || !pdfEls.aiQuestionInput) {
          return;
        }
        hidePdfAiQuestionEditorMinimizedButton();
        hidePdfAiNoticeFireball({ immediate: true });
        hidePdfAiQuestionPanel();
        const existingNodes = pdfAiQuestionsForSelection();
        const existing = existingNodes.find((item) => clean(item && item.id || "") === clean(pdfAiQuestionEditingId)) || existingNodes[0] || null;
        pdfAiQuestionEditorNodes = existingNodes.length ? existingNodes.map((item) => ({ ...item })) : [pdfAiQuestionBlankNode()];
        pdfAiQuestionEditingId = clean(existing && existing.id || pdfAiQuestionEditorNodes[0].id || "");
        hydratePdfAiQuestionEditorNode(pdfAiQuestionEditorNodes.find((item) => clean(item && item.id || "") === clean(pdfAiQuestionEditingId)) || pdfAiQuestionEditorNodes[0]);
        renderPdfAiQuestionNodeList();
        pdfEls.aiQuestionModal.classList.remove("is-hidden");
        pdfEls.aiQuestionModal.setAttribute("aria-hidden", "false");
        setPdfAiQuestionEditorStatus(existingNodes.length ? "Editing question nodes for this region. Right-click a node to edit its details." : "New question node for this region. Right-click answer rows to add explanations.", "");
        window.setTimeout(() => {
          try { pdfEls.aiQuestionInput.focus(); } catch (error) {}
        }, 40);
      };

      const closePdfAiQuestionEditor = () => {
        if (!pdfEls || !pdfEls.aiQuestionModal) {
          return;
        }
        hidePdfAiQuestionEditorMinimizedButton();
        closePdfAiQuestionExplanationPopups();
        pdfEls.aiQuestionModal.classList.add("is-hidden");
        pdfEls.aiQuestionModal.setAttribute("aria-hidden", "true");
      };

      // Added 2026-07-02: lets admins temporarily hide the Set AI Question editor without losing draft state.
      const ensurePdfAiQuestionEditorMinimizedButton = () => {
        let button = document.getElementById("ft-pdf-ai-question-editor-mini-return");
        if (button) {
          return button;
        }
        button = document.createElement("button");
        button.id = "ft-pdf-ai-question-editor-mini-return";
        button.className = "ft-pdf-ai-question-editor-mini-return is-hidden";
        button.type = "button";
        button.setAttribute("aria-label", "Restore AI question editor");
        button.innerHTML = `<span></span><b>Set AI question</b>`;
        button.addEventListener("click", () => restorePdfAiQuestionEditor());
        document.body.appendChild(button);
        return button;
      };

      // Added 2026-07-02: hides the Set AI Question editor into a restore chip while preserving current inputs.
      const minimizePdfAiQuestionEditor = () => {
        if (!pdfEls || !pdfEls.aiQuestionModal) {
          return;
        }
        mergePdfAiQuestionEditorDraft();
        hidePdfAiQuestionHighlightPalette();
        closePdfAiQuestionExplanationPopups();
        pdfEls.aiQuestionModal.classList.add("is-hidden");
        pdfEls.aiQuestionModal.setAttribute("aria-hidden", "true");
        const button = ensurePdfAiQuestionEditorMinimizedButton();
        button.classList.remove("is-hidden");
      };

      // Added 2026-07-02: restores the Set AI Question editor from its minimized chip.
      const restorePdfAiQuestionEditor = () => {
        if (!pdfEls || !pdfEls.aiQuestionModal) {
          return;
        }
        hidePdfAiQuestionEditorMinimizedButton();
        pdfEls.aiQuestionModal.classList.remove("is-hidden");
        pdfEls.aiQuestionModal.setAttribute("aria-hidden", "false");
        renderPdfAiQuestionNodeList();
        resizePdfAiQuestionTextareas(pdfEls.aiQuestionModal);
        window.setTimeout(() => {
          try { pdfEls.aiQuestionInput && pdfEls.aiQuestionInput.focus(); } catch (error) {}
        }, 40);
      };

      // Added 2026-07-02: clears the Set AI Question editor restore chip on real close/open paths.
      const hidePdfAiQuestionEditorMinimizedButton = () => {
        const button = document.getElementById("ft-pdf-ai-question-editor-mini-return");
        if (button) {
          button.classList.add("is-hidden");
        }
      };

      const savePdfAiRegionQuestion = async () => {
        if (!currentAuthIsAdmin) {
          setPdfAiQuestionEditorStatus("Only admin can set AI questions.", "error");
          return;
        }
        const rect = getPdfAiNoticeRect();
        if (!rect) {
          setPdfAiQuestionEditorStatus("Select a region first.", "error");
          return;
        }
        mergePdfAiQuestionEditorDraft();
        const nodes = (Array.isArray(pdfAiQuestionEditorNodes) ? pdfAiQuestionEditorNodes : [])
          .map((node) => ({
            ...node,
            question: preserveQuestionText(node && node.question || ""),
            imageSrc: normalizePdfAiQuestionImageSrc(node && (node.imageSrc || node.image_src) || ""),
            imageAlt: clean(node && (node.imageAlt || node.image_alt) || ""),
            questionHighlights: normalizePdfAiTextHighlights(node && node.questionHighlights || [], node && node.question || ""),
            questionType: normalizePdfAiQuestionType(node && node.questionType || "choice"),
            typedMatchPercent: normalizePdfAiTypedMatchPercent(node && node.typedMatchPercent || 100),
            randomOrder: Boolean(node && node.randomOrder),
            pinned: pdfAiQuestionNodeIsPinned(node),
            mikasaIntro: preserveQuestionText(node && node.mikasaIntro || ""),
            mikasaIntroHighlights: normalizePdfAiTextHighlights(node && node.mikasaIntroHighlights || [], node && node.mikasaIntro || ""),
            voice: clean(node && node.voice || PDF_AI_QUESTION_DEFAULT_VOICE) || PDF_AI_QUESTION_DEFAULT_VOICE,
            answers: (Array.isArray(node && node.answers) ? node.answers : [])
              .map((answer, index) => pdfAiQuestionAnswerTemplate(answer, index))
              .filter((answer) => answer.text),
          }))
          .filter((node) => node.question || node.answers.length);
        if (!nodes.length) {
          setPdfAiQuestionEditorStatus("Enter at least one question node.", "error");
          return;
        }
        const invalidNodeIndex = nodes.findIndex((node) => !node.question || (normalizePdfAiQuestionType(node.questionType) === "choice" && node.answers.length > 0 && node.answers.length < 2));
        if (invalidNodeIndex >= 0) {
          setPdfAiQuestionEditorStatus(`Question node ${invalidNodeIndex + 1} needs a question. Choice nodes need at least 2 answers; input/speak nodes can use 1 answer.`, "error");
          selectPdfAiQuestionEditorNode(nodes[invalidNodeIndex].id || "", { focus: true });
          return;
        }
        nodes.forEach((node) => {
          if (node.answers.length && !node.answers.some((answer) => answer.correct)) {
            node.answers[0].correct = true;
          }
        });
        const randomOrder = Boolean(pdfEls && pdfEls.aiQuestionRandomMode && pdfEls.aiQuestionRandomMode.value === "on");
        const regionName = syncPdfAiQuestionRegionNameToEditorNodes(pdfEls && pdfEls.aiQuestionRegionName ? pdfEls.aiQuestionRegionName.value : (nodes[0] && nodes[0].regionName || ""));
        nodes.forEach((node) => {
          node.randomOrder = randomOrder;
          node.regionName = regionName;
        });
        const scope = currentPdfAiRegionNoticeScope();
        const missingAudioJobs = collectPdfAiQuestionMissingAudioJobs(nodes);
        if (missingAudioJobs.length) {
          setPdfAiQuestionEditorStatus(`Saving ${nodes.length} AI question node${nodes.length > 1 ? "s" : ""}. Missing audio: ${missingAudioJobs.length} file${missingAudioJobs.length > 1 ? "s" : ""}.\n${missingAudioJobs.slice(0, 5).map((job) => `- ${job.label}`).join("\n")}`, "");
        } else {
          setPdfAiQuestionEditorStatus(`Saving ${nodes.length} AI question node${nodes.length > 1 ? "s" : ""}. No missing audio to build.`, "");
        }
        if (typeof setTopOperationStatus === "function") {
          setTopOperationStatus(missingAudioJobs.length ? `Saving MishiKa questions and building ${missingAudioJobs.length} missing audio file${missingAudioJobs.length > 1 ? "s" : ""}...` : `Saving ${nodes.length} MishiKa question node${nodes.length > 1 ? "s" : ""}...`, {
            working: true,
            progress: 0.3,
            autoHideMs: 1400,
          });
        }
        try {
          let latestPayload = null;
          for (let saveIndex = 0; saveIndex < nodes.length; saveIndex += 1) {
            const node = nodes[saveIndex];
            setPdfAiQuestionAudioBuildStatus(missingAudioJobs, saveIndex, saveIndex, nodes.length);
            const nodeId = clean(node.id || "");
            const timeoutMs = (node.mikasaIntro || node.answers.some((answer) => answer.explanationText && answer.explanationMode !== "text")) ? 180000 : 20000;
            const { payload } = await fetchAuthJson("/space-pdf/ai-region-questions?client_source=pdf_ai_question_mutation", {
              method: "POST",
              timeoutMs,
              body: JSON.stringify({
                ...scope,
                id: nodeId && !nodeId.startsWith("draft-") ? nodeId : "",
                rect: { x: rect.x, y: rect.y, w: rect.w, h: rect.h },
                unionRects: rect.unionRects && rect.unionRects.length ? rect.unionRects : (node.unionRects && node.unionRects.length ? node.unionRects : []),
                regionName: node.regionName,
                question: node.question,
                imageSrc: node.imageSrc,
                imageAlt: node.imageAlt,
                questionHighlights: node.questionHighlights,
                questionType: node.questionType,
                typedMatchPercent: node.typedMatchPercent,
                randomOrder: node.randomOrder,
                pinned: node.pinned,
                mikasaIntro: node.mikasaIntro,
                mikasaIntroHighlights: node.mikasaIntroHighlights,
                voice: node.voice,
                answers: node.answers,
              }),
            });
            latestPayload = payload || latestPayload;
            if (missingAudioJobs.length) {
              const finishedCount = missingAudioJobs.filter((job) => job.nodeIndex <= saveIndex).length;
              setPdfAiQuestionEditorStatus(`Saved node ${saveIndex + 1}/${nodes.length}. Missing audio built/checked: ${finishedCount}/${missingAudioJobs.length}.`, "");
            }
          }
          applyPdfAiRegionQuestionPayload(latestPayload || {});
          const latest = pdfAiQuestionsForSelection();
          pdfAiQuestionEditorNodes = latest.length ? latest.map((item) => ({ ...item })) : [];
          pdfAiQuestionEditingId = clean((latest.find((item) => item.question === nodes[0].question) || latest[latest.length - 1] || {}).id || "");
          closePdfAiQuestionEditor();
          setPdfStatus(`${nodes.length} AI question node${nodes.length > 1 ? "s" : ""} set for this Ghost Eye region.`);
          if (typeof setTopOperationStatus === "function") {
            setTopOperationStatus("MishiKa question settings saved.", {
              progress: 1,
              autoHideMs: 2200,
            });
          }
        } catch (error) {
          const message = error && error.message ? error.message : "Could not save AI question.";
          setPdfAiQuestionEditorStatus(message, "error");
          if (typeof setTopOperationStatus === "function") {
            setTopOperationStatus(`MishiKa save failed: ${message}`, {
              isError: true,
              autoHideMs: 7200,
            });
          }
        }
      };

      const deletePdfAiRegionQuestion = async () => {
        if (!currentAuthIsAdmin) {
          setPdfAiQuestionEditorStatus("Only admin can delete AI questions.", "error");
          return;
        }
        const rect = getPdfAiNoticeRect();
        const existing = currentPdfAiQuestionForSelection();
        if (!rect || !existing || !existing.id) {
          setPdfAiQuestionEditorStatus("This region has no saved AI question yet.", "error");
          return;
        }
        const scope = currentPdfAiRegionNoticeScope();
        setPdfAiQuestionEditorStatus("Deleting AI question...", "");
        try {
          const { payload } = await fetchAuthJson("/space-pdf/ai-region-questions?client_source=pdf_ai_question_mutation", {
            method: "POST",
            body: JSON.stringify({ ...scope, id: existing.id, rect, action: "delete" }),
          });
          applyPdfAiRegionQuestionPayload(payload || {});
          closePdfAiQuestionEditor();
          hidePdfAiQuestionPanel();
          setPdfStatus("AI question removed for this region.");
        } catch (error) {
          setPdfAiQuestionEditorStatus(error && error.message ? error.message : "Could not delete AI question.", "error");
        }
      };

